 79→export async function loadLatestManifestEntry(
 80→  workspaceRoot: string,
 81→): Promise<ManifestVersionEntry | null> {
 82→  const manifestPath = path.join(workspaceRoot, MANIFEST_PATH);
 83→  try {
 84→    const raw = await fs.readFile(manifestPath, "utf-8");
 85→    const manifest: Manifest = JSON.parse(raw);
 86→    const versions = manifest.versions ?? [];
 87→    if (versions.length === 0) return null;
 88→    return versions[versions.length - 1];
 89→  } catch {
 90→    return null;
 91→  }
