136→export function computeGroundingDistribution(nodes: BaselineNode[]): Record<string, Record<string, number>> {
137→  const dist: Record<string, Record<string, number>> = {};
138→  for (const t of NODE_TYPES) {
139→    const row: Record<string, number> = { total: 0 };
140→    for (const a of AUTHORITY_VALUES) row[a] = 0;
141→    dist[t] = row;
142→  }
143→  for (const node of nodes) {
144→    const row = dist[node.type ?? ""];
145→    if (!row) continue;
146→    row.total++;
147→    const authority = node.grounding?.authority ?? "ai_inferred";
148→    row[authority] = (row[authority] ?? 0) + 1;
149→  }
150→  return dist;
151→}
