153→/**
154→ * Compute orphaned node counts. When `filterIds` is provided, only those nodes
155→ * are checked for orphan status, but edge connectivity is resolved against ALL
156→ * nodes so that a changed node connected to an intact node is not falsely orphaned.
157→ */
158→export function computeOrphanedNodes(
159→  nodes: BaselineNode[],
160→  edges: BaselineEdge[],
161→  filterIds?: Set<string>,
162→): Record<string, Record<string, number>> {
163→  const nodeTypeMap = new Map<string, string>();
164→  for (const n of nodes) {
165→    if (n.id && n.type) nodeTypeMap.set(n.id, n.type);
166→  }
167→  const connectedTypes = new Map<string, Set<string>>();
168→  for (const e of edges) {
169→    if (!e.source || !e.target) continue;
170→    const st = nodeTypeMap.get(e.source);
171→    const tt = nodeTypeMap.get(e.target);
172→    if (!st || !tt) continue;
173→    if (!connectedTypes.has(e.source)) connectedTypes.set(e.source, new Set());
174→    if (!connectedTypes.has(e.target)) connectedTypes.set(e.target, new Set());
175→    connectedTypes.get(e.source)!.add(tt);
176→    connectedTypes.get(e.target)!.add(st);
177→  }
178→  const result: Record<string, Record<string, number>> = {};
179→  for (const rt of NODE_TYPES) {
180→    const row: Record<string, number> = {};
181→    for (const ct of NODE_TYPES) {
182→      if (rt !== ct) row[ct] = 0;
183→    }
184→    result[rt] = row;
185→  }
186→  const nodesToCount = filterIds
187→    ? nodes.filter((n) => n.id && filterIds.has(n.id))
188→    : nodes;
189→  for (const n of nodesToCount) {
190→    const nt = n.type ?? "";
191→    if (!(nt in result)) continue;
192→    const connected = n.id ? connectedTypes.get(n.id) : undefined;
193→    for (const ct of NODE_TYPES) {
194→      if (ct === nt) continue;
195→      if (!connected || !connected.has(ct)) result[nt][ct]++;
196→    }
197→  }
198→  return result;
199→}
