205→/** Returns the absolute path to the latest version's analysis/ directory, or null. */
206→export async function getLatestAnalysisDir(workspaceRoot: string): Promise<string | null> {
207→  // Versioned path (from manifest)
208→  const entry = await loadLatestManifestEntry(workspaceRoot);
209→  if (entry) {
210→    // entry.path is e.g. "v1/appgraph-project.json" — parent is the version dir
211→    const versionDir = path.dirname(path.join(workspaceRoot, VERSIONS_DIR, entry.path));
212→    const analysisDir = path.join(versionDir, "analysis");
213→    try {
214→      await fs.access(analysisDir);
215→      return analysisDir;
216→    } catch {
217→      // Fall through to baseline
218→    }
219→  }
220→
221→  // Baseline fallback
222→  const baselineAnalysisDir = path.join(workspaceRoot, ".alucify", "analysis");
223→  try {
224→    await fs.access(baselineAnalysisDir);
225→    return baselineAnalysisDir;
226→  } catch {
227→    return null;
228→  }
229→}
