231→/** Finds the congruency markdown report for an artifact (V2 then V1), or null. */
232→export async function findCongruencyReport(
233→  analysisDir: string,
234→  artName: string,
235→): Promise<string | null> {
236→  try {
237→    const entries = await fs.readdir(analysisDir);
238→
239→    // V2 naming: congruency-v2-{name}.md
240→    const v2Name = `congruency-v2-${artName}.md`;
241→    if (entries.includes(v2Name)) {
242→      return path.join(analysisDir, v2Name);
243→    }
244→
245→    // V1 naming: congruency-analysis-{name}-v*.md (latest version)
246→    const v1Prefix = `congruency-analysis-${artName}-v`;
247→    const v1Matches = entries
248→      .filter((e) => e.startsWith(v1Prefix) && e.endsWith(".md"))
249→      .sort();
250→    if (v1Matches.length > 0) {
251→      return path.join(analysisDir, v1Matches[v1Matches.length - 1]);
252→    }
253→
254→    return null;
255→  } catch {
256→    return null;
257→  }
258→}
