195→async function loadContextData(workspaceRoot: string): Promise<ContextData> {
196→  const hasBaseline = await checkBaselineExists(workspaceRoot);
197→  const { changedArtifactCount, unanalyzedArtifactCount } =
198→    await countArtifactStatesFromManifest(workspaceRoot);
199→
200→  // Build metric history from all manifest versions
201→  const allEntries = await loadAllManifestEntries(workspaceRoot);
202→  const metricHistory = buildMetricHistory(allEntries);
203→
204→  const entry = await loadLatestManifestEntry(workspaceRoot);
205→  if (entry) {
206→    let artifactCount = entry.artifact_count ?? 0;
207→    let blastRadius = 0;
208→    let groundingPct = 0;
209→    let congruencyPct = -1;
210→    let projectMode = "";
211→
212→    try {
213→      const appgraphPath = path.join(workspaceRoot, VERSIONS_DIR, entry.path);
214→      const raw = await fs.readFile(appgraphPath, "utf-8");
215→      const ag = JSON.parse(raw) as Record<string, unknown>;
216→      const meta = ag.metadata as Record<string, unknown> | undefined;
217→      if (meta) {
218→        if (typeof meta.project_mode === "string") {
219→          projectMode = meta.project_mode;
220→        }
221→        const refs = meta.artifact_references;
222→        if (Array.isArray(refs)) artifactCount = refs.length;
223→
224→        const stats = meta.stats as Record<string, unknown> | undefined;
225→        if (stats) {
226→          const impact = stats.impact as Record<string, unknown> | undefined;
227→          if (impact && typeof impact.blast_radius === "number") {
228→            blastRadius = impact.blast_radius;
229→          }
230→          const grounding = stats.grounding as Record<string, Record<string, unknown>> | undefined;
231→          if (grounding?.overall && typeof grounding.overall.grounding_pct === "number") {
232→            groundingPct = grounding.overall.grounding_pct;
233→          }
234→          const congruency = stats.congruency as Record<string, unknown> | undefined;
235→          if (congruency) {
236→            if (typeof congruency.congruency_score === "number") {
237→              // Use severity-weighted score (stored as 0-100, convert to 0-1 ratio)
238→              congruencyPct = Math.round(congruency.congruency_score * 100) / 10000;
239→            } else if (typeof congruency.total_nodes_affected === "number") {
240→              // Fallback: unweighted node-affected ratio
241→              const totalNodes = entry.node_count;
242→              congruencyPct = totalNodes > 0
243→                ? Math.round((1 - congruency.total_nodes_affected / totalNodes) * 10000) / 10000
244→                : -1;
245→            }
246→          }
247→        }
248→      }
249→    } catch {
250→      // Appgraph file not found — use manifest totals
251→    }
252→
253→    const analysisDir = await getLatestAnalysisDir(workspaceRoot);
254→    const impactReportPath = analysisDir ? await findImpactReport(analysisDir) : null;
255→    const coverageReportPath = analysisDir ? await findCoverageReport(analysisDir) : null;
256→    const congruencyReportPath = analysisDir ? await findCongruencyBatchReport(analysisDir) : null;
257→    const synthesisReportPath = analysisDir ? await findQualitySynthesisReport(analysisDir) : null;
258→    const { topActions: synthesisTopActions, totalActions: synthesisTotalActions } =
259→      analysisDir ? await loadSynthesisActions(analysisDir) : { topActions: [], totalActions: 0 };
260→
261→    return {
262→      versionLabel: entry.version,
263→      versionDate: entry.created_at ? formatDate(entry.created_at) : "",
264→      hasStats: true,
265→      hasBaseline,
266→      changedArtifactCount,
267→      hasProjectAppgraph: true,
268→      hasClaudeCli: detectClaudeCli(),
269→      hasAnyArtifacts: false,
270→      hasCode: false,
271→      artifactCount,
272→      blastRadius,
273→      groundingPct,
274→      congruencyPct,
275→      projectMode,
276→      impactReportPath,
277→      coverageReportPath,
278→      congruencyReportPath,
279→      synthesisReportPath,
280→      synthesisTopActions,
281→      synthesisTotalActions,
282→      unanalyzedArtifactCount,
283→      metricHistory,
284→    };
285→  }
286→
287→  const baseline = await loadBaseline(workspaceRoot);
288→  if (baseline) {
289→    // Extract version and date from the baseline JSON and manifest
290→    const baselineRaw = baseline as unknown as Record<string, unknown>;
291→    const generatedAt = typeof baselineRaw.generated_at === "string" ? baselineRaw.generated_at : "";
292→    let baselineVersion = "Baseline";
293→    try {
