  80→function generateV2Markdown(
  81→  artifactName: string,
  82→  status: string,
  83→  issues: CongruencyIssue[],
  84→  severity: { critical: number; major: number; minor: number },
  85→  layerSummary: Record<string, Record<string, number>>,
  86→): string {
  87→  const lines: string[] = [];
  88→  lines.push(`# ${artifactName} Congruency Report (V2)\n`);
  89→
  90→  lines.push("## Executive Summary\n");
  91→  lines.push(`**Status**: ${status}\n`);
  92→  lines.push(
  93→    `**Total Issues**: ${issues.length} ` +
  94→    `(Critical: ${severity.critical}, ` +
  95→    `Major: ${severity.major}, ` +
  96→    `Minor: ${severity.minor})\n`,
  97→  );
  98→
  99→  lines.push("## Analysis Layers\n");
 100→  lines.push("| Layer | Detail |");
 101→  lines.push("|-------|--------|");
 102→  lines.push(`| Intra-Artifact | ${layerSummary.intra?.findings ?? 0} findings |`);
 103→  const l1 = layerSummary.layer1;
 104→  if (l1) {
 105→    lines.push(`| Layer 1 Mechanical | ${l1.strong ?? 0} strong, ${l1.partial ?? 0} partial, ${l1.additions ?? 0} additions, ${l1.uncovered ?? 0} uncovered |`);
 106→  }
 107→  lines.push(`| Layer 2 LLM | ${layerSummary.layer2?.classified ?? 0} classified |`);
 108→  lines.push(`| Layer 3 Holistic | ${layerSummary.layer3?.findings ?? 0} findings |`);
 109→  lines.push("");
 110→
 111→  if (issues.length === 0) {
 112→    lines.push("No congruency issues found.\n");
 113→    return lines.join("\n");
 114→  }
 115→
 116→  // Group issues by severity
 117→  for (const sev of ["critical", "major", "minor"] as const) {
 118→    const sevIssues = issues.filter((i) => (i.severity ?? "minor").toLowerCase() === sev);
 119→    if (sevIssues.length === 0) continue;
 120→    lines.push(`## ${sev.charAt(0).toUpperCase() + sev.slice(1)} Issues (${sevIssues.length})\n`);
 121→    for (const issue of sevIssues) {
 122→      const layerLabel = LAYER_LABELS[issue.layer ?? -1] ?? `Layer ${issue.layer}`;
 123→      lines.push(`### [${issue.id ?? "?"}] ${issue.title ?? "Untitled"}\n`);
 124→      lines.push(`**Layer**: ${layerLabel} | **Dimension**: ${issue.dimension ?? "N/A"}\n`);
 125→      if (issue.description) {
 126→        lines.push(`\n${issue.description}\n`);
 127→      }
 128→    }
 129→  }
 130→
 131→  return lines.join("\n");
 132→}
