 134→function mechanicalStep(
 135→  id: string,
 136→  name: string,
 137→  fn: (ctx: StepContext) => Promise<Record<string, unknown> | void>,
 138→): Step {
 139→  return {
 140→    id,
 141→    name,
 142→    mode: "sequential",
 143→    async execute(ctx: StepContext): Promise<StepResult> {
 144→      try {
 145→        const data = await fn(ctx);
 146→        return { status: "success", data: (data as Record<string, unknown>) ?? {} };
 147→      } catch (err) {
 148→        return { status: "error", error: String(err) };
 149→      }
 150→    },
 151→  };
 152→}
