 154→async function findLatestAppGraph(
 155→  workspaceRoot: string,
 156→): Promise<{ version: string; appgraphPath: string }> {
 157→  const manifestPath = path.join(workspaceRoot, MANIFEST_PATH);
 158→
 159→  try {
 160→    const raw = await fs.readFile(manifestPath, "utf-8");
 161→    const manifest = JSON.parse(raw);
 162→    const versions = manifest.versions ?? [];
 163→    if (versions.length === 0) throw new Error("Manifest has no versions");
 164→    const latest = versions[versions.length - 1];
 165→    return {
 166→      version: latest.version,
 167→      appgraphPath: path.join(workspaceRoot, VERSIONS_DIR, latest.path),
 168→    };
 169→  } catch (err) {
 170→    const baselinePath = path.join(workspaceRoot, BASELINE_PATH);
 171→    try {
 172→      await fs.access(baselinePath);
 173→      return { version: "baseline", appgraphPath: baselinePath };
 174→    } catch {
 175→      throw new Error(
 176→        `No manifest or baseline AppGraph found. Run Update Project Context first. (${String(err)})`,
 177→      );
 178→    }
 179→  }
 180→}
