 182→async function verifyAndRetry(
 183→  calls: AgentCall[],
 184→  sctx: StepContext,
 185→  label: string,
 186→): Promise<void> {
 187→  const missing: AgentCall[] = [];
 188→  for (const call of calls) {
 189→    if (!call.outputFile) continue;
 190→    try {
 191→      await fs.access(call.outputFile);
 192→    } catch {
 193→      missing.push(call);
 194→    }
 195→  }
 196→
 197→  if (missing.length === 0) return;
 198→
 199→  sctx.emitter.emit({
 200→    type: "log",
 201→    level: "warn",
 202→    message: `${label}: retrying ${missing.length} agent(s) that did not write output`,
 203→  });
 204→
 205→  const retryCalls = missing.map((c) => ({ ...c, maxToolTurns: undefined }));
 206→  const retryResults = await sctx.agentRunner.runAgentsParallel(
 207→    retryCalls,
 208→    sctx.tools,
 209→    sctx.emitter,
 210→    sctx.signal,
 211→    5,
 212→  );
 213→  for (const r of retryResults) {
 214→    trackAgentResult(sctx.state, r);
 215→  }
 216→
 217→  const stillMissing: string[] = [];
 218→  for (const call of missing) {
 219→    if (!call.outputFile) continue;
 220→    try {
 221→      await fs.access(call.outputFile);
 222→    } catch {
 223→      stillMissing.push(call.outputFile);
 224→    }
 225→  }
 226→  if (stillMissing.length > 0) {
 227→    throw new Error(
 228→      `${label}: ${stillMissing.length} agent(s) still missing output after retry: ${stillMissing.map((f) => path.basename(f)).join(", ")}`,
 229→    );
 230→  }
 231→}
