 233→/**
 234→ * Convert Layer 2 classifications into congruency issues.
 235→ *
 236→ * @param pairIdMap — Maps pair_id (from buildLayer2Batches) to the partial match entry.
 237→ *                    Built by the caller from Layer2Batch pairs to avoid fragile index arithmetic.
 238→ */
 239→function layer2ClassificationsToIssues(
 240→  classifications: Array<{
 241→    pair_id: number;
 242→    classification: string;
 243→    confidence?: number;
 244→    severity?: string;
 245→    reasoning?: string;
 246→    downstream_impact?: string;
 247→    dimension?: string;
 248→  }>,
 249→  artifactName: string,
 250→  pairIdMap: Map<number, {
 251→    artifact_node: { id: string; name?: string };
 252→    project_node: { id: string; name?: string };
 253→  }>,
 254→): CongruencyIssue[] {
 255→  const issues: CongruencyIssue[] = [];
 256→  let issueNum = 1;
 257→
 258→  for (const c of classifications) {
 259→    // Skip equivalents and unrelated — no issue
 260→    if (c.classification === "equivalent" || c.classification === "unrelated") continue;
 261→
 262→    const pair = pairIdMap.get(c.pair_id);
 263→    const affectedIds: string[] = [];
 264→    if (pair) {
 265→      affectedIds.push(pair.artifact_node.id, pair.project_node.id);
 266→    }
 267→
 268→    issues.push({
 269→      id: `L2-${artifactName}-${String(issueNum++).padStart(3, "0")}`,
 270→      dimension: c.dimension ?? "conflict_identification",
 271→      severity: c.severity ?? "major",
 272→      title: `${c.classification}: ${pair?.artifact_node.name ?? "?"} vs ${pair?.project_node.name ?? "?"}`,
 273→      description: c.reasoning ?? "",
 274→      affected_node_ids: affectedIds,
 275→      layer: 2,
 276→      scope: "appgraph",
 277→      downstream_impact: c.downstream_impact,
 278→      confidence: c.confidence,
 279→    });
 280→  }
 281→
 282→  return issues;
 283→}
 284→
 285→/**
 286→ * Convert Layer 3 holistic findings into congruency issues.
 287→ */
 288→function layer3FindingsToIssues(
 289→  findings: Array<{
 290→    type: string;
 291→    severity?: string;
 292→    title?: string;
 293→    description?: string;
 294→    affected_node_ids?: string[];
 295→    dimension?: string;
 296→  }>,
 297→  artifactName: string,
 298→): CongruencyIssue[] {
 299→  return findings.map((f, idx) => ({
 300→    id: `L3-${artifactName}-${String(idx + 1).padStart(3, "0")}`,
 301→    dimension: f.dimension ?? "missing_requirements",
 302→    severity: f.severity ?? "major",
 303→    title: f.title ?? `Holistic: ${f.type}`,
 304→    description: f.description ?? "",
 305→    affected_node_ids: f.affected_node_ids ?? [],
 306→    layer: 3,
 307→    scope: "appgraph",
 308→    finding_type: f.type,
 309→  }));
 310→}
 311→
 312→/**
 313→ * Convert Layer 1 mechanical findings (edge topology diffs, additions) into issues.
 314→ */
 315→function layer1ToIssues(
 316→  comparison: MechanicalComparisonResult,
 317→  artifactName: string,
 318→): CongruencyIssue[] {
 319→  const issues: CongruencyIssue[] = [];
 320→  let issueNum = 1;
 321→
 322→  // Additions → missing_requirements (minor per addition)
 323→  for (const addition of comparison.additions) {
 324→    issues.push({
 325→      id: `L1-${artifactName}-${String(issueNum++).padStart(3, "0")}`,
 326→      dimension: "missing_requirements",
 327→      severity: addition.downstream_nodes.length >= 3 ? "major" : "minor",
 328→      title: `Uncovered artifact concept: ${addition.node.name ?? addition.node.id}`,
 329→      description: `Artifact defines "${addition.node.name}" (${addition.node.type}) but no matching node exists in the project AppGraph.`,
 330→      affected_node_ids: [addition.node.id],
 331→      layer: 1,
 332→      scope: "appgraph",
 333→    });
 334→  }
 335→
 336→  // Edge topology diffs → terminology_consistency or conflict_identification
 337→  for (const diff of comparison.edge_topology_diffs) {
 338→    if (diff.missing_in_project.length > 0) {
 339→      issues.push({
 340→        id: `L1-${artifactName}-${String(issueNum++).padStart(3, "0")}`,
 341→        dimension: "missing_requirements",
 342→        severity: diff.missing_in_project.length >= 3 ? "major" : "minor",
 343→        title: `Missing edges for ${diff.artifact_node_name}`,
 344→        description: `Artifact "${diff.artifact_node_name}" has ${diff.missing_in_project.length} edge(s) not reflected in project node "${diff.project_node_name}": ${diff.missing_in_project.map((e) => `${e.edge_type}→${e.target_name}`).join(", ")}`,
 345→        affected_node_ids: [diff.artifact_node_id, diff.project_node_id],
 346→        layer: 1,
 347→        scope: "appgraph",
 348→      });
 349→    }
 350→  }
 351→
 352→  // Property diffs on strong matches → terminology_consistency
 353→  for (const propDiff of comparison.property_diffs) {
 354→    issues.push({
 355→      id: `L1-${artifactName}-${String(issueNum++).padStart(3, "0")}`,
 356→      dimension: "terminology_consistency",
 357→      severity: "minor",
 358→      title: `Property diff on ${propDiff.node_name}: ${propDiff.property}`,
 359→      description: `Strong match "${propDiff.node_name}" has different "${propDiff.property}" values. Artifact: "${String(propDiff.artifact_value).slice(0, 100)}" vs Project: "${String(propDiff.project_value).slice(0, 100)}"`,
 360→      affected_node_ids: [propDiff.artifact_node_id, propDiff.project_node_id],
 361→      layer: 1,
 362→      scope: "appgraph",
 363→    });
 364→  }
 365→
 366→  return issues;
 367→}
