 369→// ---------------------------------------------------------------------------
 370→// Phase definition
 371→// ---------------------------------------------------------------------------
 372→
 373→export function createCongruencyV2Phase(
 374→  artifacts: CongruencyV2Artifact[],
 375→): PhaseDefinition {
 376→  return {
 377→    id: "congruency-v2",
 378→    name: "Congruency Analysis V2",
 379→    async createSteps(_ctx: WorkflowContext): Promise<Step[]> {
 380→      const steps: Step[] = [];
 381→
 382→      // Step 1: Init — locate AppGraph, verify mini-AppGraphs
 383→      steps.push(
 384→        mechanicalStep("init", "Initialize V2 analysis", async (sctx) => {
 385→          const { version, appgraphPath } = await findLatestAppGraph(sctx.workspaceRoot);
 386→
 387→          let workingDir: string;
 388→          if (version === "baseline") {
 389→            workingDir = path.join(sctx.workspaceRoot, ALUCIFY_DIR, "baseline", "working");
 390→          } else {
 391→            workingDir = path.join(sctx.workspaceRoot, VERSIONS_DIR, version, "working");
 392→          }
 393→          await fs.mkdir(workingDir, { recursive: true });
 394→
 395→          sctx.state.workingDirectory = workingDir;
 396→          sctx.state.targetVersion = version;
 397→
 398→          // Verify all mini-AppGraphs exist
 399→          const validArtifacts: CongruencyV2Artifact[] = [];
 400→          for (const art of artifacts) {
 401→            try {
 402→              await fs.access(art.miniAppGraphPath);
 403→              validArtifacts.push(art);
 404→            } catch {
 405→              sctx.emitter.emit({
 406→                type: "log",
 407→                level: "warn",
 408→                message: `Skipping ${art.name}: artifact model not found at ${art.miniAppGraphPath}`,
 409→              });
 410→            }
 411→          }
 412→
 413→          if (validArtifacts.length === 0) {
 414→            throw new Error("No valid artifact models found. Run Analyze Artifacts first.");
 415→          }
 416→
 417→          sctx.phaseData.artifacts = validArtifacts;
 418→          sctx.phaseData.appgraphPath = appgraphPath;
 419→
 420→          sctx.emitter.emit({
 421→            type: "log",
 422→            level: "info",
 423→            message: `V2 init: ${version}, ${validArtifacts.length} artifact(s)`,
 424→          });
 425→
 426→          return { version, appgraphPath, artifactCount: validArtifacts.length };
 427→        }),
 428→      );
 429→
 430→      // Step 2: Layer 1 — Mechanical comparison
 431→      steps.push(
 432→        mechanicalStep("layer1", "Layer 1: Mechanical comparison", async (sctx) => {
 433→          const validArtifacts = sctx.phaseData.artifacts as CongruencyV2Artifact[];
 434→          const appgraphPath = sctx.phaseData.appgraphPath as string;
 435→
 436→          const comparisons: Array<{
 437→            artifactName: string;
 438→            comparison: MechanicalComparisonResult;
 439→          }> = [];
 440→
 441→          for (const art of validArtifacts) {
 442→            const comparison = await runMechanicalComparison(art.miniAppGraphPath, appgraphPath);
 443→            comparisons.push({ artifactName: art.name, comparison });
 444→
 445→            sctx.emitter.emit({
 446→              type: "log",
 447→              level: "info",
 448→              message: `Layer 1 ${art.name}: ${comparison.strong_matches.length} strong, ${comparison.partial_matches.length} partial, ${comparison.additions.length} additions, ${comparison.uncovered.length} uncovered`,
 449→            });
 450→          }
 451→
 452→          sctx.phaseData.comparisons = comparisons;
 453→
 454→          const totalPartial = comparisons.reduce((s, c) => s + c.comparison.partial_matches.length, 0);
 455→
 456→          return {
 457→            layer1: "done",
 458→            total_strong: comparisons.reduce((s, c) => s + c.comparison.strong_matches.length, 0),
 459→            total_partial: totalPartial,
 460→            total_additions: comparisons.reduce((s, c) => s + c.comparison.additions.length, 0),
 461→            total_uncovered: comparisons.reduce((s, c) => s + c.comparison.uncovered.length, 0),
 462→          };
 463→        }),
 464→      );
 465→
 466→      // Step 3: Layer 2 — Batched LLM classification of partial matches
 467→      steps.push(
 468→        mechanicalStep("layer2", "Layer 2: LLM classification", async (sctx) => {
 469→          const comparisons = sctx.phaseData.comparisons as Array<{
 470→            artifactName: string;
 471→            comparison: MechanicalComparisonResult;
 472→          }>;
 473→
 474→          const allLayer2Classifications: Array<{
 475→            artifactName: string;
 476→            classifications: Array<{
 477→              pair_id: number;
 478→              classification: string;
 479→              confidence?: number;
 480→              severity?: string;
 481→              reasoning?: string;
 482→              downstream_impact?: string;
 483→              dimension?: string;
 484→            }>;
 485→          }> = [];
 486→
 487→          // Collect all batches across all artifacts
 488→          const allCalls: AgentCall[] = [];
 489→          const batchMapping: Array<{
 490→            artifactName: string;
 491→            batchIndex: number;
 492→            outputPath: string;
 493→          }> = [];
 494→
 495→          // Store pair_id → partial match mapping per artifact for issue attribution
 496→          const pairIdMaps = new Map<string, Map<number, { artifact_node: { id: string; name?: string }; project_node: { id: string; name?: string } }>>();
 497→
 498→          for (const { artifactName, comparison } of comparisons) {
 499→            const batches = buildLayer2Batches(comparison.partial_matches, 10);
 500→
 501→            // Build pair_id map from batches for this artifact
 502→            const pairMap = new Map<number, { artifact_node: { id: string; name?: string }; project_node: { id: string; name?: string } }>();
 503→            for (const batch of batches) {
 504→              for (const pair of batch.pairs) {
 505→                pairMap.set(pair.pair_id, {
 506→                  artifact_node: pair.artifact_node,
 507→                  project_node: pair.project_node,
 508→                });
 509→              }
 510→            }
 511→            pairIdMaps.set(artifactName, pairMap);
 512→
 513→            if (batches.length === 0) {
 514→              allLayer2Classifications.push({ artifactName, classifications: [] });
 515→              continue;
 516→            }
 517→
 518→            for (const batch of batches) {
 519→              const outputPath = path.join(
 520→                sctx.state.workingDirectory,
 521→                `layer2-${artifactName}-batch-${batch.batch_index}.json`,
 522→              );
 523→
 524→              const prompt = [
 525→                `Classify the following ${batch.pairs.length} node pairs from artifact "${artifactName}".`,
 526→                `Write output to: ${outputPath}`,
 527→                "",
 528→                "Do NOT use the Read tool — all data is provided inline.",
 529→                "",
 530→                "--- NODE PAIRS ---",
 531→                JSON.stringify(batch.pairs, null, 2),
 532→              ].join("\n");
 533→
 534→              allCalls.push({
 535→                agentName: "congruency-classifier",
 536→                prompt,
 537→                workingDir: sctx.state.workingDirectory,
 538→                outputFile: outputPath,
 539→                allowedTools: ["Write"],
 540→                maxToolTurns: 1,
 541→                model: "haiku" as const,
 542→                toolChoice: { type: "tool" as const, name: "Write" },
 543→              });
 544→
 545→              batchMapping.push({
 546→                artifactName,
 547→                batchIndex: batch.batch_index,
 548→                outputPath,
 549→              });
 550→            }
 551→          }
 552→
 553→          if (allCalls.length > 0) {
 554→            sctx.emitter.emit({
 555→              type: "log",
 556→              level: "info",
 557→              message: `Layer 2: Running ${allCalls.length} classifier batch(es)`,
 558→            });
 559→
 560→            const results = await sctx.agentRunner.runAgentsParallel(
 561→              allCalls,
 562→              sctx.tools,
 563→              sctx.emitter,
 564→              sctx.signal,
 565→              5,
 566→            );
 567→            for (const r of results) {
 568→              trackAgentResult(sctx.state, r);
 569→            }
 570→
 571→            await verifyAndRetry(allCalls, sctx, "Layer 2 classifier");
 572→          }
 573→
 574→          // Collect results per artifact
 575→          const artifactClassifications = new Map<
 576→            string,
 577→            Array<{
 578→              pair_id: number;
 579→              classification: string;
 580→              confidence?: number;
 581→              severity?: string;
 582→              reasoning?: string;
 583→              downstream_impact?: string;
 584→              dimension?: string;
 585→            }>
 586→          >();
 587→
 588→          for (const { artifactName, outputPath } of batchMapping) {
 589→            try {
 590→              const data = await loadJson<{
 591→                classifications?: Array<{
 592→                  pair_id: number;
 593→                  classification: string;
 594→                  confidence?: number;
 595→                  severity?: string;
 596→                  reasoning?: string;
 597→                  downstream_impact?: string;
 598→                  dimension?: string;
 599→                }>;
 600→              }>(outputPath);
 601→
 602→              const existing = artifactClassifications.get(artifactName) ?? [];
 603→              existing.push(...(data.classifications ?? []));
 604→              artifactClassifications.set(artifactName, existing);
 605→            } catch (err) {
 606→              sctx.emitter.emit({
 607→                type: "log",
 608→                level: "warn",
 609→                message: `Layer 2: Failed to read batch output for ${artifactName}: ${err}`,
 610→              });
 611→            }
 612→          }
 613→
 614→          // Update allLayer2Classifications
 615→          for (const [artifactName, classifications] of artifactClassifications) {
 616→            allLayer2Classifications.push({ artifactName, classifications });
 617→          }
 618→
 619→          sctx.phaseData.layer2Classifications = allLayer2Classifications;
 620→          // Store pair_id maps for step 4 (serialized as Record<string, Array<[number, ...]>>)
 621→          const serializedMaps: Record<string, Array<[number, { artifact_node: { id: string; name?: string }; project_node: { id: string; name?: string } }]>> = {};
 622→          for (const [name, pMap] of pairIdMaps) {
 623→            serializedMaps[name] = [...pMap.entries()];
 624→          }
 625→          sctx.phaseData.pairIdMaps = serializedMaps;
 626→
 627→          const totalClassified = allLayer2Classifications.reduce(
 628→            (s, a) => s + a.classifications.length, 0,
 629→          );
 630→
 631→          return { layer2: "done", total_classified: totalClassified, batches: allCalls.length };
 632→        }),
 633→      );
 634→
 635→      // Step 4: Intra-artifact analysis (text artifacts only)
 636→      steps.push(
 637→        mechanicalStep("intra-artifact", "Intra-artifact consistency analysis", async (sctx) => {
 638→          const validArtifacts = sctx.phaseData.artifacts as CongruencyV2Artifact[];
 639→
 640→          const intraCalls: AgentCall[] = [];
 641→          const intraMapping: Array<{ artifactName: string; outputPath: string }> = [];
 642→
 643→          for (const art of validArtifacts) {
 644→            // Skip images (defensive — images are already filtered in commands.ts)
 645→            if (isImageArtifact(art.path)) continue;
 646→
 647→            // Read artifact content — only text files (string return) are supported
 648→            const ext = path.extname(art.path).toLowerCase();
 649→            const fileType = ext === ".pdf" ? "pdf" : "text";
 650→
 651→            let content: string | unknown[];
 652→            try {
 653→              content = await readArtifactContent(art.path, fileType);
 654→            } catch {
 655→              sctx.emitter.emit({
 656→                type: "log",
 657→                level: "warn",
 658→                message: `Intra-artifact: Could not read ${art.name}, skipping`,
 659→              });
 660→              continue;
 661→            }
 662→
 663→            // Skip PDF document blocks — intra-analyzer only handles text
 664→            if (typeof content !== "string") continue;
 665→
 666→            const outputPath = path.join(
 667→              sctx.state.workingDirectory,
 668→              `intra-${art.name}.json`,
 669→            );
 670→
 671→            intraCalls.push({
 672→              agentName: "artifact-intra-analyzer",
 673→              prompt:
 674→                `Analyze this artifact for internal consistency issues.\n` +
 675→                `Write output to: ${outputPath}\n` +
 676→                `Artifact name: ${art.name}\n` +
 677→                `Do NOT use the Read tool — all data is provided inline.\n` +
 678→                `Do NOT output any text. Only use the Write tool.\n\n` +
 679→                `--- ARTIFACT CONTENT ---\n${content}`,
 680→              workingDir: sctx.state.workingDirectory,
 681→              outputFile: outputPath,
 682→              allowedTools: ["Write"],
 683→              maxToolTurns: 1,
 684→              model: "haiku" as const,
 685→              toolChoice: { type: "tool" as const, name: "Write" },
 686→            });
 687→
 688→            intraMapping.push({ artifactName: art.name, outputPath });
 689→          }
 690→
 691→          if (intraCalls.length > 0) {
 692→            sctx.emitter.emit({
 693→              type: "log",
 694→              level: "info",
 695→              message: `Intra-artifact: Running ${intraCalls.length} analysis call(s) (Haiku)`,
 696→            });
 697→
 698→            const results = await sctx.agentRunner.runAgentsParallel(
 699→              intraCalls,
 700→              sctx.tools,
 701→              sctx.emitter,
 702→              sctx.signal,
 703→              5,
 704→            );
 705→            for (const r of results) {
 706→              trackAgentResult(sctx.state, r);
 707→            }
 708→
 709→            try {
 710→              await verifyAndRetry(intraCalls, sctx, "Intra-artifact analysis");
 711→            } catch (retryErr) {
 712→              sctx.emitter.emit({
 713→                type: "log",
 714→                level: "warn",
 715→                message: `Intra-artifact: some agents failed after retry — continuing. ${(retryErr as Error).message}`,
 716→              });
 717→            }
 718→          } else {
 719→            sctx.emitter.emit({
 720→              type: "log",
 721→              level: "info",
 722→              message: `Intra-artifact: No text artifacts to analyze`,
 723→            });
 724→          }
 725→
 726→          sctx.phaseData.intraMapping = intraMapping;
 727→
 728→          return { intra_calls: intraCalls.length, artifacts_analyzed: intraMapping.length };
 729→        }),
 730→      );
 731→
 732→      // Step 5: Layer 3 Holistic + Assembly
 733→      steps.push(
 734→        mechanicalStep("layer3-assembly", "Layer 3: Holistic review + assembly", async (sctx) => {
 735→          const comparisons = sctx.phaseData.comparisons as Array<{
 736→            artifactName: string;
 737→            comparison: MechanicalComparisonResult;
 738→          }>;
 739→          const layer2Classifications = sctx.phaseData.layer2Classifications as Array<{
 740→            artifactName: string;
 741→            classifications: Array<{
 742→              pair_id: number;
 743→              classification: string;
 744→              confidence?: number;
 745→              severity?: string;
 746→              reasoning?: string;
 747→              downstream_impact?: string;
 748→              dimension?: string;
 749→            }>;
 750→          }>;
 751→          const validArtifacts = sctx.phaseData.artifacts as CongruencyV2Artifact[];
 752→          const appgraphPath = sctx.phaseData.appgraphPath as string;
 753→
 754→          // Restore pair_id maps from step 3
 755→          const serializedMaps = (sctx.phaseData.pairIdMaps ?? {}) as Record<
 756→            string,
 757→            Array<[number, { artifact_node: { id: string; name?: string }; project_node: { id: string; name?: string } }]>
 758→          >;
 759→          const pairIdMaps = new Map<string, Map<number, { artifact_node: { id: string; name?: string }; project_node: { id: string; name?: string } }>>();
 760→          for (const [name, entries] of Object.entries(serializedMaps)) {
 761→            pairIdMaps.set(name, new Map(entries));
 762→          }
 763→
 764→          // --- Layer 3: Holistic review per artifact ---
 765→          const holisticCalls: AgentCall[] = [];
 766→          const holisticMapping: Array<{ artifactName: string; outputPath: string }> = [];
 767→
 768→          for (const art of validArtifacts) {
 769→            const compEntry = comparisons.find((c) => c.artifactName === art.name);
 770→            const l2Entry = layer2Classifications.find((l) => l.artifactName === art.name);
 771→            if (!compEntry) continue;
 772→
 773→            const l3Context = await buildLayer3Context(
 774→              compEntry.comparison,
 775→              l2Entry?.classifications ?? [],
 776→              art.miniAppGraphPath,
 777→              appgraphPath,
 778→              art.name,
 779→            );
 780→
 781→            const outputPath = path.join(
 782→              sctx.state.workingDirectory,
 783→              `layer3-${art.name}.json`,
 784→            );
 785→
 786→            const prompt = [
 787→              `Perform holistic review for artifact "${art.name}".`,
 788→              `Write output to: ${outputPath}`,
 789→              "",
 790→              "Do NOT use the Read tool — all data is provided inline.",
 791→              "",
 792→              "--- HOLISTIC CONTEXT ---",
 793→              JSON.stringify(l3Context, null, 2),
 794→            ].join("\n");
 795→
 796→            holisticCalls.push({
 797→              agentName: "congruency-holistic-reviewer",
 798→              prompt,
 799→              workingDir: sctx.state.workingDirectory,
 800→              outputFile: outputPath,
 801→              allowedTools: ["Write"],
 802→              maxToolTurns: 1,
 803→              toolChoice: { type: "tool" as const, name: "Write" },
 804→            });
 805→
 806→            holisticMapping.push({ artifactName: art.name, outputPath });
 807→          }
 808→
 809→          if (holisticCalls.length > 0) {
 810→            sctx.emitter.emit({
 811→              type: "log",
 812→              level: "info",
 813→              message: `Layer 3: Running ${holisticCalls.length} holistic review(s)`,
 814→            });
 815→
 816→            const results = await sctx.agentRunner.runAgentsParallel(
 817→              holisticCalls,
 818→              sctx.tools,
 819→              sctx.emitter,
 820→              sctx.signal,
 821→              5,
 822→            );
 823→            for (const r of results) {
 824→              trackAgentResult(sctx.state, r);
 825→            }
 826→
 827→            await verifyAndRetry(holisticCalls, sctx, "Layer 3 holistic");
 828→          }
 829→
 830→          // --- Assembly: merge all layers + intra findings into final report ---
 831→          const analysisDir = path.join(
 832→            path.dirname(sctx.state.workingDirectory),
 833→            "analysis",
 834→          );
 835→          await fs.mkdir(analysisDir, { recursive: true });
 836→
 837→          // Retrieve intra-artifact results from Step 4
 838→          const intraMapping = (sctx.phaseData.intraMapping ?? []) as Array<{
 839→            artifactName: string;
 840→            outputPath: string;
 841→          }>;
 842→
 843→          let totalIssues = 0;
 844→          let overallSeverity = { critical: 0, major: 0, minor: 0 };
 845→          const perArtifactSummary: Array<Record<string, unknown>> = [];
 846→
 847→          for (const art of validArtifacts) {
 848→            const compEntry = comparisons.find((c) => c.artifactName === art.name);
 849→            const l2Entry = layer2Classifications.find((l) => l.artifactName === art.name);
 850→            if (!compEntry) continue;
 851→
 852→            // Collect Layer 1 issues
 853→            const l1Issues = layer1ToIssues(compEntry.comparison, art.name);
 854→
 855→            // Collect Layer 2 issues
 856→            const artPairIdMap = pairIdMaps.get(art.name) ?? new Map();
 857→            const l2Issues = layer2ClassificationsToIssues(
 858→              l2Entry?.classifications ?? [],
 859→              art.name,
 860→              artPairIdMap,
 861→            );
 862→
 863→            // Collect Layer 3 issues
 864→            let l3Issues: CongruencyIssue[] = [];
 865→            const holisticEntry = holisticMapping.find((h) => h.artifactName === art.name);
 866→            if (holisticEntry) {
 867→              try {
 868→                const holisticData = await loadJson<{
 869→                  findings?: Array<{
 870→                    type: string;
 871→                    severity?: string;
 872→                    title?: string;
 873→                    description?: string;
 874→                    affected_node_ids?: string[];
 875→                    dimension?: string;
 876→                  }>;
 877→                }>(holisticEntry.outputPath);
 878→                l3Issues = layer3FindingsToIssues(holisticData.findings ?? [], art.name);
 879→              } catch {
 880→                // Non-fatal
 881→              }
 882→            }
 883→
 884→            // Collect intra-artifact issues (from Step 4)
 885→            let intraIssues: CongruencyIssue[] = [];
 886→            const intraEntry = intraMapping.find((i) => i.artifactName === art.name);
 887→            if (intraEntry) {
 888→              try {
 889→                const intraData = await loadJson<{
 890→                  issues?: Array<{
 891→                    id?: string;
 892→                    severity?: string;
 893→                    title?: string;
 894→                    description?: string;
 895→                    scope?: string;
 896→                    dimension?: string;
 897→                  }>;
 898→                }>(intraEntry.outputPath);
 899→                intraIssues = (intraData.issues ?? []).map((issue, idx) => ({
 900→                  id: issue.id ?? `INTRA-${art.name}-${String(idx + 1).padStart(3, "0")}`,
 901→                  dimension: issue.dimension ?? "terminology_consistency",
 902→                  severity: issue.severity ?? "minor",
 903→                  title: issue.title ?? "Intra-artifact issue",
 904→                  description: issue.description ?? "",
 905→                  affected_node_ids: [],
 906→                  layer: 0,
 907→                  scope: "intra_artifact",
 908→                }));
 909→              } catch {
 910→                // Non-fatal — intra findings may be missing
 911→              }
 912→            }
 913→
 914→            // Merge and dedup — cast to dedup's CongruencyIssue (requires non-optional id/title/dimension/severity)
 915→            const allIssues = [...intraIssues, ...l1Issues, ...l2Issues, ...l3Issues];
 916→            const deduped = deduplicateIssuesByTitleSimilarity(
 917→              allIssues as Array<{ id: string; title: string; dimension: string; severity: string; [key: string]: unknown }>,
 918→            );
 919→
 920→            // Count severities
 921→            const artSeverity = { critical: 0, major: 0, minor: 0 };
 922→            for (const issue of deduped) {
 923→              const sev = (issue.severity ?? "minor").toLowerCase();
 924→              if (sev === "critical") artSeverity.critical++;
 925→              else if (sev === "major") artSeverity.major++;
 926→              else artSeverity.minor++;
 927→            }
 928→
 929→            overallSeverity.critical += artSeverity.critical;
 930→            overallSeverity.major += artSeverity.major;
 931→            overallSeverity.minor += artSeverity.minor;
 932→            totalIssues += deduped.length;
 933→
 934→            const layerSummary = {
 935→              intra: { findings: intraIssues.length },
 936→              layer1: { strong: compEntry.comparison.strong_matches.length, partial: compEntry.comparison.partial_matches.length, additions: compEntry.comparison.additions.length, uncovered: compEntry.comparison.uncovered.length },
 937→              layer2: { classified: l2Entry?.classifications.length ?? 0 },
 938→              layer3: { findings: l3Issues.length },
 939→            };
 940→
 941→            // Write per-artifact JSON report
 942→            const artReportPath = path.join(
 943→              analysisDir,
 944→              `congruency-v2-${art.name}.json`,
 945→            );
 946→            await saveJson(artReportPath, {
 947→              artifact_name: art.name,
 948→              artifact_path: art.path,
 949→              analysis_version: "v2",
 950→              layer_summary: layerSummary,
 951→              issues: deduped,
 952→              by_severity: artSeverity,
 953→              total_issues: deduped.length,
 954→            });
 955→
 956→            let artStatus = "CONGRUENT";
 957→            if (artSeverity.critical > 0) artStatus = "INCONGRUENT";
 958→            else if (artSeverity.major > 0) artStatus = "MAJOR_ISSUES";
 959→            else if (artSeverity.minor > 0) artStatus = "MINOR_ISSUES";
 960→
 961→            // Write per-artifact markdown report
 962→            const artMdPath = path.join(analysisDir, `congruency-v2-${art.name}.md`);
 963→            const markdown = generateV2Markdown(art.name, artStatus, deduped, artSeverity, layerSummary);
 964→            await fs.writeFile(artMdPath, markdown, "utf-8");
 965→
 966→            perArtifactSummary.push({
 967→              artifact_name: art.name,
 968→              artifact_path: art.path,
 969→              status: artStatus,
 970→              issue_count: deduped.length,
 971→              by_severity: artSeverity,
 972→            });
 973→
 974→            sctx.emitter.emit({
 975→              type: "log",
 976→              level: "info",
 977→              message: `V2 ${art.name}: ${artStatus} — ${deduped.length} issues (Intra:${intraIssues.length} L1:${l1Issues.length} L2:${l2Issues.length} L3:${l3Issues.length})`,
 978→            });
 979→          }
 980→
 981→          // Update pipeline manifest with analysis completion
 982→          try {
 983→            const { loadManifest, markAnalyzed, saveManifest } = await import(
 984→              "../mechanical/artifact-pipeline-manifest.js"
 985→            );
 986→            const pManifest = await loadManifest(sctx.workspaceRoot);
 987→            for (const art of validArtifacts) {
 988→              markAnalyzed(pManifest, art.name);
 989→            }
 990→            await saveManifest(sctx.workspaceRoot, pManifest);
 991→          } catch {
 992→            // Non-critical — manifest update failure shouldn't block analysis
 993→          }
 994→
 995→          // Write batch report
 996→          let overallStatus = "CONGRUENT";
 997→          if (overallSeverity.critical > 0) overallStatus = "INCONGRUENT";
 998→          else if (overallSeverity.major > 0) overallStatus = "MAJOR_ISSUES";
 999→          else if (overallSeverity.minor > 0) overallStatus = "MINOR_ISSUES";
1000→
1001→          const batchReportPath = path.join(
1002→            analysisDir,
1003→            "congruency-v2-batch-report.json",
1004→          );
1005→          await saveJson(batchReportPath, {
1006→            analysis_version: "v2",
1007→            overall_assessment: {
1008→              status: overallStatus,
1009→              total_issues: totalIssues,
1010→              by_severity: overallSeverity,
1011→            },
1012→            per_artifact_summary: perArtifactSummary,
1013→          });
1014→
1015→          // Extract stats
1016→          const { extractCongruencyStats } = await import(
1017→            "../mechanical/extract-congruency-stats.js"
1018→          );
1019→          const statsOutputPath = path.join(
1020→            sctx.state.workingDirectory,
1021→            "congruency-stats.json",
1022→          );
1023→
1024→          const stats = await extractCongruencyStats({
1025→            batchReportPath,
1026→            outputDir: analysisDir,
1027→            statsOutputPath,
1028→            appgraphPath,
1029→            baselinePath: null,
1030→          });
1031→
1032→          sctx.emitter.emit({
1033→            type: "log",
1034→            level: "info",
1035→            message: `V2 complete: ${overallStatus} — score ${stats.congruency_score}, ${totalIssues} issues, ${stats.total_nodes_affected} nodes affected`,
1036→          });
1037→
1038→          return {
1039→            status: overallStatus,
1040→            total_issues: totalIssues,
1041→            congruency_score: stats.congruency_score,
1042→            nodes_affected: stats.total_nodes_affected,
1043→          };
1044→        }),
1045→      );
1046→
1047→      return steps;
1048→    },
1049→  };
1050→}
