 39→function mechanicalStep(
 40→  id: string,
 41→  name: string,
 42→  fn: (ctx: StepContext) => Promise<Record<string, unknown> | void>,
 43→): Step {
 44→  return {
 45→    id,
 46→    name,
 47→    mode: "sequential",
 48→    async execute(ctx: StepContext): Promise<StepResult> {
 49→      try {
 50→        const data = await fn(ctx);
 51→        return { status: "success", data: (data as Record<string, unknown>) ?? {} };
 52→      } catch (err) {
 53→        return { status: "error", error: String(err) };
 54→      }
 55→    },
 56→  };
 57→}
