120→function createNormalizePhase(): PhaseDefinition {
121→  return {
122→    id: "normalize-data",
123→    name: "Normalize Data",
124→    createSteps(_ctx: WorkflowContext): Step[] {
125→      return [
126→        mechanicalStep("normalize-data", "Normalize and cross-reference analysis data", async (sctx) => {
127→          const { version: appgraphVersion, appgraphPath } =
128→            await findLatestAppGraph(sctx.workspaceRoot);
129→
130→          sctx.emitter.emit({
131→            type: "log",
132→            level: "info",
133→            message: `Normalizing analysis data for ${appgraphVersion}`,
134→          });
135→
136→          // Determine version directory and analysis dir
137→          let versionDir: string;
138→          let analysisDir: string;
139→          if (appgraphVersion === "baseline") {
140→            versionDir = path.join(sctx.workspaceRoot, ".alucify");
141→            analysisDir = path.join(versionDir, "analysis");
142→          } else {
143→            versionDir = path.join(sctx.workspaceRoot, VERSIONS_DIR, appgraphVersion);
144→            analysisDir = path.join(versionDir, "analysis");
145→          }
146→          await fs.mkdir(analysisDir, { recursive: true });
147→
148→          const synthesisVersion = await getNextSynthesisVersion(analysisDir);
149→          const dataPath = path.join(
150→            analysisDir,
151→            `quality-synthesis-data-v${synthesisVersion}.json`,
152→          );
153→          const reportPath = path.join(
154→            analysisDir,
155→            `quality-synthesis-report-v${synthesisVersion}.md`,
156→          );
157→
158→          sctx.state.workingDirectory = analysisDir;
159→
160→          const stats = await normalizeQualitySynthesis(versionDir, synthesisVersion, dataPath, appgraphPath);
161→
162→          sctx.emitter.emit({
163→            type: "log",
164→            level: "info",
165→            message: `Normalized: ${stats.totalItems} items, ${stats.crossCuttingNodes} cross-cutting nodes, health: ${stats.compositeHealth}`,
166→          });
167→
168→          return {
169→            appgraphVersion,
170→            appgraphPath,
171→            synthesisVersion,
172→            dataPath,
173→            reportPath,
174→            versionDir,
175→          };
176→        }),
177→      ];
178→    },
179→  };
180→}
