182→// ---------------------------------------------------------------------------
183→// Phase 2: Generate Report (mechanical + slim LLM enhancement)
184→// ---------------------------------------------------------------------------
185→
186→function createSynthesizePhase(): PhaseDefinition {
187→  return {
188→    id: "synthesize-report",
189→    name: "Synthesize Report",
190→    createSteps(_ctx: WorkflowContext): Step[] {
191→      return [
192→        // Step 1: Mechanical — generate leverage clusters, prioritized actions, and markdown report
193→        mechanicalStep("generate-report-mechanical", "Generate report (mechanical)", async (sctx) => {
194→          const phaseResult = sctx.state.phaseResults["normalize-data"] ?? {};
195→          const dataPath = phaseResult.dataPath as string;
196→          const reportPath = phaseResult.reportPath as string;
197→
198→          if (!dataPath) {
199→            throw new Error("Missing paths from normalize-data phase");
200→          }
201→
202→          // Load normalized metrics
203→          const raw = await fs.readFile(dataPath, "utf-8");
204→          const metrics: QualitySynthesisOutput = JSON.parse(raw);
205→
206→          // Generate prioritized actions, narrative, and markdown mechanically
207→          const { actions, narrative, markdown } = generateQualitySynthesisReport(metrics);
208→
209→          sctx.emitter.emit({
210→            type: "log",
211→            level: "info",
212→            message: `Generated ${actions.length} prioritized actions mechanically, ${narrative.cross_cutting_themes.length} themes`,
213→          });
214→
215→          // Update metrics JSON with prioritized actions and narrative
216→          metrics.prioritized_actions = actions;
217→          metrics.narrative_sections = narrative;
218→          await fs.writeFile(dataPath, JSON.stringify(metrics, null, 2), "utf-8");
219→
220→          // Write markdown report
221→          await fs.writeFile(reportPath, markdown, "utf-8");
222→
223→          sctx.emitter.emit({
224→            type: "log",
225→            level: "info",
226→            message: `Mechanical report generated at ${reportPath}`,
227→          });
228→
229→          return { reportPath, dataPath };
230→        }),
231→
232→        // Step 2: LLM — enhance narrative sections (executive summary, themes, recommendations, action descriptions)
233→        {
234→          id: "enhance-report-narrative",
235→          name: "Enhance report narrative",
236→          mode: "sequential",
237→          async execute(sctx: StepContext): Promise<StepResult> {
238→            const phaseResult = sctx.state.phaseResults["normalize-data"] ?? {};
239→            const dataPath = phaseResult.dataPath as string;
240→            const reportPath = phaseResult.reportPath as string;
241→
242→            if (!dataPath || !reportPath) {
243→              return {
244→                status: "error",
245→                error: "Missing paths from normalize-data phase",
246→              };
247→            }
248→
249→            const prompt = [
250→              "Enhance the pre-generated quality synthesis report with contextual narrative.",
251→              "",
252→              `Pre-generated report: ${reportPath}`,
253→              `Metrics JSON (with prioritized_actions[] and narrative_sections{} populated): ${dataPath}`,
254→              "",
255→              "Instructions:",
256→              `1. Read the pre-generated markdown report from: ${reportPath}`,
257→              `2. Read the metrics JSON from: ${dataPath}`,
258→              "3. Enhance the report:",
259→              "   - Improve the Executive Summary with more contextual insight about quality posture",
260→              "   - Improve Cross-Cutting Themes with strategic analysis of documentation gaps",
261→              "   - Improve Strategic Recommendations with artifact-focused, actionable advice",
262→              "   - Enrich prioritized action rationales with root-cause analysis",
263→              "   - Improve cross-cutting concern descriptions with artifact gap context",
264→              `4. Write the enhanced report back to: ${reportPath}`,
265→              "",
266→              "IMPORTANT: Do NOT modify any numbers, tables, or metric values.",
267→              "Only enhance narrative/prose sections. The report structure must remain identical.",
268→              "Frame all recommendations in terms of artifact operations (create/update documents),",
269→              "NOT AppGraph internals (nodes, edges, grounding scores).",
270→            ].join("\n");
271→
272→            const agentCall: AgentCall = {
273→              agentName: "synthesis-reporter",
274→              prompt,
275→              workingDir: path.dirname(dataPath),
276→              outputFile: reportPath,
277→              allowedTools: ["Read", "Write"],
278→              maxToolTurns: 3, // Read report + Read metrics + Write report
279→            };
280→
281→            const results = await sctx.agentRunner.runAgentsParallel(
282→              [agentCall],
283→              sctx.tools,
284→              sctx.emitter,
285→              sctx.signal,
286→              5,
287→            );
288→
289→            for (const r of results) {
290→              trackAgentResult(sctx.state, r);
291→            }
292→
293→            // No verifyAndRetry needed — the mechanical step already wrote
294→            // reportPath as a complete fallback. If the LLM enhancement fails,
295→            // the mechanical report is still usable.
296→
297→            return {
298→              status: "success",
299→              data: { reportPath, dataPath },
300→            };
301→          },
302→        },
303→      ];
304→    },
305→  };
306→}
