 39→/**
 40→ * Extract a JSON object/array from text that may contain markdown fences.
 41→ * Returns the parsed value or null if no valid JSON is found.
 42→ */
 43→export function extractJson(text: string): unknown {
 44→  if (!text) return null;
 45→
 46→  // Try 1: the entire text is valid JSON
 47→  try {
 48→    const parsed = JSON.parse(text);
 49→    if (typeof parsed === "object" && parsed !== null) return parsed;
 50→  } catch { /* not raw JSON */ }
 51→
 52→  // Try 2: extract from ```json ... ``` or ``` ... ``` fenced blocks
 53→  const fenceMatch = text.match(/```(?:json)?\s*\n?([\s\S]*?)```/);
 54→  if (fenceMatch) {
 55→    try {
 56→      const parsed = JSON.parse(fenceMatch[1].trim());
 57→      if (typeof parsed === "object" && parsed !== null) return parsed;
 58→    } catch { /* fence content not valid JSON */ }
 59→  }
 60→
 61→  // Try 3: find the first { ... } or [ ... ] span (greedy)
 62→  const braceStart = text.indexOf("{");
 63→  const bracketStart = text.indexOf("[");
 64→  const start = braceStart >= 0 && (bracketStart < 0 || braceStart < bracketStart)
 65→    ? braceStart
 66→    : bracketStart;
 67→  if (start >= 0) {
 68→    const closer = text[start] === "{" ? "}" : "]";
 69→    const end = text.lastIndexOf(closer);
 70→    if (end > start) {
 71→      try {
 72→        const parsed = JSON.parse(text.slice(start, end + 1));
 73→        if (typeof parsed === "object" && parsed !== null) return parsed;
 74→      } catch { /* not valid JSON span */ }
 75→    }
 76→  }
 77→
 78→  return null;
 79→}
