106→  constructor(private options: SdkAgentRunnerOptions) {
107→    this.promptComposer = new PromptComposer(
108→      options.agentDir,
109→      options.skillsDir,
110→      {
111→        workflowId: options.workflowId,
112→        useInlined: options.useInlined,
113→        dependencyWorkflows: options.dependencyWorkflows,
114→      },
115→    );
116→    this.modelResolver = new ModelResolver(options.defaultModel);
117→  }
118→
119→  async runAgent(
120→    call: AgentCall,
121→    _toolRegistry: ToolRegistry,
122→    emitter: WorkflowEventEmitter,
123→    signal: AbortSignal,
124→  ): Promise<AgentResult> {
125→    // Lazy-import the SDK to avoid bundling issues when not in use
126→    const { query } = await import("@anthropic-ai/claude-agent-sdk");
127→
128→    const startTime = Date.now();
129→    const tempFiles: string[] = [];
130→
131→    try {
132→      // 1. Compose system prompt (reuses existing PromptComposer)
133→      const agentDef = this.promptComposer.loadAgent(call.agentName);
134→      let systemPrompt = this.promptComposer.compose(agentDef);
135→      const modelPref = call.model ?? agentDef.model;
136→      const model = this.modelResolver.resolveToPreference(modelPref);
137→      let allowedTools = call.allowedTools ?? agentDef.allowedTools;
138→
139→      // 2. Build SDK prompt (string or AsyncIterable for multi-modal)
140→      const { prompt: sdkPrompt, tempFiles: created } = this.buildSdkPrompt(
141→        call.prompt,
142→        call.workingDir,
143→      );
144→      tempFiles.push(...created);
145→
146→      // If we saved temp PDFs, the agent needs Read access to load them
147→      if (created.length > 0 && !allowedTools.includes("Read")) {
148→        allowedTools = [...allowedTools, "Read"];
149→      }
150→
151→      // Write-only agents need Read access to satisfy CLI's "must read before write"
152→      // rule when overwriting existing files (e.g., retries, edge re-extraction)
153→      if (allowedTools.length === 1 && allowedTools[0] === "Write") {
154→        allowedTools = [...allowedTools, "Read"];
155→      }
156→
157→      const verbose = this.options.verbose === true;
158→
159→      // Map maxToolTurns to SDK --max-turns. Floor at 1 (tool calls execute
160→      // as part of the turn, so maxTurns=1 still runs the Write tool).
161→      // verifyAndRetry provides the safety net for the rare text-only response.
162→      const resolvedMaxTurns = Math.max(call.maxToolTurns ?? 3, 1);
163→
164→      // 3. Emit start event
165→      (emitter as WorkflowEventEmitter).emit({
166→        type: "log",
167→        level: "info",
168→        message: `[SDK] Starting agent: ${call.agentName}`,
169→      });
170→      if (verbose) {
171→        const isWriteOnly = allowedTools.length === 1 && allowedTools[0] === "Write";
172→        (emitter as WorkflowEventEmitter).emit({
173→          type: "log",
174→          level: "info",
175→          message: `[SDK] Agent ${call.agentName} config: model=${model} tools=[${allowedTools}] maxToolTurns=${call.maxToolTurns} maxTurns=${resolvedMaxTurns} isWriteOnly=${isWriteOnly} promptLen=${typeof call.prompt === "string" ? call.prompt.length : "array"} tempFiles=${created.length}`,
176→        });
177→      }
178→
179→      // 4. Set up abort controller bridged from our AbortSignal
180→      const abortController = new AbortController();
181→      const onAbort = () => abortController.abort();
182→      signal.addEventListener("abort", onAbort, { once: true });
183→
184→      // 5. Call SDK
185→      // Use Record type to avoid ESM/CJS import issues with SDK type definitions.
186→      // The SDK's SDKResultMessage has: total_cost_usd, num_turns, duration_ms, usage.
187→      let resultMessage: Record<string, unknown> | null = null;
188→
189→      if (verbose) {
190→        const promptPreview = typeof sdkPrompt === "string"
191→          ? sdkPrompt.slice(0, 500)
192→          : "[multi-modal prompt]";
193→        (emitter as WorkflowEventEmitter).emit({
194→          type: "log",
195→          level: "info",
196→          message: `[SDK] Agent ${call.agentName} prompt preview: ${promptPreview}`,
197→        });
198→      }
199→
200→      // Capture stderr so we get the real error when the subprocess crashes.
201→      // By default the SDK sets stderr to "ignore", losing all diagnostic info.
202→      const stderrChunks: string[] = [];
203→      let rateLimitResetsAt: number | null = null;
204→
205→      try {
206→        for await (const message of query({
207→          prompt: sdkPrompt,
208→          options: {
209→            systemPrompt,
210→            model,
211→            tools: allowedTools,
212→            allowedTools,
213→            cwd: call.workingDir,
214→            maxTurns: resolvedMaxTurns,
215→            permissionMode: "bypassPermissions",
216→            allowDangerouslySkipPermissions: true,
217→            abortController,
218→            persistSession: false,
219→            env: {
220→              ...process.env,
221→              // Claude Code defaults to 32K output tokens which is too low
222→              // for large extraction tasks. Sonnet max is 64K, Opus max is 128K.
223→              CLAUDE_CODE_MAX_OUTPUT_TOKENS: String(call.maxOutputTokens ?? 64000),
224→            },
225→            stderr: (data: string) => {
226→              stderrChunks.push(data);
227→            },
228→          },
229→        })) {
230→          if (signal.aborted) break;
231→
232→          // Capture the result message (last message in the stream)
233→          const msg = message as Record<string, unknown>;
234→          if (msg?.type === "result") {
235→            resultMessage = msg;
236→            if (verbose) {
237→              (emitter as WorkflowEventEmitter).emit({
238→                type: "log",
239→                level: "info",
240→                message: `[SDK] Agent ${call.agentName} result: ${JSON.stringify(msg, null, 0).slice(0, 1000)}`,
241→              });
242→            }
243→          }
244→
245→          // Detect rate limit rejection (always — needed for RateLimitError)
246→          if (msg?.type === "rate_limit_event") {
247→            const info = (msg as Record<string, unknown>).rate_limit_info as Record<string, unknown> | undefined;
248→            if (info?.status === "rejected" && typeof info.resetsAt === "number") {
249→              rateLimitResetsAt = info.resetsAt as number;
250→            }
251→          }
252→
253→          if (verbose) {
254→            // Log assistant turns with full content detail
255→            if (msg?.type === "assistant") {
256→              const content = msg.message as Record<string, unknown> | undefined;
257→              const blocks = (content?.content ?? []) as Array<Record<string, unknown>>;
258→              const blockTypes = blocks.map((b) => {
259→                if (b.type === "tool_use") {
260→                  const input = b.input as Record<string, unknown> | undefined;
261→                  const filePath = input?.file_path ?? input?.path ?? "";
262→                  return `tool_use(${b.name}, ${filePath})`;
263→                }
264→                if (b.type === "text") {
265→                  const txt = (b.text as string) ?? "";
266→                  return `text(${txt.length}ch): ${txt.slice(0, 300)}`;
267→                }
268→                if (b.type === "thinking") {
269→                  const txt = (b.thinking as string) ?? "";
270→                  return `thinking(${txt.length}ch): ${txt.slice(0, 300)}`;
271→                }
272→                return String(b.type);
273→              });
274→              (emitter as WorkflowEventEmitter).emit({
275→                type: "log",
276→                level: "info",
277→                message: `[SDK] Agent ${call.agentName} turn: [${blockTypes.join(" | ")}]`,
278→              });
279→            }
280→
281→            // Log other message types (tool_result, system, etc.)
282→            if (msg?.type && msg.type !== "assistant" && msg.type !== "result") {
283→              (emitter as WorkflowEventEmitter).emit({
284→                type: "log",
285→                level: "info",
286→                message: `[SDK] Agent ${call.agentName} msg: type=${msg.type} ${JSON.stringify(msg).slice(0, 300)}`,
287→              });
288→            }
289→          }
290→        }
291→      } catch (sdkError) {
292→        // If rate limit was detected during the stream, throw non-retryable error
293→        if (rateLimitResetsAt != null) {
294→          const resetsAt = new Date(rateLimitResetsAt * 1000);
295→          (emitter as WorkflowEventEmitter).emit({
296→            type: "log",
297→            level: "error",
298→            message: `[SDK] Agent ${call.agentName} hit rate limit. Resets at ${resetsAt.toLocaleTimeString()}`,
299→          });
300→          throw new RateLimitError(call.agentName, resetsAt);
301→        }
302→        // Enrich the opaque SDK error with captured stderr
303→        const stderrText = stderrChunks.join("").trim();
304→        const baseMsg = (sdkError as Error).message ?? String(sdkError);
305→        const detail = stderrText
306→          ? `${baseMsg}\nstderr: ${stderrText.slice(0, 2000)}`
307→          : baseMsg;
308→        (emitter as WorkflowEventEmitter).emit({
309→          type: "log",
310→          level: "error",
311→          message: `[SDK] Agent ${call.agentName} subprocess failed: ${detail.slice(0, 500)}`,
312→        });
313→        throw new AgentError(call.agentName, detail);
314→      } finally {
315→        signal.removeEventListener("abort", onAbort);
316→      }
317→
318→      if (signal.aborted) {
319→        throw new AgentError(call.agentName, "Cancelled");
320→      }
321→
322→      // Check for rate limit rejection — throw a non-retryable error
323→      if (rateLimitResetsAt != null) {
324→        const resetsAt = new Date(rateLimitResetsAt * 1000);
325→        throw new RateLimitError(call.agentName, resetsAt);
326→      }
327→
328→      // Log stderr even on success — 0-token results indicate something went wrong
329→      const stderrText = stderrChunks.join("").trim();
330→      if (stderrText && verbose) {
331→        (emitter as WorkflowEventEmitter).emit({
332→          type: "log",
333→          level: "warn",
334→          message: `[SDK] Agent ${call.agentName} stderr: ${stderrText.slice(0, 1000)}`,
335→        });
336→      }
337→
338→      // 6. Text rescue: if the agent returned JSON as text instead of calling
339→      //    Write, extract it and write the file ourselves. This handles the
340→      //    SDK's lack of tool_choice forcing — especially common with Haiku.
341→      let rescued = false;
342→      if (call.outputFile && resultMessage) {
343→        let fileExists = false;
344→        try {
345→          fs.accessSync(call.outputFile);
346→          fileExists = true;
347→        } catch { /* file missing — candidate for rescue */ }
348→
349→        if (!fileExists) {
350→          const resultText = typeof resultMessage.result === "string"
351→            ? resultMessage.result
352→            : "";
353→          const json = extractJson(resultText);
354→          if (json !== null) {
355→            const dir = path.dirname(call.outputFile);
356→            fs.mkdirSync(dir, { recursive: true });
357→            fs.writeFileSync(call.outputFile, JSON.stringify(json, null, 2));
358→            rescued = true;
359→            (emitter as WorkflowEventEmitter).emit({
360→              type: "log",
361→              level: "warn",
362→              message: `[SDK] Agent ${call.agentName} returned text instead of calling Write — rescued output to ${call.outputFile}`,
363→            });
364→          }
365→        }
366→      }
367→
368→      // 7. Map SDK result to AgentResult
369→      const usage = (resultMessage?.usage ?? {}) as Record<string, number>;
370→      const tokensUsed: TokenUsage = {
371→        input: usage.input_tokens ?? 0,
372→        output: usage.output_tokens ?? 0,
373→        cacheCreationInput: usage.cache_creation_input_tokens,
374→        cacheReadInput: usage.cache_read_input_tokens,
375→      };
376→
377→      const agentResult: AgentResult = {
378→        agentName: call.agentName,
379→        costUsd: (resultMessage?.total_cost_usd as number) ?? 0,
380→        durationMs: Date.now() - startTime,
381→        toolTurns: (resultMessage?.num_turns as number) ?? 0,
382→        tokensUsed,
383→        outputFile: call.outputFile,
384→        rescued,
385→      };
386→
387→      (emitter as WorkflowEventEmitter).emit({
388→        type: "log",
389→        level: "info",
390→        message: `[SDK] Agent ${call.agentName} completed: ${tokensUsed.input + tokensUsed.output} tokens, ${agentResult.toolTurns} turns${rescued ? " (rescued)" : ""}`,
391→      });
392→
393→      return agentResult;
394→    } finally {
395→      // Clean up temp files
396→      for (const f of tempFiles) {
397→        try {
398→          fs.unlinkSync(f);
399→        } catch {
400→          /* ignore */
401→        }
402→      }
403→    }
404→  }
