406→  async runAgentsParallel(
407→    calls: AgentCall[],
408→    toolRegistry: ToolRegistry,
409→    emitter: WorkflowEventEmitter,
410→    signal: AbortSignal,
411→    maxConcurrency: number = 3,
412→  ): Promise<AgentResult[]> {
413→    // SDK spawns subprocesses that are heavier than API calls.
414→    // Cap at 3 concurrent agents to balance throughput vs rate limits.
415→    // Individual failures are retried once with backoff before propagating.
416→    const effectiveConcurrency = Math.min(maxConcurrency, 3);
417→
418→    if (calls.length === 0) return [];
419→    if (calls.length === 1) {
420→      return [await this.runAgent(calls[0], toolRegistry, emitter, signal)];
421→    }
422→
423→    const linkedToken = createCancellationToken(signal);
424→    const results: AgentResult[] = new Array(calls.length);
425→    let firstError: Error | null = null;
426→
427→    // Semaphore for concurrency control
428→    let running = 0;
429→    const queue: Array<() => void> = [];
430→    const acquire = (): Promise<void> => {
431→      if (running < effectiveConcurrency) {
432→        running++;
433→        return Promise.resolve();
434→      }
435→      return new Promise<void>((resolve) => {
436→        queue.push(resolve);
437→      });
438→    };
439→    const release = () => {
440→      running--;
441→      const next = queue.shift();
442→      if (next) {
443→        running++;
444→        next();
445→      }
446→    };
447→
448→    const tasks = calls.map(async (call, index) => {
449→      await acquire();
450→      if (linkedToken.signal.aborted || firstError) {
451→        release();
452→        throw firstError ?? new Error("Cancelled");
453→      }
454→      try {
455→        results[index] = await this.runAgent(
456→          call,
457→          toolRegistry,
458→          emitter,
459→          linkedToken.signal,
460→        );
461→      } catch (err) {
462→        // Rate limit errors are not retryable — fail fast
463→        if (err instanceof RateLimitError) {
464→          if (!firstError) {
465→            firstError = err;
466→            linkedToken.cancel();
467→          }
468→          throw err;
469→        }
470→        // Retry once after a backoff — SDK errors are often transient
471→        if (linkedToken.signal.aborted) {
472→          throw err;
473→        }
474→        const delay = 15_000 + Math.random() * 15_000; // 15-30s jitter
475→        (emitter as WorkflowEventEmitter).emit({
476→          type: "log",
477→          level: "warn",
478→          message: `[SDK] Agent ${call.agentName} failed, retrying in ${Math.round(delay / 1000)}s: ${(err as Error).message?.slice(0, 100)}`,
479→        });
480→        await new Promise((r) => setTimeout(r, delay));
481→        if (linkedToken.signal.aborted) {
482→          throw err;
483→        }
484→        try {
485→          results[index] = await this.runAgent(
486→            call,
487→            toolRegistry,
488→            emitter,
489→            linkedToken.signal,
490→          );
491→        } catch (retryErr) {
492→          if (!firstError) {
493→            firstError = retryErr as Error;
494→            linkedToken.cancel();
495→          }
496→          throw retryErr;
497→        }
498→      } finally {
499→        release();
500→      }
501→    });
502→
503→    const settled = await Promise.allSettled(tasks);
504→    // Throw the first error if any
505→    for (const s of settled) {
506→      if (s.status === "rejected") {
507→        throw s.reason;
508→      }
509→    }
510→
511→    return results;
512→  }
