514→  /**
515→   * Build SDK-compatible prompt from ContentBlockParam[].
516→   * - Text-only prompts → plain string (simplest path)
517→   * - Multi-modal prompts (with images) → AsyncIterable<SDKUserMessage>
518→   *   so the SDK sends images through its native vision encoder pipeline.
519→   *
520→   * Document blocks (PDFs) are always saved as temp files since the SDK
521→   * subprocess can't receive inline base64 PDFs.
522→   */
523→  buildSdkPrompt(
524→    prompt: string | unknown[],
525→    workingDir: string,
526→  // eslint-disable-next-line @typescript-eslint/no-explicit-any
527→  ): { prompt: string | AsyncIterable<any>; tempFiles: string[] } {
528→    if (typeof prompt === "string") {
529→      return { prompt, tempFiles: [] };
530→    }
531→
532→    const blocks = prompt as Array<Record<string, unknown>>;
533→    const tempFiles: string[] = [];
534→    // Use Record<string, unknown>[] for content blocks to avoid SDK type import issues
535→    const contentBlocks: Array<Record<string, unknown>> = [];
536→    let hasMultiModal = false;
537→
538→    for (const block of blocks) {
539→      if (block.type === "text") {
540→        contentBlocks.push({ type: "text", text: block.text as string });
541→      } else if (block.type === "image") {
542→        // Pass image blocks natively — this is the key fix.
543→        // Previously these were silently dropped by flattenPrompt().
544→        hasMultiModal = true;
545→        contentBlocks.push(block);
546→      } else if (block.type === "document") {
547→        // PDFs: save as temp file (SDK subprocess can't receive inline base64 PDFs)
548→        const source = block.source as Record<string, string> | undefined;
549→        if (source?.type === "base64" && source.data) {
550→          const tempName = `_temp_${Date.now()}_${Math.random().toString(36).slice(2, 8)}.pdf`;
551→          const tempPath = path.join(workingDir, tempName);
552→          const buffer = Buffer.from(source.data, "base64");
553→          fs.writeFileSync(tempPath, buffer);
554→          tempFiles.push(tempPath);
555→          contentBlocks.push({
556→            type: "text",
557→            text: `The artifact content is a PDF file saved at: ${tempPath}\nRead this file to access the artifact content.`,
558→          });
559→        }
560→      }
561→    }
562→
563→    // When PDFs were saved as temp files, the prompt must tell the agent
564→    // to Read them — but the original instruction says "Do NOT read the file"
565→    // (which was correct for API mode where PDFs are inline document blocks).
566→    // Replace the conflicting instruction so the agent reads the temp file.
567→    if (tempFiles.length > 0) {
568→      for (const block of contentBlocks) {
569→        if (block.type === "text" && typeof block.text === "string") {
570→          block.text = (block.text as string).replace(
571→            /The source artifact content is provided below\. Do NOT read the file\./g,
572→            "The source artifact content is in the PDF file referenced below. Read it using the Read tool.",
573→          );
574→        }
575→      }
576→    }
577→
578→    // If no images, flatten to string for simplicity (preserves current behavior)
579→    if (!hasMultiModal) {
580→      const text = contentBlocks
581→        .filter((b) => b.type === "text")
582→        .map((b) => b.text as string)
583→        .join("\n\n");
584→      return { prompt: text, tempFiles };
585→    }
586→
587→    // Multi-modal: yield a single SDKUserMessage with the full content array
588→    // so the SDK sends images through its native vision encoder pipeline.
589→    const sessionId = randomUUID();
590→    // Yields SDKUserMessage-shaped objects. Typed as `any` to avoid
591→    // importing SDK types directly (ESM/CJS compatibility — see line 141).
592→    // eslint-disable-next-line @typescript-eslint/no-explicit-any
593→    async function* generate(): AsyncGenerator<any> {
594→      yield {
595→        type: "user",
596→        message: { role: "user", content: contentBlocks },
597→        parent_tool_use_id: null,
598→        session_id: sessionId,
599→      };
600→    }
601→    return { prompt: generate(), tempFiles };
602→  }
603→}
