  5→export interface AgentDefinition {
  6→  /** Agent name (e.g., "artifact-requirement-extractor") */
  7→  name: string;
  8→  /** Full system prompt content (after frontmatter) */
  9→  systemPrompt: string;
 10→  /** Model preference from frontmatter */
 11→  model: ModelPreference;
 12→  /** Skill names referenced in frontmatter */
 13→  skills: string[];
 14→  /** Tool names this agent is allowed to use */
 15→  allowedTools: string[];
 16→}
 17→
 18→export interface AgentCall {
 19→  /** Agent name to invoke */
 20→  agentName: string;
 21→  /** User-role prompt content (string for text, array for multi-part e.g. PDF documents) */
 22→  prompt: string | Anthropic.Messages.ContentBlockParam[];
 23→  /** Working directory for tool execution sandboxing */
 24→  workingDir: string;
 25→  /** Expected output file path (for tracking) */
 26→  outputFile?: string;
 27→  /** Override allowed tools (defaults to agent definition) */
 28→  allowedTools?: string[];
 29→  /** Maximum tool turns before breaking the loop (skips acknowledgment turn) */
 30→  maxToolTurns?: number;
 31→  /** Override model preference (defaults to agent frontmatter) */
 32→  model?: ModelPreference;
 33→  /** Force the model to use a specific tool on the first API turn */
 34→  toolChoice?: "auto" | "any" | { type: "tool"; name: string };
 35→  /** Max output tokens (thinking + response). Defaults to 64000 (Sonnet max: 64K, Opus: 128K). */
 36→  maxOutputTokens?: number;
 37→}
 38→
 39→export interface TokenUsage {
 40→  /** Non-cached input tokens */
 41→  input: number;
 42→  /** Output tokens */
 43→  output: number;
 44→  /** Tokens written to cache (charged at 1.25x input rate) */
 45→  cacheCreationInput?: number;
 46→  /** Tokens read from cache (charged at 0.10x input rate) */
 47→  cacheReadInput?: number;
 48→}
 49→
 50→export interface AgentResult {
 51→  /** Agent name that was invoked */
 52→  agentName: string;
 53→  /** Estimated Anthropic API cost in USD */
 54→  costUsd: number;
 55→  /** Wall-clock duration in milliseconds */
 56→  durationMs: number;
 57→  /** Number of tool-use turns in the conversation */
 58→  toolTurns: number;
 59→  /** Token usage breakdown */
 60→  tokensUsed: TokenUsage;
 61→  /** Output file path if one was produced */
 62→  outputFile?: string;
 63→  /** True if the output was rescued from text (agent didn't call Write) */
 64→  rescued?: boolean;
 65→}
