  4→import type { AgentDefinition, ModelPreference } from "../../types/index.js";
  5→import { AGENT_TOOL_MAP } from "../../types/index.js";
  6→import {
  7→  INLINED_AGENTS,
  8→  INLINED_SKILLS,
  9→} from "../../generated/agent-registry.js";
 10→
 11→export interface PromptComposerOptions {
 12→  /** Primary workflow ID for registry key lookups (e.g. "artifact-integration"). */
 13→  workflowId?: string;
 14→  /** When true, use inlined registry before falling back to filesystem. */
 15→  useInlined?: boolean;
 16→  /** Additional workflow IDs whose agents/skills are available (e.g. ["congruency-analysis"]). */
 17→  dependencyWorkflows?: string[];
 18→}
 19→
 20→export class PromptComposer {
 21→  private agentCache = new Map<string, AgentDefinition>();
 22→  private skillCache = new Map<string, string>();
 23→  private agentDirs: string[];
 24→  private skillsDirs: string[];
 25→  private workflowId: string;
 26→  private useInlined: boolean;
 27→  private dependencyWorkflows: string[];
 28→
 29→  constructor(
 30→    agentDirs: string[],
 31→    skillsDirs: string[],
 32→    options?: PromptComposerOptions,
 33→  ) {
 34→    this.agentDirs = agentDirs;
 35→    this.skillsDirs = skillsDirs;
 36→    this.workflowId = options?.workflowId ?? "artifact-integration";
 37→    this.useInlined = options?.useInlined ?? false;
 38→    this.dependencyWorkflows = options?.dependencyWorkflows ?? [];
 39→  }
 40→
 41→  /**
 42→   * Load and parse an agent definition. In inlined mode, reads from the
 43→   * build-time registry; otherwise reads from the filesystem.
 44→   */
 45→  loadAgent(name: string): AgentDefinition {
 46→    const cached = this.agentCache.get(name);
 47→    if (cached) return cached;
 48→
 49→    if (this.useInlined) {
 50→      const def = this.loadAgentFromRegistry(name);
 51→      if (def) {
 52→        this.agentCache.set(name, def);
 53→        return def;
 54→      }
 55→      // Fall through to filesystem if not found in registry
 56→    }
 57→
 58→    const filePath = this.resolveAgentPath(name);
 59→    const raw = fs.readFileSync(filePath, "utf-8");
 60→    const { data: frontmatter, content } = matter(raw);
 61→
 62→    const def: AgentDefinition = {
 63→      name: (frontmatter.name as string) ?? name,
 64→      systemPrompt: content.trim(),
 65→      model: parseModelPreference(frontmatter.model),
 66→      skills: parseStringArray(frontmatter.skills),
 67→      allowedTools: AGENT_TOOL_MAP[name] ?? ["Read", "Write"],
 68→    };
 69→
 70→    this.agentCache.set(name, def);
 71→    return def;
 72→  }
 73→
 74→  /**
 75→   * Compose the full system prompt: skill contents prepended to agent body.
 76→   */
 77→  compose(agent: AgentDefinition): string {
 78→    const skillContents: string[] = [];
 79→
 80→    for (const skillName of agent.skills) {
 81→      const skillContent = this.loadSkill(skillName);
 82→      if (skillContent) {
 83→        skillContents.push(
 84→          `<!-- Skill: ${skillName} -->\n${skillContent}`,
 85→        );
 86→      }
 87→    }
 88→
 89→    const prefix =
 90→      skillContents.length > 0
 91→        ? skillContents.join("\n\n---\n\n") + "\n\n---\n\n"
 92→        : "";
 93→
 94→    return prefix + agent.systemPrompt;
 95→  }
 96→
 97→  private loadAgentFromRegistry(name: string): AgentDefinition | null {
 98→    // Try primary workflow, then dependency workflows
 99→    const workflowIds = [this.workflowId, ...this.dependencyWorkflows];
100→    for (const wfId of workflowIds) {
101→      const key = `${wfId}/${name}`;
102→      const inlined = INLINED_AGENTS[key];
103→      if (inlined) {
104→        return {
105→          name: (inlined.frontmatter.name as string) ?? name,
106→          systemPrompt: inlined.body,
107→          model: parseModelPreference(inlined.frontmatter.model),
108→          skills: parseStringArray(inlined.frontmatter.skills),
109→          allowedTools: AGENT_TOOL_MAP[name] ?? ["Read", "Write"],
110→        };
111→      }
112→    }
113→    return null;
114→  }
115→
116→  private resolveAgentPath(name: string): string {
117→    for (const dir of this.agentDirs) {
118→      const candidate = path.join(dir, `${name}.md`);
119→      try {
120→        fs.accessSync(candidate);
121→        return candidate;
122→      } catch {
123→        continue;
124→      }
125→    }
126→    // Fall back to first dir for the error message
127→    return path.join(this.agentDirs[0], `${name}.md`);
128→  }
129→
130→  private loadSkill(name: string): string | null {
131→    const cached = this.skillCache.get(name);
132→    if (cached !== undefined) return cached;
133→
134→    if (this.useInlined) {
135→      const content = this.loadSkillFromRegistry(name);
136→      if (content !== null) {
137→        this.skillCache.set(name, content);
138→        return content;
139→      }
140→      // Fall through to filesystem
141→    }
142→
143→    // Try each skills dir, exact name first then with .md extension
144→    for (const dir of this.skillsDirs) {
145→      const candidates = [
146→        path.join(dir, name),
147→        path.join(dir, `${name}.md`),
148→      ];
149→      for (const skillPath of candidates) {
150→        try {
151→          const content = fs.readFileSync(skillPath, "utf-8");
152→          this.skillCache.set(name, content);
153→          return content;
154→        } catch {
155→          continue;
156→        }
157→      }
158→    }
159→
160→    this.skillCache.set(name, "");
161→    return null;
162→  }
163→
164→  private loadSkillFromRegistry(name: string): string | null {
165→    // Strip .md extension if present (skills are keyed without it)
166→    const baseName = name.replace(/\.md$/, "");
167→    const workflowIds = [this.workflowId, ...this.dependencyWorkflows];
168→    for (const wfId of workflowIds) {
169→      const key = `${wfId}/${baseName}`;
170→      const content = INLINED_SKILLS[key];
171→      if (content !== undefined) return content;
172→    }
173→    return null;
174→  }
175→}
176→
177→function parseModelPreference(value: unknown): ModelPreference {
178→  if (typeof value === "string") {
179→    const lower = value.toLowerCase();
180→    if (lower === "opus" || lower === "sonnet" || lower === "haiku") {
181→      return lower;
182→    }
183→  }
184→  return "inherit";
185→}
186→
187→function parseStringArray(value: unknown): string[] {
188→  if (Array.isArray(value)) {
189→    return value.filter((v): v is string => typeof v === "string");
190→  }
191→  return [];
192→}
