content.content:
  1→/**
  2→ * Generate Quality Synthesis Report — Mechanical Generation
  3→ *
  4→ * Produces:
  5→ * 1. Template `prioritized_actions[]` from artifact_guidance grouping + severity ranking
  6→ * 2. Template `narrative_sections{}` with formulaic executive summary and themes
  7→ * 3. Full markdown report from template
  8→ *
  9→ * The LLM agent then enhances narrative sections only (Key Findings, Recommendations,
 10→ * cross-cutting themes, strategic recommendations).
 11→ */
 12→
 13→import type {
 14→  QualitySynthesisOutput,
 15→  PrioritizedAction,
 16→  NarrativeSections,
 17→  CategoryHealth,
 18→  ArtifactGapCluster,
 19→} from "./normalize-quality-synthesis.js";
 20→
 21→// ---------------------------------------------------------------------------
 22→// Leverage Cluster Computation
 23→// ---------------------------------------------------------------------------
 24→
 25→interface LeverageCluster {
 26→  /** Grouping key — artifact target or category fallback */
 27→  key: string;
 28→  /** Human-readable label for the cluster */
 29→  label: string;
 30→  /** Item IDs in this cluster */
 31→  itemIds: string[];
 32→  /** Max severity across all items */
 33→  maxSeverity: string;
 34→  /** Max cross_dimension_count across items */
 35→  maxCrossDim: number;
 36→  /** Sum of severity weights */
 37→  totalWeight: number;
 38→  /** Whether this targets an existing artifact (update) vs new */
 39→  isUpdate: boolean;
 40→  /** Representative action text */
 41→  action: string;
 42→  /** Representative artifact type */
 43→  artifactType: string;
 44→}
 45→
 46→const SEVERITY_WEIGHT: Record<string, number> = {
 47→  critical: 4,
 48→  high: 3,
 49→  medium: 2,
 50→  low: 1,
 51→};
 52→
 53→const SEVERITY_RANK: Record<string, number> = {
 54→  critical: 0,
 55→  high: 1,
 56→  medium: 2,
 57→  low: 3,
 58→};
 59→
 60→function computeLeverageClusters(
 61→  metrics: QualitySynthesisOutput,
 62→): LeverageCluster[] {
 63→  const items = metrics.unified_items;
 64→
 65→  // Group items by artifact_guidance.target_artifact or artifact_type
 66→  const clusterMap = new Map<string, LeverageCluster>();
 67→
 68→  for (const item of items) {
 69→    const guidance = item.artifact_guidance as
 70→      | { target_artifact?: string; artifact_type?: string; recommended_action?: string }
 71→      | null
 72→      | undefined;
 73→
 74→    let key: string;
 75→    let label: string;
 76→    let isUpdate = false;
 77→    let artifactType = "";
 78→    let action = "";
 79→
 80→    if (guidance?.target_artifact) {
 81→      key = `artifact:${guidance.target_artifact}`;
 82→      label = guidance.target_artifact;
 83→      isUpdate = true;
 84→      artifactType = guidance.artifact_type ?? "";
 85→      action = guidance.recommended_action ?? "";
 86→    } else if (guidance?.artifact_type) {
 87→      key = `type:${guidance.artifact_type}`;
 88→      label = guidance.artifact_type;
 89→      artifactType = guidance.artifact_type;
 90→      action = guidance.recommended_action ?? "";
 91→    } else {
 92→      // Fall back to category grouping
 93→      const category = (item.category as string) ?? "other";
 94→      key = `category:${category}`;
 95→      label = `${category} category items`;
 96→    }
 97→
 98→    const severity = (item.severity as string) ?? "medium";
 99→    const crossDim = (item.cross_dimension_count as number) ?? 1;
100→    const weight = SEVERITY_WEIGHT[severity] ?? 2;
101→    const itemId = (item.id as string) ?? "";
102→
103→    if (clusterMap.has(key)) {
104→      const c = clusterMap.get(key)!;
105→      c.itemIds.push(itemId);
106→      c.totalWeight += weight;
107→      c.maxCrossDim = Math.max(c.maxCrossDim, crossDim);
108→      if ((SEVERITY_RANK[severity] ?? 3) < (SEVERITY_RANK[c.maxSeverity] ?? 3)) {
109→        c.maxSeverity = severity;
110→      }
111→      if (!c.action && action) {
112→        c.action = action;
113→      }
114→    } else {
115→      clusterMap.set(key, {
116→        key,
117→        label,
118→        itemIds: [itemId],
119→        maxSeverity: severity,
120→        maxCrossDim: crossDim,
121→        totalWeight: weight,
122→        isUpdate,
123→        action,
124→        artifactType,
125→      });
126→    }
127→  }
128→
129→  // Sort clusters by leverage score: totalWeight × maxCrossDim
130→  const clusters = [...clusterMap.values()];
131→  clusters.sort((a, b) => {
132→    const scoreA = a.totalWeight * a.maxCrossDim;
133→    const scoreB = b.totalWeight * b.maxCrossDim;
134→    if (scoreB !== scoreA) return scoreB - scoreA;
135→    return b.itemIds.length - a.itemIds.length;
136→  });
137→
138→  return clusters;
139→}
140→
141→// ---------------------------------------------------------------------------
142→// Category-specific recommendations for uncovered concepts
143→// ---------------------------------------------------------------------------
144→
145→const CATEGORY_RECOMMENDATIONS: Record<string, {
146→  action: (count: number) => string;
147→  artifactType: string;
148→}> = {
149→  data: {
150→    action: (n) => `Add a data dictionary or ERD specifying field definitions, relationships, and constraints for ${n} undocumented data concept${n === 1 ? "" : "s"}`,
151→    artifactType: "data dictionary / ERD",
152→  },
153→  interface: {
154→    action: (n) => `Add UI/UX specifications (wireframes, component specs, or interaction flows) for ${n} undocumented interface concept${n === 1 ? "" : "s"}`,
155→    artifactType: "UI/UX specification",
156→  },
157→  logic: {
158→    action: (n) => `Add business logic specifications (state machines, workflow diagrams, or decision rules) for ${n} undocumented logic concept${n === 1 ? "" : "s"}`,
159→    artifactType: "business logic specification",
160→  },
161→  testing: {
162→    action: (n) => `Add a test strategy or test plan covering ${n} untested concept${n === 1 ? "" : "s"} (acceptance criteria, test scenarios, coverage targets)`,
163→    artifactType: "test strategy / test plan",
164→  },
165→  architecture: {
166→    action: (n) => `Add architecture documentation (system diagrams, API contracts, or integration specs) for ${n} undocumented architecture concept${n === 1 ? "" : "s"}`,
167→    artifactType: "architecture specification",
168→  },
169→  security: {
170→    action: (n) => `Add security specifications (threat model, access control matrix, or auth flows) for ${n} undocumented security concept${n === 1 ? "" : "s"}`,
171→    artifactType: "security specification",
172→  },
173→  other: {
174→    action: (n) => `Add supplementary documentation (glossary, domain model, or requirements addendum) for ${n} concept${n === 1 ? "" : "s"} that lack artifact coverage`,
175→    artifactType: "supplementary documentation",
176→  },
177→};
178→
179→// ---------------------------------------------------------------------------
180→// Prioritized Actions from Clusters
181→// ---------------------------------------------------------------------------
182→
183→function generatePrioritizedActions(
184→  clusters: LeverageCluster[],
185→  artifactGapSummary: ArtifactGapCluster[],
186→): PrioritizedAction[] {
187→  const actions: PrioritizedAction[] = [];
188→  const topClusters = clusters.slice(0, 15);
189→
190→  // Track which gap clusters get consumed by artifact-specific actions
191→  // so we can append uncovered ones at the end
192→  const consumedGapTypes = new Set<string>();
193→
194→  for (let i = 0; i < topClusters.length; i++) {
195→    const c = topClusters[i];
196→    const verb = c.isUpdate ? "Update" : "Create";
197→    const target = c.artifactType || c.label;
198→
199→    let actionText: string;
200→    let actionType: "update_artifact" | "create_artifact";
201→    let targetArtifact: string | null = null;
202→    let suggestedArtifactType: string | null = null;
203→
204→    if (c.action) {
205→      actionText = c.action;
206→      actionType = c.isUpdate ? "update_artifact" : "create_artifact";
207→      if (c.isUpdate) {
208→        targetArtifact = c.label;
209→      } else {
210→        suggestedArtifactType = c.artifactType || null;
211→      }
212→    } else if (c.key.startsWith("category:")) {
213→      // Category fallback — try to find an artifact gap cluster that covers these items
214→      const cat = c.key.replace("category:", "");
215→
216→      // Look for the best-matching gap cluster whose items overlap with this category cluster
217→      let bestGap: ArtifactGapCluster | undefined;
218→      let bestOverlap = 0;
219→      const clusterItemSet = new Set(c.itemIds);
220→      for (const gap of artifactGapSummary) {
221→        if (consumedGapTypes.has(gap.artifact_type)) continue;
222→        const overlap = gap.source_item_ids.filter((id) => clusterItemSet.has(id)).length;
223→        if (overlap > bestOverlap) {
224→          bestOverlap = overlap;
225→          bestGap = gap;
226→        }
227→      }
228→
229→      if (bestGap && bestOverlap >= 2) {
230→        consumedGapTypes.add(bestGap.artifact_type);
231→        if (bestGap.target_artifact) {
232→          actionText = `Update ${bestGap.target_artifact} to resolve ${c.itemIds.length} ${cat}-related findings`;
233→          actionType = "update_artifact";
234→          targetArtifact = bestGap.target_artifact;
235→        } else {
236→          actionText = `Create ${bestGap.artifact_type} covering ${c.itemIds.length} unspecified ${cat} concepts`;
237→          actionType = "create_artifact";
238→          suggestedArtifactType = bestGap.artifact_type;
239→        }
240→      } else {
241→        // No gap cluster match — produce a category-specific actionable recommendation
242→        const n = c.itemIds.length;
243→        const catRec = CATEGORY_RECOMMENDATIONS[cat];
244→        if (catRec) {
245→          actionText = `${catRec.action(n)}`;
246→          suggestedArtifactType = catRec.artifactType;
247→        } else {
248→          actionText = `Create a specification document detailing ${n} uncovered ${cat} concept${n === 1 ? "" : "s"}`;
249→          suggestedArtifactType = `${cat} specification`;
250→        }
251→        actionType = "create_artifact";
252→      }
253→    } else {
254→      actionText = `${verb} ${target} to resolve ${c.itemIds.length} related findings`;
255→      actionType = c.isUpdate ? "update_artifact" : "create_artifact";
256→      if (c.isUpdate) {
257→        targetArtifact = c.label;
258→      } else {
259→        suggestedArtifactType = c.artifactType || null;
260→      }
261→    }
262→
263→    if (c.artifactType) consumedGapTypes.add(c.artifactType);
264→
265→    const rationale = [
266→      `Resolves ${c.itemIds.length} finding(s)`,
267→      c.maxCrossDim > 1 ? `spanning ${c.maxCrossDim} analysis dimensions` : "",
268→      `with ${c.maxSeverity} maximum severity.`,
269→      c.isUpdate ? "Lower effort — updates an existing artifact." : "",
270→    ]
271→      .filter(Boolean)
272→      .join(" ");
273→
274→    // Effort heuristic: update=low, create with few items=medium, create with many=high
275→    let effort: string;
276→    if (c.isUpdate) {
277→      effort = c.itemIds.length <= 3 ? "low" : "medium";
278→    } else {
279→      effort = c.itemIds.length <= 5 ? "medium" : "high";
280→    }
281→
282→    actions.push({
283→      rank: i + 1,
284→      action_type: actionType,
285→      action: actionText,
286→      rationale,
287→      severity: c.maxSeverity,
288→      effort,
289→      target_artifact: targetArtifact,
290→      suggested_artifact_type: suggestedArtifactType,
291→      affected_items: c.itemIds,
292→      expected_score_impact: `Addresses ${c.itemIds.length} findings. Cross-dimensional impact: ${c.maxCrossDim} source(s).`,
293→    });
294→  }
295→
296→  // Append uncovered gap clusters with high finding counts as "create new artifact" actions
297→  for (const gap of artifactGapSummary) {
298→    if (consumedGapTypes.has(gap.artifact_type)) continue;
299→    if (gap.finding_count < 3) continue; // Only surface significant gaps
300→    if (gap.target_artifact) continue; // Already covered by artifact-specific clusters
301→
302→    const crossSources = gap.sources.length;
303→    actions.push({
304→      rank: actions.length + 1,
305→      action_type: "create_artifact",
306→      action: `Create ${gap.artifact_type} to specify ${gap.finding_count} currently ungrounded concepts`,
307→      rationale: `${gap.finding_count} findings across ${crossSources} analysis source(s) point to missing ${gap.artifact_type} documentation. Creating this artifact would ground these concepts and improve both coverage and congruency scores.`,
308→      severity: gap.severity_counts.critical > 0 ? "critical" : gap.severity_counts.high > 0 ? "high" : "medium",
309→      effort: gap.finding_count <= 5 ? "medium" : "high",
310→      target_artifact: null,
311→      suggested_artifact_type: gap.artifact_type,
312→      affected_items: gap.source_item_ids,
313→      expected_score_impact: `Would ground ${gap.finding_count} unspecified concepts. Cross-dimensional impact: ${crossSources} source(s).`,
314→    });
315→  }
316→
317→  return actions;
318→}
319→
320→// ---------------------------------------------------------------------------
321→// Template Narrative Sections
322→// ---------------------------------------------------------------------------
323→
324→function generateNarrativeSections(
325→  metrics: QualitySynthesisOutput,
326→  actions: PrioritizedAction[],
327→): NarrativeSections {
328→  const qo = metrics.quality_overview;
329→  const stats = metrics.summary_stats;
330→
331→  // Executive summary — template with fill-ins
332→  const healthDesc: Record<string, string> = {
333→    critical: "in critical condition requiring immediate attention",
334→    at_risk: "at risk with several areas needing attention",
335→    needs_attention: "generally acceptable but with areas needing improvement",
336→    healthy: "in good health with only minor improvements needed",
337→  };
338→
339→  const sourceList: string[] = [];
340→  if (qo.coverage_score !== null) sourceList.push("coverage");
341→  if (qo.congruency_score !== null) sourceList.push("congruency");
342→  if (qo.impact_blast_radius !== null) sourceList.push("impact");
343→
344→  const parts: string[] = [
345→    `Quality synthesis across ${sourceList.length} analysis dimension(s) (${sourceList.join(", ")}) indicates the project is ${healthDesc[qo.composite_health] ?? "in an undetermined state"}.`,
346→  ];
347→
348→  if (qo.coverage_score !== null) {
349→    parts.push(`Coverage quality stands at ${qo.coverage_score.toFixed(2)}/1.00.`);
350→  }
351→  if (qo.congruency_score !== null) {
352→    parts.push(`Congruency score is ${qo.congruency_score}%.`);
353→  }
354→  if (qo.impact_blast_radius !== null) {
355→    parts.push(`Impact blast radius is ${qo.impact_blast_radius.toFixed(1)}%.`);
356→  }
357→
358→  parts.push(
359→    `A total of ${stats.total_items} findings were identified (${stats.by_severity.critical ?? 0} critical, ${stats.by_severity.high ?? 0} high, ${stats.by_severity.medium ?? 0} medium, ${stats.by_severity.low ?? 0} low).`,
360→  );
361→
362→  if (actions.length > 0) {
363→    parts.push(`The highest-priority action is: ${actions[0].action}`);
364→  }
365→
366→  // Cross-cutting themes — derive from category health
367→  const themes: string[] = [];
368→  const catHealth = metrics.category_health;
369→  const criticalCats = Object.entries(catHealth).filter(
370→    ([, h]) => h.health_status === "critical",
371→  );
372→  const atRiskCats = Object.entries(catHealth).filter(
373→    ([, h]) => h.health_status === "at_risk",
374→  );
375→
376→  if (criticalCats.length > 0) {
377→    themes.push(
378→      `Critical quality gaps in ${criticalCats.map(([c]) => c).join(", ")} categories — these areas have multiple critical findings and require immediate documentation improvements.`,
379→    );
380→  }
381→  if (atRiskCats.length > 0) {
382→    themes.push(
383→      `At-risk areas in ${atRiskCats.map(([c]) => c).join(", ")} categories — these have elevated severity findings that should be addressed before they become critical.`,
384→    );
385→  }
386→  if (stats.cross_cutting_node_count > 0) {
387→    themes.push(
388→      `${stats.cross_cutting_node_count} cross-cutting node(s) flagged by multiple analysis dimensions — these represent systemic documentation gaps that affect coverage, congruency, and/or impact simultaneously.`,
389→    );
390→  }
391→  if (themes.length === 0) {
392→    themes.push("No critical cross-cutting themes identified — quality posture is generally healthy.");
393→  }
394→
395→  // Strategic recommendations — top 3 actions rephrased
396→  const strategic = actions.slice(0, 3).map(
397→    (a) => `Priority ${a.rank}: ${a.action}`,
398→  );
399→  if (strategic.length === 0) {
400→    strategic.push("No high-priority actions identified — maintain current documentation quality.");
401→  }
402→
403→  return {
404→    executive_summary: parts.join(" "),
405→    cross_cutting_themes: themes,
406→    strategic_recommendations: strategic,
407→  };
408→}
409→
410→// ---------------------------------------------------------------------------
411→// Markdown Report Generation
412→// ---------------------------------------------------------------------------
413→
414→function healthEmoji(status: string): string {
415→  switch (status) {
416→    case "critical": return "CRITICAL";
417→    case "at_risk": return "AT RISK";
418→    case "needs_attention": return "NEEDS ATTENTION";
419→    case "healthy": return "HEALTHY";
420→    default: return status.toUpperCase();
421→  }
422→}
423→
424→function severityLabel(sev: string): string {
425→  switch (sev) {
426→    case "critical": return "Critical";
427→    case "high": return "High";
428→    case "medium": return "Medium";
429→    case "low": return "Low";
430→    default: return sev;
431→  }
432→}
433→
434→export function generateQualitySynthesisMarkdown(opts: {
435→  metrics: QualitySynthesisOutput;
436→  actions: PrioritizedAction[];
437→  narrative: NarrativeSections;
438→}): string {
439→  const { metrics, actions, narrative } = opts;
440→  const qo = metrics.quality_overview;
441→  const stats = metrics.summary_stats;
442→  const meta = metrics.metadata;
443→  const lines: string[] = [];
444→
445→  lines.push(`# Quality Synthesis Report v${meta.report_version}`);
446→  lines.push("");
447→
448→  // Executive Summary
449→  lines.push("## Executive Summary");
450→  lines.push("");
451→  lines.push(narrative.executive_summary);
452→  lines.push("");
453→
454→  // Data Sources
455→  lines.push("**Data Sources Analyzed:**");
456→  lines.push("");
457→  lines.push("| Source | Status | Key Metric |");
458→  lines.push("|--------|--------|------------|");
459→
460→  const covStatus = qo.coverage_score !== null ? "Available" : "Missing";
461→  const covMetric = qo.coverage_score !== null ? `Overall Score: ${qo.coverage_score.toFixed(2)}` : "N/A";
462→  lines.push(`| Coverage Analysis | ${covStatus} | ${covMetric} |`);
463→
464→  const congStatus = qo.congruency_score !== null ? "Available" : "Missing";
465→  const congMetric = qo.congruency_score !== null ? `Congruency: ${qo.congruency_score}%` : "N/A";
466→  lines.push(`| Congruency Analysis | ${congStatus} | ${congMetric} |`);
467→
468→  const impStatus = qo.impact_blast_radius !== null ? "Available" : "Missing";
469→  const impMetric = qo.impact_blast_radius !== null ? `Blast Radius: ${qo.impact_blast_radius.toFixed(1)}%` : "N/A";
470→  lines.push(`| Impact Analysis | ${impStatus} | ${impMetric} |`);
471→  lines.push("");
472→
473→  lines.push(`**Composite Health: ${healthEmoji(qo.composite_health)}**`);
474→  lines.push("");
475→
476→  // What You Need To Do
477→  lines.push("## What You Need To Do");
478→  lines.push("");
479→
480→  if (actions.length === 0) {
481→    lines.push("No prioritized actions identified — quality posture is healthy.");
482→    lines.push("");
483→  } else {
484→    for (const a of actions) {
485→      lines.push(`### ${a.rank}. ${a.action}`);
486→      lines.push(`**Severity**: ${severityLabel(a.severity)} | **Effort**: ${a.effort} | **Resolves**: ${a.affected_items.length} finding(s)`);
487→      lines.push("");
488→      lines.push(a.rationale);
489→      lines.push("");
490→      lines.push(`**Expected Outcome**: ${a.expected_score_impact}`);
491→      lines.push("");
492→      lines.push(`**Findings addressed**: ${a.affected_items.join(", ")}`);
493→      lines.push("");
494→    }
495→  }
496→
497→  // Quality Overview
498→  lines.push("## Quality Overview");
499→  lines.push("");
500→  lines.push("| Metric | Value | Status |");
501→  lines.push("|--------|-------|--------|");
502→
503→  const covGrade = qo.coverage_score !== null
504→    ? (qo.coverage_score >= 0.85 ? "Good" : qo.coverage_score >= 0.7 ? "Fair" : "Poor")
505→    : "N/A";
506→  lines.push(`| Coverage Quality Score | ${qo.coverage_score !== null ? `${qo.coverage_score.toFixed(2)} / 1.00` : "N/A"} | ${covGrade} |`);
507→
508→  const congGrade = qo.congruency_score !== null
509→    ? (qo.congruency_score >= 75 ? "Good" : qo.congruency_score >= 55 ? "Fair" : "Poor")
510→    : "N/A";
511→  lines.push(`| Congruency Score | ${qo.congruency_score !== null ? `${qo.congruency_score}%` : "N/A"} | ${congGrade} |`);
512→
513→  const impGrade = qo.impact_blast_radius !== null
514→    ? (qo.impact_blast_radius <= 20 ? "Low" : qo.impact_blast_radius <= 40 ? "Medium" : "High")
515→    : "N/A";
516→  lines.push(`| Impact Blast Radius | ${qo.impact_blast_radius !== null ? `${qo.impact_blast_radius.toFixed(1)}%` : "N/A"} | ${impGrade} |`);
517→  lines.push("");
518→
519→  // Cross-Cutting Concerns
520→  lines.push("## Cross-Cutting Concerns");
521→  lines.push("");
522→
523→  if (metrics.cross_cutting_nodes.length === 0) {
524→    lines.push("No cross-cutting nodes identified.");
525→    lines.push("");
526→  } else {
527→    for (const node of metrics.cross_cutting_nodes) {
528→      const nodeName = node.node_name || node.node_id;
529→      lines.push(`### ${nodeName} (flagged by ${node.dimensions_affected} sources)`);
530→      lines.push("");
531→      if (node.node_type) {
532→        lines.push(`**Type**: ${node.node_type}`);
533→        lines.push("");
534→      }
535→      const bySource = new Map<string, string[]>();
536→      for (const issue of node.issues) {
537→        if (!bySource.has(issue.source)) bySource.set(issue.source, []);
538→        bySource.get(issue.source)!.push(`${issue.summary} (${issue.severity})`);
539→      }
540→      for (const [source, summaries] of bySource) {
541→        lines.push(`- **${source}**: ${summaries.join("; ")}`);
542→      }
543→      lines.push("");
544→    }
545→  }
546→
547→  // Cross-Cutting Themes
548→  lines.push("## Cross-Cutting Themes");
549→  lines.push("");
550→  for (const theme of narrative.cross_cutting_themes) {
551→    lines.push(`- ${theme}`);
552→  }
553→  lines.push("");
554→
555→  // Category Health Dashboard
556→  lines.push("## Category Health Dashboard");
557→  lines.push("");
558→  lines.push("| Category | Coverage Score | Congruency Issues | Impact Risk | Items | Health |");
559→  lines.push("|----------|---------------|-------------------|-------------|-------|--------|");
560→
561→  const categories = ["scope", "architecture", "technical", "sequencing", "interface", "data", "logic", "testing"];
562→  for (const cat of categories) {
563→    const h = metrics.category_health[cat] as CategoryHealth | undefined;
564→    if (!h) continue;
565→    const covStr = h.coverage_score !== null ? h.coverage_score.toFixed(2) : "—";
566→    const riskStr = h.impact_risk ?? "—";
567→    lines.push(`| ${cat} | ${covStr} | ${h.congruency_issues} | ${riskStr} | ${h.total_items} | ${healthEmoji(h.health_status)} |`);
568→  }
569→  lines.push("");
570→
571→  // Summary Stats
572→  lines.push("## Finding Distribution");
573→  lines.push("");
574→  lines.push("| Severity | Count |");
575→  lines.push("|----------|-------|");
576→  for (const sev of ["critical", "high", "medium", "low"]) {
577→    lines.push(`| ${severityLabel(sev)} | ${stats.by_severity[sev] ?? 0} |`);
578→  }
579→  lines.push("");
580→  lines.push("| Source | Count |");
581→  lines.push("|--------|-------|");
582→  for (const src of ["coverage", "congruency", "impact"]) {
583→    lines.push(`| ${src} | ${stats.by_source[src] ?? 0} |`);
584→  }
585→  lines.push("");
586→
587→  // Strategic Recommendations
588→  lines.push("## Strategic Recommendations");
589→  lines.push("");
590→  for (let i = 0; i < narrative.strategic_recommendations.length; i++) {
591→    lines.push(`${i + 1}. ${narrative.strategic_recommendations[i]}`);
592→  }
593→  lines.push("");
594→
595→  // Data Availability
596→  lines.push("## Data Availability");
597→  lines.push("");
598→  const available = [
599→    meta.sources_available.coverage ? "Coverage Analysis" : null,
600→    meta.sources_available.congruency.length > 0 ? "Congruency Analysis" : null,
601→    meta.sources_available.impact ? "Impact Analysis" : null,
602→  ].filter(Boolean);
603→  lines.push(`**Sources included**: ${available.join(", ") || "None"}`);
604→  lines.push(`**Sources missing**: ${meta.sources_missing.length > 0 ? meta.sources_missing.join(", ") : "None"}`);
605→  lines.push("");
606→
607→  if (meta.sources_missing.length > 0) {
608→    lines.push(
609→      `Note: Without ${meta.sources_missing.join(" and ")} analysis, the synthesis is limited to ${available.length} dimension(s). Run the missing analyses for a more complete quality picture.`,
610→    );
611→    lines.push("");
612→  }
613→
614→  lines.push("---");
615→  lines.push("*Generated by quality-synthesis plugin v1.0.0*");
616→  lines.push("");
617→
618→  return lines.join("\n");
619→}
620→
621→// ---------------------------------------------------------------------------
622→// Main Export
623→// ---------------------------------------------------------------------------
624→
625→export interface GenerateQualitySynthesisReportResult {
626→  actions: PrioritizedAction[];
627→  narrative: NarrativeSections;
628→  markdown: string;
629→}
630→
631→export function generateQualitySynthesisReport(
632→  metrics: QualitySynthesisOutput,
633→): GenerateQualitySynthesisReportResult {
634→  const clusters = computeLeverageClusters(metrics);
635→  const actions = generatePrioritizedActions(clusters, metrics.artifact_gap_summary ?? []);
636→  const narrative = generateNarrativeSections(metrics, actions);
637→  const markdown = generateQualitySynthesisMarkdown({ metrics, actions, narrative });
638→
639→  return { actions, narrative, markdown };
640→}
