/**
 * Generate Quality Synthesis Report — Mechanical Generation
 *
 * Produces:
 * 1. Template `prioritized_actions[]` from artifact_guidance grouping + severity ranking
 * 2. Template `narrative_sections{}` with formulaic executive summary and themes
 * 3. Full markdown report from template
 *
 * The LLM agent then enhances narrative sections only (Key Findings, Recommendations,
 * cross-cutting themes, strategic recommendations).
 */

import type {
  QualitySynthesisOutput,
  PrioritizedAction,
  NarrativeSections,
  CategoryHealth,
  ArtifactGapCluster,
} from "./normalize-quality-synthesis.js";

// ---------------------------------------------------------------------------
// Leverage Cluster Computation
// ---------------------------------------------------------------------------

interface LeverageCluster {
  /** Grouping key — artifact target or category fallback */
  key: string;
  /** Human-readable label for the cluster */
  label: string;
  /** Item IDs in this cluster */
  itemIds: string[];
  /** Max severity across all items */
  maxSeverity: string;
  /** Max cross_dimension_count across items */
  maxCrossDim: number;
  /** Sum of severity weights */
  totalWeight: number;
  /** Whether this targets an existing artifact (update) vs new */
  isUpdate: boolean;
  /** Representative action text */
  action: string;
  /** Representative artifact type */
  artifactType: string;
}

const SEVERITY_WEIGHT: Record<string, number> = {
  critical: 4,
  high: 3,
  medium: 2,
  low: 1,
};

const SEVERITY_RANK: Record<string, number> = {
  critical: 0,
  high: 1,
  medium: 2,
  low: 3,
};

function computeLeverageClusters(
  metrics: QualitySynthesisOutput,
): LeverageCluster[] {
  const items = metrics.unified_items;

  // Group items by artifact_guidance.target_artifact or artifact_type
  const clusterMap = new Map<string, LeverageCluster>();

  for (const item of items) {
    const guidance = item.artifact_guidance as
      | { target_artifact?: string; artifact_type?: string; recommended_action?: string }
      | null
      | undefined;

    let key: string;
    let label: string;
    let isUpdate = false;
    let artifactType = "";
    let action = "";

    if (guidance?.target_artifact) {
      key = `artifact:${guidance.target_artifact}`;
      label = guidance.target_artifact;
      isUpdate = true;
      artifactType = guidance.artifact_type ?? "";
      action = guidance.recommended_action ?? "";
    } else if (guidance?.artifact_type) {
      key = `type:${guidance.artifact_type}`;
      label = guidance.artifact_type;
      artifactType = guidance.artifact_type;
      action = guidance.recommended_action ?? "";
    } else {
      // Fall back to category grouping
      const category = (item.category as string) ?? "other";
      key = `category:${category}`;
      label = `${category} category items`;
    }

    const severity = (item.severity as string) ?? "medium";
    const crossDim = (item.cross_dimension_count as number) ?? 1;
    const weight = SEVERITY_WEIGHT[severity] ?? 2;
    const itemId = (item.id as string) ?? "";

    if (clusterMap.has(key)) {
      const c = clusterMap.get(key)!;
      c.itemIds.push(itemId);
      c.totalWeight += weight;
      c.maxCrossDim = Math.max(c.maxCrossDim, crossDim);
      if ((SEVERITY_RANK[severity] ?? 3) < (SEVERITY_RANK[c.maxSeverity] ?? 3)) {
        c.maxSeverity = severity;
      }
      if (!c.action && action) {
        c.action = action;
      }
    } else {
      clusterMap.set(key, {
        key,
        label,
        itemIds: [itemId],
        maxSeverity: severity,
        maxCrossDim: crossDim,
        totalWeight: weight,
        isUpdate,
        action,
        artifactType,
      });
    }
  }

  // Sort clusters by leverage score: totalWeight × maxCrossDim
  const clusters = [...clusterMap.values()];
  clusters.sort((a, b) => {
    const scoreA = a.totalWeight * a.maxCrossDim;
    const scoreB = b.totalWeight * b.maxCrossDim;
    if (scoreB !== scoreA) return scoreB - scoreA;
    return b.itemIds.length - a.itemIds.length;
  });

  return clusters;
}

// ---------------------------------------------------------------------------
// Category-specific recommendations for uncovered concepts
// ---------------------------------------------------------------------------

const CATEGORY_RECOMMENDATIONS: Record<string, {
  action: (count: number) => string;
  artifactType: string;
}> = {
  data: {
    action: (n) => `Add a data dictionary or ERD specifying field definitions, relationships, and constraints for ${n} undocumented data concept${n === 1 ? "" : "s"}`,
    artifactType: "data dictionary / ERD",
  },
  interface: {
    action: (n) => `Add UI/UX specifications (wireframes, component specs, or interaction flows) for ${n} undocumented interface concept${n === 1 ? "" : "s"}`,
    artifactType: "UI/UX specification",
  },
  logic: {
    action: (n) => `Add business logic specifications (state machines, workflow diagrams, or decision rules) for ${n} undocumented logic concept${n === 1 ? "" : "s"}`,
    artifactType: "business logic specification",
  },
  testing: {
    action: (n) => `Add a test strategy or test plan covering ${n} untested concept${n === 1 ? "" : "s"} (acceptance criteria, test scenarios, coverage targets)`,
    artifactType: "test strategy / test plan",
  },
  architecture: {
    action: (n) => `Add architecture documentation (system diagrams, API contracts, or integration specs) for ${n} undocumented architecture concept${n === 1 ? "" : "s"}`,
    artifactType: "architecture specification",
  },
  security: {
    action: (n) => `Add security specifications (threat model, access control matrix, or auth flows) for ${n} undocumented security concept${n === 1 ? "" : "s"}`,
    artifactType: "security specification",
  },
  other: {
    action: (n) => `Add supplementary documentation (glossary, domain model, or requirements addendum) for ${n} concept${n === 1 ? "" : "s"} that lack artifact coverage`,
    artifactType: "supplementary documentation",
  },
};

// ---------------------------------------------------------------------------
// Prioritized Actions from Clusters
// ---------------------------------------------------------------------------

function generatePrioritizedActions(
  clusters: LeverageCluster[],
  artifactGapSummary: ArtifactGapCluster[],
): PrioritizedAction[] {
  const actions: PrioritizedAction[] = [];
  const topClusters = clusters.slice(0, 15);

  // Track which gap clusters get consumed by artifact-specific actions
  // so we can append uncovered ones at the end
  const consumedGapTypes = new Set<string>();

  for (let i = 0; i < topClusters.length; i++) {
    const c = topClusters[i];
    const verb = c.isUpdate ? "Update" : "Create";
    const target = c.artifactType || c.label;

    let actionText: string;
    let actionType: "update_artifact" | "create_artifact";
    let targetArtifact: string | null = null;
    let suggestedArtifactType: string | null = null;

    if (c.action) {
      actionText = c.action;
      actionType = c.isUpdate ? "update_artifact" : "create_artifact";
      if (c.isUpdate) {
        targetArtifact = c.label;
      } else {
        suggestedArtifactType = c.artifactType || null;
      }
    } else if (c.key.startsWith("category:")) {
      // Category fallback — try to find an artifact gap cluster that covers these items
      const cat = c.key.replace("category:", "");

      // Look for the best-matching gap cluster whose items overlap with this category cluster
      let bestGap: ArtifactGapCluster | undefined;
      let bestOverlap = 0;
      const clusterItemSet = new Set(c.itemIds);
      for (const gap of artifactGapSummary) {
        if (consumedGapTypes.has(gap.artifact_type)) continue;
        const overlap = gap.source_item_ids.filter((id) => clusterItemSet.has(id)).length;
        if (overlap > bestOverlap) {
          bestOverlap = overlap;
          bestGap = gap;
        }
      }

      if (bestGap && bestOverlap >= 2) {
        consumedGapTypes.add(bestGap.artifact_type);
        if (bestGap.target_artifact) {
          actionText = `Update ${bestGap.target_artifact} to resolve ${c.itemIds.length} ${cat}-related findings`;
          actionType = "update_artifact";
          targetArtifact = bestGap.target_artifact;
        } else {
          actionText = `Create ${bestGap.artifact_type} covering ${c.itemIds.length} unspecified ${cat} concepts`;
          actionType = "create_artifact";
          suggestedArtifactType = bestGap.artifact_type;
        }
      } else {
        // No gap cluster match — produce a category-specific actionable recommendation
        const n = c.itemIds.length;
        const catRec = CATEGORY_RECOMMENDATIONS[cat];
        if (catRec) {
          actionText = `${catRec.action(n)}`;
          suggestedArtifactType = catRec.artifactType;
        } else {
          actionText = `Create a specification document detailing ${n} uncovered ${cat} concept${n === 1 ? "" : "s"}`;
          suggestedArtifactType = `${cat} specification`;
        }
        actionType = "create_artifact";
      }
    } else {
      actionText = `${verb} ${target} to resolve ${c.itemIds.length} related findings`;
      actionType = c.isUpdate ? "update_artifact" : "create_artifact";
      if (c.isUpdate) {
        targetArtifact = c.label;
      } else {
        suggestedArtifactType = c.artifactType || null;
      }
    }

    if (c.artifactType) consumedGapTypes.add(c.artifactType);

    const rationale = [
      `Resolves ${c.itemIds.length} finding(s)`,
      c.maxCrossDim > 1 ? `spanning ${c.maxCrossDim} analysis dimensions` : "",
      `with ${c.maxSeverity} maximum severity.`,
      c.isUpdate ? "Lower effort — updates an existing artifact." : "",
    ]
      .filter(Boolean)
      .join(" ");

    // Effort heuristic: update=low, create with few items=medium, create with many=high
    let effort: string;
    if (c.isUpdate) {
      effort = c.itemIds.length <= 3 ? "low" : "medium";
    } else {
      effort = c.itemIds.length <= 5 ? "medium" : "high";
    }

    actions.push({
      rank: i + 1,
      action_type: actionType,
      action: actionText,
      rationale,
      severity: c.maxSeverity,
      effort,
      target_artifact: targetArtifact,
      suggested_artifact_type: suggestedArtifactType,
      affected_items: c.itemIds,
      expected_score_impact: `Addresses ${c.itemIds.length} findings. Cross-dimensional impact: ${c.maxCrossDim} source(s).`,
    });
  }

  // Append uncovered gap clusters with high finding counts as "create new artifact" actions
  for (const gap of artifactGapSummary) {
    if (consumedGapTypes.has(gap.artifact_type)) continue;
    if (gap.finding_count < 3) continue; // Only surface significant gaps
    if (gap.target_artifact) continue; // Already covered by artifact-specific clusters

    const crossSources = gap.sources.length;
    actions.push({
      rank: actions.length + 1,
      action_type: "create_artifact",
      action: `Create ${gap.artifact_type} to specify ${gap.finding_count} currently ungrounded concepts`,
      rationale: `${gap.finding_count} findings across ${crossSources} analysis source(s) point to missing ${gap.artifact_type} documentation. Creating this artifact would ground these concepts and improve both coverage and congruency scores.`,
      severity: gap.severity_counts.critical > 0 ? "critical" : gap.severity_counts.high > 0 ? "high" : "medium",
      effort: gap.finding_count <= 5 ? "medium" : "high",
      target_artifact: null,
      suggested_artifact_type: gap.artifact_type,
      affected_items: gap.source_item_ids,
      expected_score_impact: `Would ground ${gap.finding_count} unspecified concepts. Cross-dimensional impact: ${crossSources} source(s).`,
    });
  }

  return actions;
}

// ---------------------------------------------------------------------------
// Template Narrative Sections
// ---------------------------------------------------------------------------

function generateNarrativeSections(
  metrics: QualitySynthesisOutput,
  actions: PrioritizedAction[],
): NarrativeSections {
  const qo = metrics.quality_overview;
  const stats = metrics.summary_stats;

  // Executive summary — template with fill-ins
  const healthDesc: Record<string, string> = {
    critical: "in critical condition requiring immediate attention",
    at_risk: "at risk with several areas needing attention",
    needs_attention: "generally acceptable but with areas needing improvement",
    healthy: "in good health with only minor improvements needed",
  };

  const sourceList: string[] = [];
  if (qo.coverage_score !== null) sourceList.push("coverage");
  if (qo.congruency_score !== null) sourceList.push("congruency");
  if (qo.impact_blast_radius !== null) sourceList.push("impact");

  const parts: string[] = [
    `Quality synthesis across ${sourceList.length} analysis dimension(s) (${sourceList.join(", ")}) indicates the project is ${healthDesc[qo.composite_health] ?? "in an undetermined state"}.`,
  ];

  if (qo.coverage_score !== null) {
    parts.push(`Coverage quality stands at ${qo.coverage_score.toFixed(2)}/1.00.`);
  }
  if (qo.congruency_score !== null) {
    parts.push(`Congruency score is ${qo.congruency_score}%.`);
  }
  if (qo.impact_blast_radius !== null) {
    parts.push(`Impact blast radius is ${qo.impact_blast_radius.toFixed(1)}%.`);
  }

  parts.push(
    `A total of ${stats.total_items} findings were identified (${stats.by_severity.critical ?? 0} critical, ${stats.by_severity.high ?? 0} high, ${stats.by_severity.medium ?? 0} medium, ${stats.by_severity.low ?? 0} low).`,
  );

  if (actions.length > 0) {
    parts.push(`The highest-priority action is: ${actions[0].action}`);
  }

  // Cross-cutting themes — derive from category health
  const themes: string[] = [];
  const catHealth = metrics.category_health;
  const criticalCats = Object.entries(catHealth).filter(
    ([, h]) => h.health_status === "critical",
  );
  const atRiskCats = Object.entries(catHealth).filter(
    ([, h]) => h.health_status === "at_risk",
  );

  if (criticalCats.length > 0) {
    themes.push(
      `Critical quality gaps in ${criticalCats.map(([c]) => c).join(", ")} categories — these areas have multiple critical findings and require immediate documentation improvements.`,
    );
  }
  if (atRiskCats.length > 0) {
    themes.push(
      `At-risk areas in ${atRiskCats.map(([c]) => c).join(", ")} categories — these have elevated severity findings that should be addressed before they become critical.`,
    );
  }
  if (stats.cross_cutting_node_count > 0) {
    themes.push(
      `${stats.cross_cutting_node_count} cross-cutting node(s) flagged by multiple analysis dimensions — these represent systemic documentation gaps that affect coverage, congruency, and/or impact simultaneously.`,
    );
  }
  if (themes.length === 0) {
    themes.push("No critical cross-cutting themes identified — quality posture is generally healthy.");
  }

  // Strategic recommendations — top 3 actions rephrased
  const strategic = actions.slice(0, 3).map(
    (a) => `Priority ${a.rank}: ${a.action}`,
  );
  if (strategic.length === 0) {
    strategic.push("No high-priority actions identified — maintain current documentation quality.");
  }

  return {
    executive_summary: parts.join(" "),
    cross_cutting_themes: themes,
    strategic_recommendations: strategic,
  };
}

// ---------------------------------------------------------------------------
// Markdown Report Generation
// ---------------------------------------------------------------------------

function healthEmoji(status: string): string {
  switch (status) {
    case "critical": return "CRITICAL";
    case "at_risk": return "AT RISK";
    case "needs_attention": return "NEEDS ATTENTION";
    case "healthy": return "HEALTHY";
    default: return status.toUpperCase();
  }
}

function severityLabel(sev: string): string {
  switch (sev) {
    case "critical": return "Critical";
    case "high": return "High";
    case "medium": return "Medium";
    case "low": return "Low";
    default: return sev;
  }
}

export function generateQualitySynthesisMarkdown(opts: {
  metrics: QualitySynthesisOutput;
  actions: PrioritizedAction[];
  narrative: NarrativeSections;
}): string {
  const { metrics, actions, narrative } = opts;
  const qo = metrics.quality_overview;
  const stats = metrics.summary_stats;
  const meta = metrics.metadata;
  const lines: string[] = [];

  lines.push(`# Quality Synthesis Report v${meta.report_version}`);
  lines.push("");

  // Executive Summary
  lines.push("## Executive Summary");
  lines.push("");
  lines.push(narrative.executive_summary);
  lines.push("");

  // Data Sources
  lines.push("**Data Sources Analyzed:**");
  lines.push("");
  lines.push("| Source | Status | Key Metric |");
  lines.push("|--------|--------|------------|");

  const covStatus = qo.coverage_score !== null ? "Available" : "Missing";
  const covMetric = qo.coverage_score !== null ? `Overall Score: ${qo.coverage_score.toFixed(2)}` : "N/A";
  lines.push(`| Coverage Analysis | ${covStatus} | ${covMetric} |`);

  const congStatus = qo.congruency_score !== null ? "Available" : "Missing";
  const congMetric = qo.congruency_score !== null ? `Congruency: ${qo.congruency_score}%` : "N/A";
  lines.push(`| Congruency Analysis | ${congStatus} | ${congMetric} |`);

  const impStatus = qo.impact_blast_radius !== null ? "Available" : "Missing";
  const impMetric = qo.impact_blast_radius !== null ? `Blast Radius: ${qo.impact_blast_radius.toFixed(1)}%` : "N/A";
  lines.push(`| Impact Analysis | ${impStatus} | ${impMetric} |`);
  lines.push("");

  lines.push(`**Composite Health: ${healthEmoji(qo.composite_health)}**`);
  lines.push("");

  // What You Need To Do
  lines.push("## What You Need To Do");
  lines.push("");

  if (actions.length === 0) {
    lines.push("No prioritized actions identified — quality posture is healthy.");
    lines.push("");
  } else {
    for (const a of actions) {
      lines.push(`### ${a.rank}. ${a.action}`);
      lines.push(`**Severity**: ${severityLabel(a.severity)} | **Effort**: ${a.effort} | **Resolves**: ${a.affected_items.length} finding(s)`);
      lines.push("");
      lines.push(a.rationale);
      lines.push("");
      lines.push(`**Expected Outcome**: ${a.expected_score_impact}`);
      lines.push("");
      lines.push(`**Findings addressed**: ${a.affected_items.join(", ")}`);
      lines.push("");
    }
  }

  // Quality Overview
  lines.push("## Quality Overview");
  lines.push("");
  lines.push("| Metric | Value | Status |");
  lines.push("|--------|-------|--------|");

  const covGrade = qo.coverage_score !== null
    ? (qo.coverage_score >= 0.85 ? "Good" : qo.coverage_score >= 0.7 ? "Fair" : "Poor")
    : "N/A";
  lines.push(`| Coverage Quality Score | ${qo.coverage_score !== null ? `${qo.coverage_score.toFixed(2)} / 1.00` : "N/A"} | ${covGrade} |`);

  const congGrade = qo.congruency_score !== null
    ? (qo.congruency_score >= 75 ? "Good" : qo.congruency_score >= 55 ? "Fair" : "Poor")
    : "N/A";
  lines.push(`| Congruency Score | ${qo.congruency_score !== null ? `${qo.congruency_score}%` : "N/A"} | ${congGrade} |`);

  const impGrade = qo.impact_blast_radius !== null
    ? (qo.impact_blast_radius <= 20 ? "Low" : qo.impact_blast_radius <= 40 ? "Medium" : "High")
    : "N/A";
  lines.push(`| Impact Blast Radius | ${qo.impact_blast_radius !== null ? `${qo.impact_blast_radius.toFixed(1)}%` : "N/A"} | ${impGrade} |`);
  lines.push("");

  // Cross-Cutting Concerns
  lines.push("## Cross-Cutting Concerns");
  lines.push("");

  if (metrics.cross_cutting_nodes.length === 0) {
    lines.push("No cross-cutting nodes identified.");
    lines.push("");
  } else {
    for (const node of metrics.cross_cutting_nodes) {
      const nodeName = node.node_name || node.node_id;
      lines.push(`### ${nodeName} (flagged by ${node.dimensions_affected} sources)`);
      lines.push("");
      if (node.node_type) {
        lines.push(`**Type**: ${node.node_type}`);
        lines.push("");
      }
      const bySource = new Map<string, string[]>();
      for (const issue of node.issues) {
        if (!bySource.has(issue.source)) bySource.set(issue.source, []);
        bySource.get(issue.source)!.push(`${issue.summary} (${issue.severity})`);
      }
      for (const [source, summaries] of bySource) {
        lines.push(`- **${source}**: ${summaries.join("; ")}`);
      }
      lines.push("");
    }
  }

  // Cross-Cutting Themes
  lines.push("## Cross-Cutting Themes");
  lines.push("");
  for (const theme of narrative.cross_cutting_themes) {
    lines.push(`- ${theme}`);
  }
  lines.push("");

  // Category Health Dashboard
  lines.push("## Category Health Dashboard");
  lines.push("");
  lines.push("| Category | Coverage Score | Congruency Issues | Impact Risk | Items | Health |");
  lines.push("|----------|---------------|-------------------|-------------|-------|--------|");

  const categories = ["scope", "architecture", "technical", "sequencing", "interface", "data", "logic", "testing"];
  for (const cat of categories) {
    const h = metrics.category_health[cat] as CategoryHealth | undefined;
    if (!h) continue;
    const covStr = h.coverage_score !== null ? h.coverage_score.toFixed(2) : "—";
    const riskStr = h.impact_risk ?? "—";
    lines.push(`| ${cat} | ${covStr} | ${h.congruency_issues} | ${riskStr} | ${h.total_items} | ${healthEmoji(h.health_status)} |`);
  }
  lines.push("");

  // Summary Stats
  lines.push("## Finding Distribution");
  lines.push("");
  lines.push("| Severity | Count |");
  lines.push("|----------|-------|");
  for (const sev of ["critical", "high", "medium", "low"]) {
    lines.push(`| ${severityLabel(sev)} | ${stats.by_severity[sev] ?? 0} |`);
  }
  lines.push("");
  lines.push("| Source | Count |");
  lines.push("|--------|-------|");
  for (const src of ["coverage", "congruency", "impact"]) {
    lines.push(`| ${src} | ${stats.by_source[src] ?? 0} |`);
  }
  lines.push("");

  // Strategic Recommendations
  lines.push("## Strategic Recommendations");
  lines.push("");
  for (let i = 0; i < narrative.strategic_recommendations.length; i++) {
    lines.push(`${i + 1}. ${narrative.strategic_recommendations[i]}`);
  }
  lines.push("");

  // Data Availability
  lines.push("## Data Availability");
  lines.push("");
  const available = [
    meta.sources_available.coverage ? "Coverage Analysis" : null,
    meta.sources_available.congruency.length > 0 ? "Congruency Analysis" : null,
    meta.sources_available.impact ? "Impact Analysis" : null,
  ].filter(Boolean);
  lines.push(`**Sources included**: ${available.join(", ") || "None"}`);
  lines.push(`**Sources missing**: ${meta.sources_missing.length > 0 ? meta.sources_missing.join(", ") : "None"}`);
  lines.push("");

  if (meta.sources_missing.length > 0) {
    lines.push(
      `Note: Without ${meta.sources_missing.join(" and ")} analysis, the synthesis is limited to ${available.length} dimension(s). Run the missing analyses for a more complete quality picture.`,
    );
    lines.push("");
  }

  lines.push("---");
  lines.push("*Generated by quality-synthesis plugin v1.0.0*");
  lines.push("");

  return lines.join("\n");
}

// ---------------------------------------------------------------------------
// Main Export
// ---------------------------------------------------------------------------

export interface GenerateQualitySynthesisReportResult {
  actions: PrioritizedAction[];
  narrative: NarrativeSections;
  markdown: string;
}

export function generateQualitySynthesisReport(
  metrics: QualitySynthesisOutput,
): GenerateQualitySynthesisReportResult {
  const clusters = computeLeverageClusters(metrics);
  const actions = generatePrioritizedActions(clusters, metrics.artifact_gap_summary ?? []);
  const narrative = generateNarrativeSections(metrics, actions);
  const markdown = generateQualitySynthesisMarkdown({ metrics, actions, narrative });

  return { actions, narrative, markdown };
}

