  1→/**
  2→ * Quality Synthesis Workflow Definition.
  3→ *
  4→ * 2-phase pipeline:
  5→ *   Phase 1: Normalize Data — Cross-reference coverage/congruency/impact findings (mechanical)
  6→ *   Phase 2: Generate Report — Mechanical leverage clusters + markdown generation, then slim LLM
  7→ *            enhancement of narrative sections (executive summary, themes, recommendations).
  8→ *            The LLM no longer reads the full AppGraph or PRD — only the pre-generated report
  9→ *            and enriched metrics JSON.
 10→ *
 11→ * Requires at least one prior analysis run (impact, coverage, or congruency).
 12→ */
 13→
 14→import * as fs from "node:fs/promises";
 15→import * as path from "node:path";
 16→import type {
 17→  AgentCall,
 18→  PhaseDefinition,
 19→  Step,
 20→  StepContext,
 21→  StepResult,
 22→  WorkflowContext,
 23→  WorkflowDefinition,
 24→} from "../../types/index.js";
 25→import { trackAgentResult } from "../workflow-engine/tracking.js";
 26→import {
 27→  MANIFEST_PATH,
 28→  VERSIONS_DIR,
 29→  BASELINE_PATH,
 30→} from "../mechanical/initialize-workflow.js";
 31→import { normalizeQualitySynthesis } from "../mechanical/normalize-quality-synthesis.js";
 32→import type { QualitySynthesisOutput } from "../mechanical/normalize-quality-synthesis.js";
 33→import { generateQualitySynthesisReport } from "../mechanical/generate-quality-synthesis-report.js";
 34→
 35→// ---------------------------------------------------------------------------
 36→// Helpers
 37→// ---------------------------------------------------------------------------
 38→
 39→function mechanicalStep(
 40→  id: string,
 41→  name: string,
 42→  fn: (ctx: StepContext) => Promise<Record<string, unknown> | void>,
 43→): Step {
 44→  return {
 45→    id,
 46→    name,
 47→    mode: "sequential",
 48→    async execute(ctx: StepContext): Promise<StepResult> {
 49→      try {
 50→        const data = await fn(ctx);
 51→        return { status: "success", data: (data as Record<string, unknown>) ?? {} };
 52→      } catch (err) {
 53→        return { status: "error", error: String(err) };
 54→      }
 55→    },
 56→  };
 57→}
 58→
 59→interface ManifestEntry {
 60→  version: string;
 61→  path: string;
 62→  [key: string]: unknown;
 63→}
 64→
 65→interface Manifest {
 66→  versions: ManifestEntry[];
 67→}
 68→
 69→async function findLatestAppGraph(
 70→  workspaceRoot: string,
 71→): Promise<{ version: string; appgraphPath: string }> {
 72→  const manifestPath = path.join(workspaceRoot, MANIFEST_PATH);
 73→
 74→  try {
 75→    const raw = await fs.readFile(manifestPath, "utf-8");
 76→    const manifest: Manifest = JSON.parse(raw);
 77→    const versions = manifest.versions ?? [];
 78→    if (versions.length === 0) {
 79→      throw new Error("Manifest has no versions");
 80→    }
 81→    const latest = versions[versions.length - 1];
 82→    return {
 83→      version: latest.version,
 84→      appgraphPath: path.join(workspaceRoot, VERSIONS_DIR, latest.path),
 85→    };
 86→  } catch (err) {
 87→    const baselinePath = path.join(workspaceRoot, BASELINE_PATH);
 88→    try {
 89→      await fs.access(baselinePath);
 90→      return { version: "baseline", appgraphPath: baselinePath };
 91→    } catch {
 92→      throw new Error(
 93→        `No manifest or baseline AppGraph found. Run Artifact Integration first. (${String(err)})`,
 94→      );
 95→    }
 96→  }
 97→}
 98→
 99→async function getNextSynthesisVersion(analysisDir: string): Promise<number> {
100→  try {
101→    const files = await fs.readdir(analysisDir);
102→    let maxVersion = 0;
103→    for (const f of files) {
104→      const match = f.match(/^quality-synthesis-data-v(\d+)\.json$/);
105→      if (match) {
106→        const v = parseInt(match[1], 10);
107→        if (v > maxVersion) maxVersion = v;
108→      }
109→    }
110→    return maxVersion + 1;
111→  } catch {
112→    return 1;
113→  }
114→}
115→
116→// ---------------------------------------------------------------------------
117→// Phase 1: Normalize Data (mechanical)
118→// ---------------------------------------------------------------------------
119→
120→function createNormalizePhase(): PhaseDefinition {
121→  return {
122→    id: "normalize-data",
123→    name: "Normalize Data",
124→    createSteps(_ctx: WorkflowContext): Step[] {
125→      return [
126→        mechanicalStep("normalize-data", "Normalize and cross-reference analysis data", async (sctx) => {
127→          const { version: appgraphVersion, appgraphPath } =
128→            await findLatestAppGraph(sctx.workspaceRoot);
129→
130→          sctx.emitter.emit({
131→            type: "log",
132→            level: "info",
133→            message: `Normalizing analysis data for ${appgraphVersion}`,
134→          });
135→
136→          // Determine version directory and analysis dir
137→          let versionDir: string;
138→          let analysisDir: string;
139→          if (appgraphVersion === "baseline") {
140→            versionDir = path.join(sctx.workspaceRoot, ".alucify");
141→            analysisDir = path.join(versionDir, "analysis");
142→          } else {
143→            versionDir = path.join(sctx.workspaceRoot, VERSIONS_DIR, appgraphVersion);
144→            analysisDir = path.join(versionDir, "analysis");
145→          }
146→          await fs.mkdir(analysisDir, { recursive: true });
147→
148→          const synthesisVersion = await getNextSynthesisVersion(analysisDir);
149→          const dataPath = path.join(
150→            analysisDir,
151→            `quality-synthesis-data-v${synthesisVersion}.json`,
152→          );
153→          const reportPath = path.join(
154→            analysisDir,
155→            `quality-synthesis-report-v${synthesisVersion}.md`,
156→          );
157→
158→          sctx.state.workingDirectory = analysisDir;
159→
160→          const stats = await normalizeQualitySynthesis(versionDir, synthesisVersion, dataPath, appgraphPath);
161→
162→          sctx.emitter.emit({
163→            type: "log",
164→            level: "info",
165→            message: `Normalized: ${stats.totalItems} items, ${stats.crossCuttingNodes} cross-cutting nodes, health: ${stats.compositeHealth}`,
166→          });
167→
168→          return {
169→            appgraphVersion,
170→            appgraphPath,
171→            synthesisVersion,
172→            dataPath,
