/**
 * Normalize and cross-reference analysis data from coverage, congruency, and impact reports.
 *
 * TypeScript port of normalize_analysis_data.py from alucify-agents-internal.
 * Loads the latest analysis files from a version directory, normalizes severity levels,
 * extracts unified items, builds a node-issue registry for cross-referencing, and
 * identifies cross-cutting nodes. Does NOT rank or prioritize — that's the LLM agent's job.
 */

import * as fs from "node:fs/promises";
import * as path from "node:path";
import type { AppGraph, AppGraphNode } from "./appgraph-types.js";

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

export interface ArtifactGuidance {
  recommended_action: string;
  artifact_type?: string;
  target_artifact?: string;
  specific_updates?: Array<Record<string, unknown>>;
}

export interface UnifiedItem {
  id: string;
  source: "coverage" | "congruency" | "impact";
  source_id: string;
  severity: string;
  category: string;
  action: string;
  impact: string;
  effort: string;
  affected_node_ids: string[];
  cross_dimension_count: number;
  related_items: string[];
  artifact_guidance?: ArtifactGuidance | null;
  _temp_id?: string;
}

interface RegistryEntry {
  source: string;
  item_id: string;
  severity: string;
  summary: string;
}

export interface CrossCuttingNode {
  node_id: string;
  node_name: string;
  node_type: string;
  dimensions_affected: number;
  issues: RegistryEntry[];
}

export interface CategoryHealth {
  coverage_score: number | null;
  congruency_issues: number;
  impact_risk: string | null;
  total_items: number;
  critical_items: number;
  health_status: string;
}

export interface ArtifactGapCluster {
  artifact_type: string;
  target_artifact: string | null;
  finding_count: number;
  node_ids: string[];
  severity_counts: Record<string, number>;
  sources: string[];
  example_actions: string[];
  source_item_ids: string[];
}

export interface PrioritizedAction {
  rank: number;
  action_type?: "update_artifact" | "create_artifact";
  action: string;
  rationale: string;
  severity: string;
  effort: string;
  target_artifact?: string | null;
  suggested_artifact_type?: string | null;
  affected_items: string[];
  expected_score_impact: string;
}

export interface NarrativeSections {
  executive_summary: string;
  cross_cutting_themes: string[];
  strategic_recommendations: string[];
}

export interface QualitySynthesisOutput {
  metadata: {
    synthesis_date: string;
    appgraph_version: string;
    report_version: number;
    sources_available: { coverage: string | null; congruency: string[]; impact: string | null };
    sources_missing: string[];
  };
  quality_overview: {
    coverage_score: number | null;
    congruency_score: number | null;
    impact_blast_radius: number | null;
    composite_health: string;
  };
  cross_cutting_nodes: CrossCuttingNode[];
  unified_items: Record<string, unknown>[];
  category_health: Record<string, CategoryHealth>;
  summary_stats: {
    total_items: number;
    by_severity: Record<string, number>;
    by_source: Record<string, number>;
    cross_cutting_node_count: number;
  };
  artifact_gap_summary: ArtifactGapCluster[];
  prioritized_actions: PrioritizedAction[];
  narrative_sections: NarrativeSections | Record<string, unknown>;
}

interface CoverageExtra {
  overall_score: number | null;
  dimension_scores: Record<string, unknown>;
  low_grounding_nodes: Array<{ id?: string; score?: number; authority?: string }>;
  unified_category_scores: Record<string, { cross_score?: number }>;
}

interface CongruencyExtra {
  congruency_score: number | null;
}

interface ImpactExtra {
  blast_radius_percentage: number | null;
  risk_levels: Record<string, string>;
}

interface DiscoveredSources {
  coverage: string | null;
  congruency: string[];
  appgraph_congruency: string | null;
  impact: string | null;
}

// ---------------------------------------------------------------------------
// Severity normalization maps
// ---------------------------------------------------------------------------

const CONGRUENCY_ISSUE_SEVERITY_MAP: Record<string, string> = {
  Critical: "critical",
  Major: "high",
  Minor: "medium",
};

const IMPACT_SEVERITY_MAP: Record<string, string> = {
  info: "low",
  low: "low",
  medium: "medium",
  high: "high",
  critical: "critical",
};

const IMPACT_RISK_LEVEL_MAP: Record<string, string> = {
  Critical: "critical",
  High: "high",
  Medium: "medium",
  Low: "low",
};

const EFFORT_NORMALIZE: Record<string, string> = {
  Low: "low",
  Medium: "medium",
  High: "high",
  low: "low",
  medium: "medium",
  high: "high",
};

const CONGRUENCY_CATEGORY_MAP: Record<string, string> = {
  // Terminology consistency
