  acceptance_criteria: "testing",
  specification_gap: "other",
  implementation_gap: "technical",
  specification_drift: "other",
  specification_inconsistency: "other",
  orphaned_node: "other",
  missing_cross_subgraph_edge: "other",
  unimplemented_requirement: "scope",
  unvalidated_implementation: "testing",
};

const VALID_CATEGORIES = new Set([
  "scope", "architecture", "technical", "sequencing",
  "interface", "data", "logic", "testing", "other",
]);

// ---------------------------------------------------------------------------
// File discovery
// ---------------------------------------------------------------------------

async function findLatestByMtime(dir: string, pattern: RegExp): Promise<string | null> {
  try {
    const files = await fs.readdir(dir);
    const matches = files.filter((f) => pattern.test(f));
    if (matches.length === 0) return null;

    const withStats = await Promise.all(
      matches.map(async (f) => {
        const full = path.join(dir, f);
        const stat = await fs.stat(full);
        return { path: full, mtime: stat.mtimeMs };
      }),
    );
    withStats.sort((a, b) => b.mtime - a.mtime);
    return withStats[0].path;
  } catch {
    return null;
  }
}

async function findAllByMtime(dir: string, pattern: RegExp): Promise<string[]> {
  try {
    const files = await fs.readdir(dir);
    const matches = files.filter((f) => pattern.test(f));
    if (matches.length === 0) return [];

    const withStats = await Promise.all(
      matches.map(async (f) => {
        const full = path.join(dir, f);
        const stat = await fs.stat(full);
        return { path: full, mtime: stat.mtimeMs };
      }),
    );
    withStats.sort((a, b) => a.mtime - b.mtime);
    return withStats.map((w) => w.path);
  } catch {
    return [];
  }
}

async function discoverSources(analysisDir: string): Promise<DiscoveredSources> {
  const result: DiscoveredSources = {
    coverage: null,
    congruency: [],
    appgraph_congruency: null,
    impact: null,
  };

  try {
    await fs.access(analysisDir);
  } catch {
    return result;
  }

  result.coverage = await findLatestByMtime(analysisDir, /^coverage-analysis-data-v\d+\.json$/);
  result.impact = await findLatestByMtime(analysisDir, /^impact-analysis-data-v\d+\.json$/);
  result.appgraph_congruency = await findLatestByMtime(analysisDir, /^appgraph-congruency-v\d+\.json$/);

  // All per-artifact congruency reports, excluding cross-artifact reports
  const allCongruency = await findAllByMtime(analysisDir, /^congruency-analysis-.*-v\d+\.json$/);
  result.congruency = allCongruency.filter((f) => !path.basename(f).includes("congruency-cross-"));

  return result;
}

async function loadJson(filePath: string): Promise<Record<string, unknown>> {
  const raw = await fs.readFile(filePath, "utf-8");
  return JSON.parse(raw);
}

