// Item extraction helpers
// ---------------------------------------------------------------------------

function buildCoverageArtifactLookups(
  data: Record<string, unknown>,
): { decisionLookup: Map<string, ArtifactGuidance>; nodeLookup: Map<string, ArtifactGuidance> } {
  const decisionLookup = new Map<string, ArtifactGuidance>();
  const nodeLookup = new Map<string, ArtifactGuidance>();

  const implAnalysis = (data.implementability_analysis as Record<string, unknown>) ?? {};
  const decisions = Array.isArray(implAnalysis.decisions) ? (implAnalysis.decisions as Array<Record<string, unknown>>) : [];

  for (const decision of decisions) {
    const hti = decision.how_to_improve as Record<string, unknown> | undefined;
    if (!hti) continue;

    const guidance: ArtifactGuidance = {
      recommended_action: (hti.recommended_action as string) ?? "",
    };

    const options = Array.isArray(hti.options) ? (hti.options as Array<Record<string, unknown>>) : [];
    if (options.length > 0) {
      guidance.artifact_type = (options[0].artifact_type as string) ?? "";
    }

    const decisionId = (decision.id as string) ?? "";
    if (decisionId) {
      decisionLookup.set(decisionId, guidance);
    }

    for (const nodeId of Array.isArray(decision.appgraph_refs) ? (decision.appgraph_refs as string[]) : []) {
      if (nodeId && !nodeLookup.has(nodeId)) {
        nodeLookup.set(nodeId, guidance);
      }
    }
  }

  return { decisionLookup, nodeLookup };
}

function extractArtifactGuidanceFromIssue(
  issue: Record<string, unknown>,
): ArtifactGuidance | null {
  const solutions = Array.isArray(issue.solutions) ? (issue.solutions as Array<Record<string, unknown>>) : [];
  if (solutions.length === 0) return null;

  // Find recommended solution, or fall back to first with artifact_to_fix
  let chosen: Record<string, unknown> | null = null;
  for (const sol of solutions) {
    if (sol.recommended) {
      chosen = sol;
      break;
    }
  }
  if (!chosen) {
    for (const sol of solutions) {
      if (sol.artifact_to_fix) {
        chosen = sol;
        break;
      }
    }
  }
  if (!chosen) return null;

  const atf = (chosen.artifact_to_fix as Record<string, unknown>) ?? null;
  if (!atf) return null;

  const guidance: ArtifactGuidance = {
    recommended_action: (chosen.description as string) ?? "",
  };

  const targetArtifact = atf.artifact_path as string | undefined;
  if (targetArtifact) guidance.target_artifact = targetArtifact;

  const artifactName = (atf.artifact_name as string) ?? "";
  if (artifactName) guidance.artifact_type = artifactName;

  const updates = Array.isArray(chosen.artifact_updates) ? (chosen.artifact_updates as Array<Record<string, unknown>>) : [];
  if (updates.length > 0) guidance.specific_updates = updates;

  return guidance;
}

