// Item extraction
// ---------------------------------------------------------------------------

function extractCoverageItems(
  data: Record<string, unknown>,
): { items: Partial<UnifiedItem>[]; extra: CoverageExtra } {
  const items: Partial<UnifiedItem>[] = [];
  const { decisionLookup, nodeLookup } = buildCoverageArtifactLookups(data);

  // Extract from gaps[]
  const gaps = Array.isArray(data.gaps) ? (data.gaps as Array<Record<string, unknown>>) : [];
  for (const gap of gaps) {
    const gapIdVal = (gap.id as string) ?? "";

    // Look up artifact guidance: try as decision ID first, then as node ID
    const artifactGuidance = decisionLookup.get(gapIdVal) ?? nodeLookup.get(gapIdVal) ?? null;

    items.push({
      source: "coverage",
      source_id: (gap.gap_id as string) ?? "",
      severity: (gap.severity as string) ?? "medium",
      category: (gap.category as string) ?? "other",
      action: (gap.recommendation as string) ?? "",
      impact: (gap.evidence as string) ?? "",
      effort: "medium",
      affected_node_ids: gapIdVal ? [gapIdVal] : [],
      artifact_guidance: artifactGuidance,
    });
  }

  // Extract from recommendations — handles both list format and dict-by-severity format
  const rawRecs = data.recommendations;
  if (Array.isArray(rawRecs)) {
    // Flat list format: each rec has "priority" as severity string and "id"
    for (const rec of rawRecs as Array<Record<string, unknown>>) {
      let severity = ((rec.priority as string) ?? "medium").toLowerCase();
      if (!["critical", "high", "medium", "low"].includes(severity)) {
        severity = "medium";
      }
      items.push({
        source: "coverage",
        source_id: (rec.id as string) ?? `REC-${severity}`,
        severity,
        category: "other",
        action: (rec.description as string) ?? (rec.action as string) ?? "",
        impact: (rec.expected_impact as string) ?? (rec.impact as string) ?? "",
        effort: EFFORT_NORMALIZE[(rec.effort as string) ?? "Medium"] ?? "medium",
        affected_node_ids: [],
        artifact_guidance: null,
      });
    }
  } else if (rawRecs && typeof rawRecs === "object") {
    // Dict-by-severity format: keyed by severity level
    const recsDict = rawRecs as Record<string, Array<Record<string, unknown>>>;
    for (const severityKey of ["critical", "high", "medium", "low"]) {
      for (const rec of recsDict[severityKey] ?? []) {
        items.push({
          source: "coverage",
          source_id: `REC-${severityKey}-${rec.priority ?? 0}`,
          severity: severityKey,
          category: "other",
          action: (rec.action as string) ?? "",
          impact: (rec.impact as string) ?? "",
          effort: EFFORT_NORMALIZE[(rec.effort as string) ?? "Medium"] ?? "medium",
          affected_node_ids: [],
          artifact_guidance: null,
        });
      }
    }
  }

  const scores = (data.scores as Record<string, unknown>) ?? {};
  const grounding = (data.grounding_analysis as Record<string, unknown>) ?? {};
  const lowGrounding = (grounding.low_grounding_nodes as CoverageExtra["low_grounding_nodes"]) ?? [];
  const unifiedCategoryScores = (data.unified_category_scores as CoverageExtra["unified_category_scores"]) ?? {};

  const extra: CoverageExtra = {
    overall_score: (scores.overall as number) ?? null,
    dimension_scores: (scores.dimensions as Record<string, unknown>) ?? {},
    low_grounding_nodes: lowGrounding,
    unified_category_scores: unifiedCategoryScores,
  };

  return { items, extra };
}

async function extractCongruencyItemsAsync(
  files: string[],
  appgraphCongruencyPath: string | null,
): Promise<{ items: Partial<UnifiedItem>[]; extra: CongruencyExtra }> {
  const items: Partial<UnifiedItem>[] = [];
  const seenRecIds = new Set<string>();
  // Build issue_id → artifact_guidance lookup for enriching recommendations
  const issueGuidanceMap = new Map<string, ArtifactGuidance>();

  // First pass: build guidance map from all issues
  for (const filepath of files) {
    const data = await loadJson(filepath);
    for (const issue of Array.isArray(data.issues) ? (data.issues as Array<Record<string, unknown>>) : []) {
      const guidance = extractArtifactGuidanceFromIssue(issue);
      if (guidance) {
        issueGuidanceMap.set((issue.id as string) ?? "", guidance);
      }
    }
  }

  for (const filepath of files) {
    const data = await loadJson(filepath);

    // Extract recommendations
    const recs = Array.isArray(data.recommendations) ? (data.recommendations as Array<Record<string, unknown>>) : [];
    for (const rec of recs) {
      const recId = (rec.id as string) ?? "";
      if (seenRecIds.has(recId)) continue;
      seenRecIds.add(recId);

      // Collect affected node IDs from addressed issues
      const affectedNodes = new Set<string>();
      const addressedIds = new Set(Array.isArray(rec.addresses) ? (rec.addresses as string[]) : []);
      let recGuidance: ArtifactGuidance | null = null;
      const issues = Array.isArray(data.issues) ? (data.issues as Array<Record<string, unknown>>) : [];
      for (const issue of issues) {
        if (addressedIds.has((issue.id as string) ?? "")) {
          for (const nid of Array.isArray(issue.affected_node_ids) ? (issue.affected_node_ids as string[]) : []) {
            affectedNodes.add(nid);
          }
          // Use first addressed issue's guidance for the recommendation
          if (!recGuidance) {
            recGuidance = issueGuidanceMap.get((issue.id as string) ?? "") ?? null;
          }
        }
      }

      items.push({
        source: "congruency",
        source_id: recId,
        severity: (rec.severity as string) ?? "medium",
        category: "other", // enriched below
        action: (rec.action as string) ?? "",
        impact: (rec.impact as string) ?? "",
        effort: (rec.effort as string) ?? "medium",
        affected_node_ids: [...affectedNodes],
        artifact_guidance: recGuidance,
      });
    }

    // Extract issues not covered by any recommendation
    const recs2 = Array.isArray(data.recommendations) ? (data.recommendations as Array<Record<string, unknown>>) : [];
    const recAddressed = new Set<string>();
    for (const rec of recs2) {
      for (const addr of Array.isArray(rec.addresses) ? (rec.addresses as string[]) : []) {
        recAddressed.add(addr);
      }
    }

    const issues = Array.isArray(data.issues) ? (data.issues as Array<Record<string, unknown>>) : [];
    for (const issue of issues) {
      const issueId = (issue.id as string) ?? "";
      if (recAddressed.has(issueId) || seenRecIds.has(issueId)) continue;
      seenRecIds.add(issueId);

      const severity = CONGRUENCY_ISSUE_SEVERITY_MAP[(issue.severity as string) ?? "Minor"] ?? "medium";
      const rawCategory = (issue.category as string) ?? "";
      const category = CONGRUENCY_CATEGORY_MAP[rawCategory] ?? "other";

      // Build action from recommended solution, or first solution, or title
      let action = (issue.title as string) ?? "";
      const solutions = Array.isArray(issue.solutions) ? (issue.solutions as Array<Record<string, unknown>>) : [];
      let foundRecommended = false;
      for (const sol of solutions) {
        if (sol.recommended) {
          action = (sol.description as string) ?? action;
          foundRecommended = true;
          break;
        }
      }
      if (!foundRecommended && solutions.length > 0) {
        action = (solutions[0].description as string) ?? action;
      }

      items.push({
        source: "congruency",
        source_id: issueId,
        severity,
        category,
        action,
        impact: (issue.impact as string) ?? "",
        effort: "medium",
        affected_node_ids: Array.isArray(issue.affected_node_ids) ? (issue.affected_node_ids as string[]) : [],
        artifact_guidance: issueGuidanceMap.get(issueId) ?? null,
      });
    }
  }

  // Enrich recommendation categories from addressed issues
  const issueCategoryMap = new Map<string, string>();
  for (const filepath of files) {
    const data = await loadJson(filepath);
    const issues = Array.isArray(data.issues) ? (data.issues as Array<Record<string, unknown>>) : [];
    for (const issue of issues) {
      const rawCat = (issue.category as string) ?? "";
      issueCategoryMap.set((issue.id as string) ?? "", CONGRUENCY_CATEGORY_MAP[rawCat] ?? "other");
    }
  }

  for (const item of items) {
    if (item.category === "other" && item.source === "congruency") {
      for (const filepath of files) {
        const data = await loadJson(filepath);
        const recs = Array.isArray(data.recommendations) ? (data.recommendations as Array<Record<string, unknown>>) : [];
        for (const rec of recs) {
          if ((rec.id as string) === item.source_id) {
            for (const addrId of Array.isArray(rec.addresses) ? (rec.addresses as string[]) : []) {
              const cat = issueCategoryMap.get(addrId);
              if (cat) {
                item.category = cat;
                break;
              }
            }
          }
          if (item.category !== "other") break;
        }
        if (item.category !== "other") break;
      }
    }
  }

  // Extra info
  const extra: CongruencyExtra = { congruency_score: null };
  if (appgraphCongruencyPath) {
    try {
      const agData = await loadJson(appgraphCongruencyPath);
      const congScore = (agData.congruency_score as Record<string, unknown>) ?? {};
      extra.congruency_score = (congScore.percentage as number) ?? null;

      // Build guidance map for appgraph-level issues
      for (const issue of Array.isArray(agData.issues) ? (agData.issues as Array<Record<string, unknown>>) : []) {
        const guidance = extractArtifactGuidanceFromIssue(issue);
        if (guidance) {
          issueGuidanceMap.set((issue.id as string) ?? "", guidance);
        }
      }

      // Also extract appgraph-level recommendations
      const agRecs = Array.isArray(agData.recommendations) ? (agData.recommendations as Array<Record<string, unknown>>) : [];
      for (const rec of agRecs) {
        const recId = (rec.id as string) ?? "";
        if (seenRecIds.has(recId)) continue;
        seenRecIds.add(recId);

        const affectedNodes = new Set<string>();
        const addressedIds = new Set(Array.isArray(rec.addresses) ? (rec.addresses as string[]) : []);
        let recGuidance: ArtifactGuidance | null = null;
        const agIssues = Array.isArray(agData.issues) ? (agData.issues as Array<Record<string, unknown>>) : [];
        for (const issue of agIssues) {
          if (addressedIds.has((issue.id as string) ?? "")) {
            for (const nid of Array.isArray(issue.affected_node_ids) ? (issue.affected_node_ids as string[]) : []) {
              affectedNodes.add(nid);
            }
            if (!recGuidance) {
              recGuidance = issueGuidanceMap.get((issue.id as string) ?? "") ?? null;
            }
          }
        }

        items.push({
          source: "congruency",
          source_id: recId,
          severity: (rec.severity as string) ?? "medium",
          category: "other",
          action: (rec.action as string) ?? "",
          impact: (rec.impact as string) ?? "",
          effort: (rec.effort as string) ?? "medium",
          affected_node_ids: [...affectedNodes],
          artifact_guidance: recGuidance,
        });
      }
    } catch {
      // Ignore if can't load appgraph congruency
    }
  }

  return { items, extra };
}

function extractImpactItems(
  data: Record<string, unknown>,
): { items: Partial<UnifiedItem>[]; extra: ImpactExtra } {
  const items: Partial<UnifiedItem>[] = [];

  const risks = Array.isArray(data.risks) ? (data.risks as Array<Record<string, unknown>>) : [];
  for (const risk of risks) {
    const severity = IMPACT_SEVERITY_MAP[(risk.severity as string) ?? "medium"] ?? "medium";
    items.push({
      source: "impact",
      source_id: `RISK-${(risk.category as string) ?? "unknown"}`,
      severity,
      category: "other",
      action: (risk.recommendation as string) ?? "",
      impact: (risk.description as string) ?? "",
      effort: "medium",
      affected_node_ids: [],
      artifact_guidance: null,
    });
  }

  const project = (data.project_level as Record<string, unknown>) ?? {};
  const blast = (project.blast_radius as Record<string, unknown>) ?? {};

  const riskLevels: Record<string, string> = {};
  for (const riskType of ["regression_testing_risk", "data_integrity_risk", "backward_compatibility_risk"]) {
    const riskData = (project[riskType] as Record<string, unknown>) ?? {};
    const rawLevel = (riskData.risk_level as string) ?? "N/A";
    if (rawLevel in IMPACT_RISK_LEVEL_MAP) {
      riskLevels[riskType] = IMPACT_RISK_LEVEL_MAP[rawLevel];
    }
  }

  const extra: ImpactExtra = {
    blast_radius_percentage: (blast.blast_radius_percentage as number) ?? null,
    risk_levels: riskLevels,
  };

  return { items, extra };
}

