function buildNodeIssueRegistry(
  items: Partial<UnifiedItem>[],
  coverageExtra: CoverageExtra | null,
): Map<string, RegistryEntry[]> {
  const registry = new Map<string, RegistryEntry[]>();

  for (const item of items) {
    for (const nodeId of Array.isArray(item.affected_node_ids) ? item.affected_node_ids : []) {
      if (!nodeId) continue;
      if (!registry.has(nodeId)) registry.set(nodeId, []);
      registry.get(nodeId)!.push({
        source: item.source!,
        item_id: item._temp_id ?? "",
        severity: item.severity!,
        summary: (item.action ?? "").slice(0, 100),
      });
    }
  }

  // Add low-grounding nodes from coverage
  if (coverageExtra) {
    for (const node of coverageExtra.low_grounding_nodes) {
      const nodeId = node.id ?? "";
      if (!nodeId) continue;
      if (!registry.has(nodeId)) registry.set(nodeId, []);
      registry.get(nodeId)!.push({
        source: "coverage",
        item_id: `low-grounding-${nodeId}`,
        severity: (node.score ?? 0) <= 0.05 ? "high" : "medium",
        summary: `Low grounding: authority=${node.authority ?? "unknown"}, score=${node.score ?? 0}`,
      });
    }
  }

  return registry;
}

function buildNodeIndex(nodes: AppGraphNode[]): Map<string, AppGraphNode> {
  const index = new Map<string, AppGraphNode>();
  for (const n of nodes) {
    index.set(n.id, n);
  }
  return index;
}

function identifyCrossCuttingNodes(
  registry: Map<string, RegistryEntry[]>,
  nodeIndex: Map<string, AppGraphNode>,
): CrossCuttingNode[] {
  const crossCutting: CrossCuttingNode[] = [];

  for (const [nodeId, entries] of registry) {
    const sources = new Set(entries.map((e) => e.source));
    if (sources.size >= 2) {
      const node = nodeIndex.get(nodeId);
      crossCutting.push({
        node_id: nodeId,
        node_name: node?.name ?? "",
        node_type: node?.type ?? "",
        dimensions_affected: sources.size,
        issues: entries,
      });
    }
  }

  crossCutting.sort((a, b) => {
    if (b.dimensions_affected !== a.dimensions_affected) {
      return b.dimensions_affected - a.dimensions_affected;
    }
    return b.issues.length - a.issues.length;
  });

  return crossCutting;
}

function annotateCrossDimensions(
  items: Partial<UnifiedItem>[],
  registry: Map<string, RegistryEntry[]>,
): void {
  for (const item of items) {
    const relatedSources = new Set<string>();
    const relatedItems = new Set<string>();

    for (const nodeId of Array.isArray(item.affected_node_ids) ? item.affected_node_ids : []) {
      for (const entry of registry.get(nodeId) ?? []) {
        if (entry.source !== item.source) {
          relatedSources.add(entry.source);
          relatedItems.add(entry.item_id);
        }
      }
    }

    item.cross_dimension_count = relatedSources.size + 1;
    item.related_items = [...relatedItems].sort();
  }
}

// ---------------------------------------------------------------------------
// Category health
// ---------------------------------------------------------------------------

const CATEGORIES = ["scope", "architecture", "technical", "sequencing",
  "interface", "data", "logic", "testing"] as const;

const CAT_RISK_MAP: Record<string, string> = {
  data: "data_integrity_risk",
  interface: "backward_compatibility_risk",
  testing: "regression_testing_risk",
};

function computeCategoryHealth(
  items: Partial<UnifiedItem>[],
  coverageExtra: CoverageExtra | null,
  impactExtra: ImpactExtra | null,
): Record<string, CategoryHealth> {
  const health: Record<string, CategoryHealth> = {};

  for (const cat of CATEGORIES) {
    const catItems = items.filter((i) => i.category === cat);
    const criticalCount = catItems.filter((i) => i.severity === "critical").length;
    const total = catItems.length;

    let covScore: number | null = null;
    if (coverageExtra) {
      const catScores = coverageExtra.unified_category_scores[cat];
      covScore = catScores?.cross_score ?? null;
    }

    let impactRisk: string | null = null;
    if (impactExtra && cat in CAT_RISK_MAP) {
      impactRisk = impactExtra.risk_levels[CAT_RISK_MAP[cat]] ?? null;
    }

    const congruencyIssues = catItems.filter((i) => i.source === "congruency").length;

    let status: string;
    if (criticalCount >= 2 || (covScore !== null && covScore < 0.4)) {
      status = "critical";
    } else if (criticalCount >= 1 || (covScore !== null && covScore < 0.6)) {
      status = "at_risk";
    } else if (total > 3 || (covScore !== null && covScore < 0.8)) {
      status = "needs_attention";
    } else {
      status = "healthy";
    }

    health[cat] = {
      coverage_score: covScore,
      congruency_issues: congruencyIssues,
      impact_risk: impactRisk,
      total_items: total,
      critical_items: criticalCount,
      health_status: status,
    };
  }

  return health;
}

// ---------------------------------------------------------------------------
// Artifact gap summary
// ---------------------------------------------------------------------------

function computeArtifactGapSummary(
  items: Record<string, unknown>[],
): ArtifactGapCluster[] {
  const byType = new Map<string, ArtifactGapCluster & { _sources: Set<string> }>();
  const byTarget = new Map<string, ArtifactGapCluster & { _sources: Set<string> }>();

  for (const item of items) {
    const guidance = item.artifact_guidance as
      | { artifact_type?: string; target_artifact?: string }
      | null
      | undefined;
    if (!guidance) continue;

    const artType = guidance.artifact_type ?? "";
    const target = guidance.target_artifact ?? null;
    const severity = (item.severity as string) ?? "medium";
    const itemId = (item.id as string) ?? "";
    const source = (item.source as string) ?? "";
    const nodeIds = (item.affected_node_ids as string[]) ?? [];
    const action = (item.action as string) ?? "";

    // Group by artifact_type (for "create new" recommendations)
    if (artType) {
      if (!byType.has(artType)) {
        byType.set(artType, {
          artifact_type: artType,
          target_artifact: null,
          finding_count: 0,
          node_ids: [],
          severity_counts: { critical: 0, high: 0, medium: 0, low: 0 },
          _sources: new Set(),
          sources: [],
          example_actions: [],
          source_item_ids: [],
        });
      }
      const bucket = byType.get(artType)!;
      bucket.finding_count++;
      bucket.node_ids.push(...nodeIds);
      if (severity in bucket.severity_counts) bucket.severity_counts[severity]++;
      bucket._sources.add(source);
      bucket.source_item_ids.push(itemId);
      if (bucket.example_actions.length < 3) bucket.example_actions.push(action.slice(0, 150));
    }

    // Group by target_artifact (for "update existing" recommendations)
    if (target) {
      if (!byTarget.has(target)) {
        byTarget.set(target, {
          artifact_type: artType || "unknown",
          target_artifact: target,
          finding_count: 0,
          node_ids: [],
          severity_counts: { critical: 0, high: 0, medium: 0, low: 0 },
          _sources: new Set(),
          sources: [],
          example_actions: [],
          source_item_ids: [],
        });
      }
      const bucket = byTarget.get(target)!;
      bucket.finding_count++;
      bucket.node_ids.push(...nodeIds);
      if (severity in bucket.severity_counts) bucket.severity_counts[severity]++;
      bucket._sources.add(source);
      bucket.source_item_ids.push(itemId);
      if (bucket.example_actions.length < 3) bucket.example_actions.push(action.slice(0, 150));
    }
  }

  // Merge: prefer by_target (more specific), supplement with by_type not covered
  const coveredItems = new Set<string>();
  const results: ArtifactGapCluster[] = [];

  const targetBuckets = [...byTarget.values()].sort((a, b) => b.finding_count - a.finding_count);
  for (const bucket of targetBuckets) {
    bucket.sources = [...bucket._sources].sort();
    bucket.node_ids = [...new Set(bucket.node_ids)].sort();
    for (const sid of bucket.source_item_ids) coveredItems.add(sid);
    // Strip internal field
    const { _sources, ...clean } = bucket;
    results.push(clean);
  }

  const typeBuckets = [...byType.values()].sort((a, b) => b.finding_count - a.finding_count);
  for (const bucket of typeBuckets) {
    const uncovered = bucket.source_item_ids.filter((sid) => !coveredItems.has(sid));
    if (uncovered.length < 2) continue;
    bucket.sources = [...bucket._sources].sort();
    bucket.node_ids = [...new Set(bucket.node_ids)].sort();
    bucket.finding_count = uncovered.length;
    bucket.source_item_ids = uncovered;
    const { _sources, ...clean } = bucket;
    results.push(clean);
  }

  results.sort((a, b) => b.finding_count - a.finding_count);
  return results;
}

// ---------------------------------------------------------------------------
// Composite health
// ---------------------------------------------------------------------------

function computeCompositeHealth(
  coverageExtra: CoverageExtra | null,
  congruencyExtra: CongruencyExtra | null,
  impactExtra: ImpactExtra | null,
  items: Partial<UnifiedItem>[],
): string {
  const criticalCount = items.filter((i) => i.severity === "critical").length;

  const covScore = coverageExtra?.overall_score ?? null;
  const blast = impactExtra?.blast_radius_percentage ?? null;
  const congScore = congruencyExtra?.congruency_score ?? null;

  // Critical — congruency uses logarithmic scale, so thresholds are lower:
  // old linear 50 ≈ new log ~40 (density ~1.5)
  if (criticalCount >= 5) return "critical";
  if (covScore !== null && covScore < 0.5) return "critical";
  if (blast !== null && blast > 60) return "critical";
  if (congScore !== null && congScore < 40) return "critical";

  // At risk — old linear 70 ≈ new log ~55 (density ~0.8)
  if (criticalCount >= 2) return "at_risk";
  if (covScore !== null && covScore < 0.7) return "at_risk";
  if (blast !== null && blast > 40) return "at_risk";
  if (congScore !== null && congScore < 55) return "at_risk";

  // Needs attention — old linear 85 ≈ new log ~75 (density ~0.3)
  if (criticalCount >= 1) return "needs_attention";
  if (covScore !== null && covScore < 0.85) return "needs_attention";
  if (blast !== null && blast > 20) return "needs_attention";
  if (congScore !== null && congScore < 75) return "needs_attention";

  return "healthy";
}

// ---------------------------------------------------------------------------
// Main export
// ---------------------------------------------------------------------------

export async function normalizeQualitySynthesis(
  versionDir: string,
  reportVersion: number,
  outputPath: string,
  appgraphPath?: string,
): Promise<{ totalItems: number; crossCuttingNodes: number; compositeHealth: string }> {
  const analysisDir = path.join(versionDir, "analysis");
  const appgraphVersion = path.basename(versionDir);

  // Load AppGraph for node name resolution (optional — graceful fallback to empty index)
  let nodeIndex = new Map<string, AppGraphNode>();
  if (appgraphPath) {
    try {
      const raw = await fs.readFile(appgraphPath, "utf-8");
      const appgraph: AppGraph = JSON.parse(raw);
      nodeIndex = buildNodeIndex(appgraph.nodes ?? []);
    } catch {
      // Fall back to empty index — cross-cutting nodes will have empty names
    }
  }

  // Step 1: Discover sources
  const sources = await discoverSources(analysisDir);

  let sourceCount = 0;
  const sourcesAvailable: { coverage: string | null; congruency: string[]; impact: string | null } = {
    coverage: null,
    congruency: [],
    impact: null,
  };
  const sourcesMissing: string[] = [];

  if (sources.coverage) {
    sourceCount++;
    sourcesAvailable.coverage = sources.coverage;
  } else {
    sourcesMissing.push("coverage");
  }

  if (sources.congruency.length > 0) {
    sourceCount++;
    sourcesAvailable.congruency = sources.congruency;
  } else {
    sourcesMissing.push("congruency");
  }

  if (sources.impact) {
    sourceCount++;
    sourcesAvailable.impact = sources.impact;
  } else {
    sourcesMissing.push("impact");
  }

  if (sourceCount === 0) {
    throw new Error("No analysis sources found. Run at least one analysis first.");
  }

  // Step 2: Extract items from each source
  const allItems: Partial<UnifiedItem>[] = [];
  let coverageExtra: CoverageExtra | null = null;
  let congruencyExtra: CongruencyExtra | null = null;
  let impactExtra: ImpactExtra | null = null;

  if (sources.coverage) {
    const covData = await loadJson(sources.coverage);
    const result = extractCoverageItems(covData);
    allItems.push(...result.items);
    coverageExtra = result.extra;
  }

  if (sources.congruency.length > 0 || sources.appgraph_congruency) {
    const result = await extractCongruencyItemsAsync(
      sources.congruency,
      sources.appgraph_congruency,
    );
    allItems.push(...result.items);
    congruencyExtra = result.extra;
  }

  // Fallback: read weighted score from congruency-stats.json if appgraph analyzer didn't provide one
  if (!congruencyExtra?.congruency_score) {
    try {
      const statsPath = path.join(versionDir, "working", "congruency-stats.json");
      const statsData = await loadJson(statsPath);
      const score = (statsData as Record<string, unknown>).congruency_score;
      if (typeof score === "number") {
        if (!congruencyExtra) congruencyExtra = { congruency_score: null };
        congruencyExtra.congruency_score = score;
      }
    } catch {
      // congruency-stats.json may not exist yet
    }
  }

  if (sources.impact) {
    const impData = await loadJson(sources.impact);
    const result = extractImpactItems(impData);
    allItems.push(...result.items);
    impactExtra = result.extra;
  }

  // Step 3: Assign temporary IDs
  for (let i = 0; i < allItems.length; i++) {
    allItems[i]._temp_id = `QS-${String(i + 1).padStart(3, "0")}`;
  }

  // Step 4: Build node-issue registry and cross-reference
  const registry = buildNodeIssueRegistry(allItems, coverageExtra);
  const crossCutting = identifyCrossCuttingNodes(registry, nodeIndex);
  annotateCrossDimensions(allItems, registry);

  // Step 5: Build unified items (clean up temp fields)
  const unifiedItems = allItems.map((item) => {
    const entry: Record<string, unknown> = {
      id: item._temp_id!,
      source: item.source!,
      source_id: item.source_id!,
      severity: item.severity!,
      category: VALID_CATEGORIES.has(item.category!) ? item.category! : "other",
      action: item.action ?? "",
      impact: item.impact ?? "",
      effort: item.effort ?? "medium",
      affected_node_ids: item.affected_node_ids ?? [],
      cross_dimension_count: item.cross_dimension_count ?? 1,
      related_items: item.related_items ?? [],
    };
    if (item.artifact_guidance) {
      entry.artifact_guidance = item.artifact_guidance;
    }
    return entry;
  });

  // Step 6: Compute category health
  const categoryHealth = computeCategoryHealth(allItems, coverageExtra, impactExtra);

  // Step 7: Compute summary stats
  const bySeverity: Record<string, number> = { critical: 0, high: 0, medium: 0, low: 0 };
  const bySource: Record<string, number> = { coverage: 0, congruency: 0, impact: 0 };
  for (const item of unifiedItems) {
    const sev = item.severity as string;
    const src = item.source as string;
    if (sev in bySeverity) bySeverity[sev]++;
    if (src in bySource) bySource[src]++;
  }

  // Step 8: Compute quality overview
  const compositeHealth = computeCompositeHealth(coverageExtra, congruencyExtra, impactExtra, allItems);

  // Step 9: Compute artifact gap summary
  const artifactGapSummary = computeArtifactGapSummary(unifiedItems);

  // Step 10: Assemble output
  const output: QualitySynthesisOutput = {
    metadata: {
      synthesis_date: new Date().toISOString().split("T")[0],
      appgraph_version: appgraphVersion,
      report_version: reportVersion,
      sources_available: sourcesAvailable,
      sources_missing: sourcesMissing,
    },
    quality_overview: {
      coverage_score: coverageExtra?.overall_score ?? null,
      congruency_score: congruencyExtra?.congruency_score ?? null,
      impact_blast_radius: impactExtra?.blast_radius_percentage ?? null,
      composite_health: compositeHealth,
    },
    cross_cutting_nodes: crossCutting,
    unified_items: unifiedItems,
    category_health: categoryHealth,
    summary_stats: {
      total_items: unifiedItems.length,
      by_severity: bySeverity,
      by_source: bySource,
      cross_cutting_node_count: crossCutting.length,
    },
    artifact_gap_summary: artifactGapSummary,
    prioritized_actions: [],
    narrative_sections: {} as Record<string, unknown>,
  };

  // Step 11: Write output
  await fs.mkdir(path.dirname(outputPath), { recursive: true });
  await fs.writeFile(outputPath, JSON.stringify(output, null, 2), "utf-8");

  return {
    totalItems: unifiedItems.length,
    crossCuttingNodes: crossCutting.length,
    compositeHealth,
  };
}

/**
 * Quality Synthesis Workflow Definition.
 *
 * 2-phase pipeline:
 *   Phase 1: Normalize Data — Cross-reference coverage/congruency/impact findings (mechanical)
 *   Phase 2: Generate Report — Mechanical leverage clusters + markdown generation, then slim LLM
 *            enhancement of narrative sections (executive summary, themes, recommendations).
 *            The LLM no longer reads the full AppGraph or PRD — only the pre-generated report
 *            and enriched metrics JSON.
 *
 * Requires at least one prior analysis run (impact, coverage, or congruency).
 */

import * as fs from "node:fs/promises";
import * as path from "node:path";
import type {
  AgentCall,
  PhaseDefinition,
  Step,
  StepContext,
  StepResult,
  WorkflowContext,
  WorkflowDefinition,
} from "../../types/index.js";
import { trackAgentResult } from "../workflow-engine/tracking.js";
import {
  MANIFEST_PATH,
  VERSIONS_DIR,
  BASELINE_PATH,
} from "../mechanical/initialize-workflow.js";
import { normalizeQualitySynthesis } from "../mechanical/normalize-quality-synthesis.js";
import type { QualitySynthesisOutput } from "../mechanical/normalize-quality-synthesis.js";
import { generateQualitySynthesisReport } from "../mechanical/generate-quality-synthesis-report.js";

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

function mechanicalStep(
  id: string,
  name: string,
  fn: (ctx: StepContext) => Promise<Record<string, unknown> | void>,
): Step {
  return {
    id,
    name,
    mode: "sequential",
    async execute(ctx: StepContext): Promise<StepResult> {
      try {
        const data = await fn(ctx);
        return { status: "success", data: (data as Record<string, unknown>) ?? {} };
      } catch (err) {
        return { status: "error", error: String(err) };
      }
    },
  };
}

interface ManifestEntry {
  version: string;
  path: string;
  [key: string]: unknown;
}

interface Manifest {
  versions: ManifestEntry[];
}

async function findLatestAppGraph(
  workspaceRoot: string,
): Promise<{ version: string; appgraphPath: string }> {
  const manifestPath = path.join(workspaceRoot, MANIFEST_PATH);

  try {
    const raw = await fs.readFile(manifestPath, "utf-8");
    const manifest: Manifest = JSON.parse(raw);
    const versions = manifest.versions ?? [];
    if (versions.length === 0) {
      throw new Error("Manifest has no versions");
    }
    const latest = versions[versions.length - 1];
    return {
      version: latest.version,
      appgraphPath: path.join(workspaceRoot, VERSIONS_DIR, latest.path),
    };
  } catch (err) {
    const baselinePath = path.join(workspaceRoot, BASELINE_PATH);
    try {
      await fs.access(baselinePath);
      return { version: "baseline", appgraphPath: baselinePath };
    } catch {
      throw new Error(
        `No manifest or baseline AppGraph found. Run Artifact Integration first. (${String(err)})`,
      );
    }
  }
}

async function getNextSynthesisVersion(analysisDir: string): Promise<number> {
  try {
    const files = await fs.readdir(analysisDir);
    let maxVersion = 0;
    for (const f of files) {
      const match = f.match(/^quality-synthesis-data-v(\d+)\.json$/);
      if (match) {
        const v = parseInt(match[1], 10);
        if (v > maxVersion) maxVersion = v;
      }
    }
    return maxVersion + 1;
  } catch {
    return 1;
  }
}

// ---------------------------------------------------------------------------
// Phase 1: Normalize Data (mechanical)
// ---------------------------------------------------------------------------

function createNormalizePhase(): PhaseDefinition {
  return {
    id: "normalize-data",
    name: "Normalize Data",
    createSteps(_ctx: WorkflowContext): Step[] {
      return [
        mechanicalStep("normalize-data", "Normalize and cross-reference analysis data", async (sctx) => {
          const { version: appgraphVersion, appgraphPath } =
            await findLatestAppGraph(sctx.workspaceRoot);

          sctx.emitter.emit({
            type: "log",
            level: "info",
            message: `Normalizing analysis data for ${appgraphVersion}`,
          });

          // Determine version directory and analysis dir
          let versionDir: string;
          let analysisDir: string;
          if (appgraphVersion === "baseline") {
            versionDir = path.join(sctx.workspaceRoot, ".alucify");
            analysisDir = path.join(versionDir, "analysis");
          } else {
            versionDir = path.join(sctx.workspaceRoot, VERSIONS_DIR, appgraphVersion);
            analysisDir = path.join(versionDir, "analysis");
          }
          await fs.mkdir(analysisDir, { recursive: true });

          const synthesisVersion = await getNextSynthesisVersion(analysisDir);
          const dataPath = path.join(
            analysisDir,
            `quality-synthesis-data-v${synthesisVersion}.json`,
          );
          const reportPath = path.join(
            analysisDir,
            `quality-synthesis-report-v${synthesisVersion}.md`,
          );

          sctx.state.workingDirectory = analysisDir;

          const stats = await normalizeQualitySynthesis(versionDir, synthesisVersion, dataPath, appgraphPath);

          sctx.emitter.emit({
            type: "log",
            level: "info",
            message: `Normalized: ${stats.totalItems} items, ${stats.crossCuttingNodes} cross-cutting nodes, health: ${stats.compositeHealth}`,
          });

          return {
            appgraphVersion,
            appgraphPath,
            synthesisVersion,
            dataPath,
            reportPath,
            versionDir,
          };
        }),
      ];
    },
  };
}

// ---------------------------------------------------------------------------
// Phase 2: Generate Report (mechanical + slim LLM enhancement)
// ---------------------------------------------------------------------------

function createSynthesizePhase(): PhaseDefinition {
  return {
    id: "synthesize-report",
    name: "Synthesize Report",
    createSteps(_ctx: WorkflowContext): Step[] {
      return [
        // Step 1: Mechanical — generate leverage clusters, prioritized actions, and markdown report
        mechanicalStep("generate-report-mechanical", "Generate report (mechanical)", async (sctx) => {
          const phaseResult = sctx.state.phaseResults["normalize-data"] ?? {};
          const dataPath = phaseResult.dataPath as string;
          const reportPath = phaseResult.reportPath as string;

          if (!dataPath) {
            throw new Error("Missing paths from normalize-data phase");
          }

          // Load normalized metrics
          const raw = await fs.readFile(dataPath, "utf-8");
          const metrics: QualitySynthesisOutput = JSON.parse(raw);

          // Generate prioritized actions, narrative, and markdown mechanically
          const { actions, narrative, markdown } = generateQualitySynthesisReport(metrics);

          sctx.emitter.emit({
            type: "log",
            level: "info",
            message: `Generated ${actions.length} prioritized actions mechanically, ${narrative.cross_cutting_themes.length} themes`,
          });

          // Update metrics JSON with prioritized actions and narrative
          metrics.prioritized_actions = actions;
          metrics.narrative_sections = narrative;
          await fs.writeFile(dataPath, JSON.stringify(metrics, null, 2), "utf-8");

          // Write markdown report
          await fs.writeFile(reportPath, markdown, "utf-8");

          sctx.emitter.emit({
            type: "log",
            level: "info",
            message: `Mechanical report generated at ${reportPath}`,
          });

          return { reportPath, dataPath };
        }),

        // Step 2: LLM — enhance narrative sections (executive summary, themes, recommendations, action descriptions)
        {
          id: "enhance-report-narrative",
          name: "Enhance report narrative",
          mode: "sequential",
          async execute(sctx: StepContext): Promise<StepResult> {
            const phaseResult = sctx.state.phaseResults["normalize-data"] ?? {};
            const dataPath = phaseResult.dataPath as string;
            const reportPath = phaseResult.reportPath as string;

            if (!dataPath || !reportPath) {
              return {
                status: "error",
                error: "Missing paths from normalize-data phase",
              };
            }

            const prompt = [
              "Enhance the pre-generated quality synthesis report with contextual narrative.",
              "",
              `Pre-generated report: ${reportPath}`,
              `Metrics JSON (with prioritized_actions[] and narrative_sections{} populated): ${dataPath}`,
              "",
              "Instructions:",
              `1. Read the pre-generated markdown report from: ${reportPath}`,
              `2. Read the metrics JSON from: ${dataPath}`,
              "3. Enhance the report:",
              "   - Improve the Executive Summary with more contextual insight about quality posture",
              "   - Improve Cross-Cutting Themes with strategic analysis of documentation gaps",
              "   - Improve Strategic Recommendations with artifact-focused, actionable advice",
              "   - Enrich prioritized action rationales with root-cause analysis",
              "   - Improve cross-cutting concern descriptions with artifact gap context",
              `4. Write the enhanced report back to: ${reportPath}`,
              "",
              "IMPORTANT: Do NOT modify any numbers, tables, or metric values.",
              "Only enhance narrative/prose sections. The report structure must remain identical.",
              "Frame all recommendations in terms of artifact operations (create/update documents),",
              "NOT AppGraph internals (nodes, edges, grounding scores).",
            ].join("\n");

            const agentCall: AgentCall = {
              agentName: "synthesis-reporter",
              prompt,
              workingDir: path.dirname(dataPath),
              outputFile: reportPath,
              allowedTools: ["Read", "Write"],
              maxToolTurns: 3, // Read report + Read metrics + Write report
            };

            const results = await sctx.agentRunner.runAgentsParallel(
              [agentCall],
              sctx.tools,
              sctx.emitter,
              sctx.signal,
              5,
            );

            for (const r of results) {
              trackAgentResult(sctx.state, r);
            }

            // No verifyAndRetry needed — the mechanical step already wrote
            // reportPath as a complete fallback. If the LLM enhancement fails,
            // the mechanical report is still usable.

            return {
              status: "success",
              data: { reportPath, dataPath },
            };
          },
        },
      ];
    },
  };
}

