    createSteps(_ctx: WorkflowContext): Step[] {
      return [
        // Step 1: Mechanical — generate leverage clusters, prioritized actions, and markdown report
        mechanicalStep("generate-report-mechanical", "Generate report (mechanical)", async (sctx) => {
          const phaseResult = sctx.state.phaseResults["normalize-data"] ?? {};
          const dataPath = phaseResult.dataPath as string;
          const reportPath = phaseResult.reportPath as string;

          if (!dataPath) {
            throw new Error("Missing paths from normalize-data phase");
          }

          // Load normalized metrics
          const raw = await fs.readFile(dataPath, "utf-8");
          const metrics: QualitySynthesisOutput = JSON.parse(raw);

          // Generate prioritized actions, narrative, and markdown mechanically
          const { actions, narrative, markdown } = generateQualitySynthesisReport(metrics);

          sctx.emitter.emit({
            type: "log",
            level: "info",
            message: `Generated ${actions.length} prioritized actions mechanically, ${narrative.cross_cutting_themes.length} themes`,
          });

          // Update metrics JSON with prioritized actions and narrative
          metrics.prioritized_actions = actions;
          metrics.narrative_sections = narrative;
          await fs.writeFile(dataPath, JSON.stringify(metrics, null, 2), "utf-8");

          // Write markdown report
          await fs.writeFile(reportPath, markdown, "utf-8");

          sctx.emitter.emit({
            type: "log",
            level: "info",
            message: `Mechanical report generated at ${reportPath}`,
          });

          return { reportPath, dataPath };
        }),

        // Step 2: LLM — enhance narrative sections (executive summary, themes, recommendations, action descriptions)
        {
          id: "enhance-report-narrative",
          name: "Enhance report narrative",
          mode: "sequential",
          async execute(sctx: StepContext): Promise<StepResult> {
            const phaseResult = sctx.state.phaseResults["normalize-data"] ?? {};
            const dataPath = phaseResult.dataPath as string;
            const reportPath = phaseResult.reportPath as string;

            if (!dataPath || !reportPath) {
              return {
                status: "error",
                error: "Missing paths from normalize-data phase",
              };
            }

            const prompt = [
              "Enhance the pre-generated quality synthesis report with contextual narrative,",
              "and assign quality dimension tags to each prioritized action.",
              "",
              `Pre-generated report: ${reportPath}`,
              `Metrics JSON (with prioritized_actions[] and narrative_sections{} populated): ${dataPath}`,
              "",
              "Instructions:",
              `1. Read the pre-generated markdown report from: ${reportPath}`,
              `2. Read the metrics JSON from: ${dataPath}`,
              "3. Assign tags to each prioritized_actions[] entry in the metrics JSON:",
              '   - Add a "tags" array to each action with one or more of: "coverage", "congruency", "completeness", "impact"',
              "   - coverage: the action improves how well artifacts ground AppGraph nodes",
              "   - congruency: the action resolves inconsistencies, naming conflicts, or contradictions",
              "   - completeness: the action fills missing requirements, features, or specification gaps",
              "   - impact: the action reduces blast radius, regression risk, or compatibility risk",
              "   - Assign ALL tags that apply. Use unified_items[].source, category_health, and cross_cutting_nodes to determine which dimensions each action addresses.",
              `   - Write the updated metrics JSON back to: ${dataPath}`,
              "4. Enhance the report:",
              "   - Improve the Executive Summary with more contextual insight about quality posture",
              "   - Improve Cross-Cutting Themes with strategic analysis of documentation gaps",
              "   - Improve Strategic Recommendations with artifact-focused, actionable advice",
              "   - Enrich prioritized action rationales with root-cause analysis",
              "   - Improve cross-cutting concern descriptions with artifact gap context",
              `5. Write the enhanced report back to: ${reportPath}`,
              "",
              "IMPORTANT: Do NOT modify any numbers, tables, or metric values in the report.",
              "Only enhance narrative/prose sections. The report structure must remain identical.",
              "In the metrics JSON, ONLY add/modify the tags field on prioritized_actions entries.",
              "Do NOT change any other fields in the JSON.",
              "Frame all recommendations in terms of artifact operations (create/update documents),",
              "NOT AppGraph internals (nodes, edges, grounding scores).",
            ].join("\n");

            const agentCall: AgentCall = {
              agentName: "synthesis-reporter",
              prompt,
              workingDir: path.dirname(dataPath),
              outputFile: reportPath,
              allowedTools: ["Read", "Write"],
              maxToolTurns: 3, // Read report + Read metrics + Write report
            };

            const results = await sctx.agentRunner.runAgentsParallel(
              [agentCall],
              sctx.tools,
              sctx.emitter,
              sctx.signal,
              5,
            );

            for (const r of results) {
              trackAgentResult(sctx.state, r);
            }

            // No verifyAndRetry needed — the mechanical step already wrote
            // reportPath as a complete fallback. If the LLM enhancement fails,
            // the mechanical report is still usable.

            return {
              status: "success",
              data: { reportPath, dataPath },
            };
          },
        },
      ];
    },
  };
}

// ---------------------------------------------------------------------------
// Workflow Definition
// ---------------------------------------------------------------------------

export const qualitySynthesisWorkflow: WorkflowDefinition = {
  id: "quality-synthesis",
  name: "Quality Synthesis",
  version: "1.0.0",
  phases: [createNormalizePhase(), createSynthesizePhase()],
};

