const NODE_TYPE_LABELS: Record<string, string> = {
  schema: "Schema",
  interface: "Interface",
  logic: "Logic",
  validation: "Validation",
};

async function loadSummaryData(workspaceRoot: string): Promise<SummaryData> {
  const entry = await loadLatestManifestEntry(workspaceRoot);

  let impact: ImpactData = {
    hasStats: false, isVersioned: false,
    totalNodes: 0, totalEdges: 0,
    newNodes: 0, newEdges: 0,
    modifiedNodes: 0, modifiedEdges: 0,
    blastRadius: 0, reportPath: null,
  };

  let coverage: CoverageData = { hasData: false, rows: [], completeness: null, reportPath: null };
  let congruency: CongruencyData = { hasData: false, cells: [], batchReportPath: null };

  if (entry) {
    let ag: BaselineAppGraph | null = null;
    try {
      const appgraphPath = path.join(workspaceRoot, VERSIONS_DIR, entry.path);
      const raw = await fs.readFile(appgraphPath, "utf-8");
      ag = JSON.parse(raw) as BaselineAppGraph;
    } catch {
      // Appgraph file not found
    }

    // Impact
    {
      let newNodes = 0, newEdges = 0, modifiedNodes = 0, modifiedEdges = 0;
      let isVersioned = false;
      let blastRadius = 0;

      if (ag) {
        const allNodes = [
          ...(ag.nodes ?? []),
          ...(ag.requirement_nodes ?? []),
          ...(ag.validation_nodes ?? []),
        ];
        const edges = ag.edges ?? [];

        for (const n of allNodes) {
          if (n.impact_status === "new") newNodes++;
          else if (n.impact_status === "modified") modifiedNodes++;
        }
        for (const e of edges) {
          if (e.impact_status === "new") newEdges++;
          else if (e.impact_status === "modified") modifiedEdges++;
        }
        if (newNodes > 0 || modifiedNodes > 0) isVersioned = true;

        const meta = (ag as Record<string, unknown>).metadata as Record<string, unknown> | undefined;
        const stats = meta?.stats as Record<string, unknown> | undefined;
        const impactStats = stats?.impact as Record<string, unknown> | undefined;
        if (impactStats && typeof impactStats.blast_radius === "number") {
          blastRadius = impactStats.blast_radius;
        }
      }

      const analysisDir = await getLatestAnalysisDir(workspaceRoot);
      const reportPath = analysisDir ? await findImpactReport(analysisDir) : null;

      impact = {
        hasStats: true, isVersioned,
        totalNodes: entry.node_count, totalEdges: entry.edge_count,
        newNodes, newEdges, modifiedNodes, modifiedEdges,
        blastRadius, reportPath,
      };
    }

    // Coverage
    {
      let grounding = entry.grounding_distribution ?? {};
      let completeness: CompletenessData | null = null;

      const allNodes = ag ? [
        ...(ag.nodes ?? []),
        ...(ag.requirement_nodes ?? []),
        ...(ag.validation_nodes ?? []),
      ] : [];

      if (ag && Object.keys(grounding).length === 0) {
        grounding = computeGroundingDistribution(allNodes);
      }

      if (ag) {
        const meta = (ag as Record<string, unknown>).metadata as Record<string, unknown> | undefined;
        const stats = meta?.stats as Record<string, unknown> | undefined;
        const comp = stats?.completeness as Record<string, number> | undefined;
        if (comp && typeof comp === "object") {
          const designTypes = new Set(["interface", "schema", "logic"]);
          completeness = {
            ...comp,
            total_requirements: allNodes.filter((n: Record<string, unknown>) => n.type === "requirement").length,
            total_designs: allNodes.filter((n: Record<string, unknown>) => designTypes.has(n.type as string ?? "")).length,
            total_validations: allNodes.filter((n: Record<string, unknown>) => n.type === "validation").length,
          } as CompletenessData;
        }
      }

      const groundingNodeTypes = NODE_TYPES.filter((nt) => nt !== "requirement" && nt !== "validation");
      const rows: CoverageRow[] = groundingNodeTypes.map((nt) => {
        const row = grounding[nt] ?? {};
        return {
          nodeType: nt,
          label: NODE_TYPE_LABELS[nt] ?? nt,
          groundingPct: typeof row.grounding_pct === "number" ? row.grounding_pct : 0,
        };
      });

      const analysisDir = await getLatestAnalysisDir(workspaceRoot);
      const reportPath = analysisDir ? await findCoverageReport(analysisDir) : null;

      coverage = { hasData: Object.keys(grounding).length > 0, rows, completeness, reportPath };
    }

    // Congruency
    {
      if (ag) {
        const meta = (ag as Record<string, unknown>).metadata as Record<string, unknown> | undefined;
        const stats = meta?.stats as Record<string, unknown> | undefined;
        const cong = stats?.congruency as Record<string, unknown> | undefined;
        let perArtifact: Array<Record<string, unknown>> = [];
        if (cong && Array.isArray(cong.per_artifact)) {
          perArtifact = cong.per_artifact as Array<Record<string, unknown>>;
        }

        if (perArtifact.length > 0) {
          const totalAppGraphNodes = entry.node_count;
          const cells: CongruencyCell[] = perArtifact.map((art) => {
            const storedScore = art.congruency_score;
            let pct: number;
            if (typeof storedScore === "number") {
              pct = Math.round(storedScore * 100) / 10000;
            } else {
              const nodesAffected = Number(art.nodes_affected ?? 0);
              pct = totalAppGraphNodes > 0
                ? Math.round((1 - nodesAffected / totalAppGraphNodes) * 10000) / 10000
                : -1;
            }
            return {
              artifactName: String(art.artifact_name ?? ""),
              totalNodes: totalAppGraphNodes,
              congruencyPct: pct,
            };
          });

          const analysisDir = await getLatestAnalysisDir(workspaceRoot);
          const batchReportPath = analysisDir ? await findCongruencyBatchReport(analysisDir) : null;
          congruency = { hasData: true, cells, batchReportPath };
        }
      }
    }
  } else {
    // No manifest — try baseline
    const baseline = await loadBaseline(workspaceRoot);
    if (baseline) {
      const allNodes = [
        ...(baseline.nodes ?? []),
        ...(baseline.requirement_nodes ?? []),
        ...(baseline.validation_nodes ?? []),
      ];
      const edges = baseline.edges ?? [];

      impact = {
        hasStats: true, isVersioned: false,
        totalNodes: allNodes.length, totalEdges: edges.length,
        newNodes: 0, newEdges: 0, modifiedNodes: 0, modifiedEdges: 0,
        blastRadius: 0, reportPath: null,
      };

      const grounding = computeGroundingDistribution(allNodes);
      const groundingNodeTypes = NODE_TYPES.filter((nt) => nt !== "requirement" && nt !== "validation");
      const rows: CoverageRow[] = groundingNodeTypes.map((nt) => {
        const row = grounding[nt] ?? {};
        return {
          nodeType: nt,
          label: NODE_TYPE_LABELS[nt] ?? nt,
          groundingPct: typeof row.grounding_pct === "number" ? row.grounding_pct : 0,
        };
      });

      coverage = { hasData: Object.keys(grounding).length > 0, rows, completeness: null, reportPath: null };
    }
  }

  return { impact, coverage, congruency };
}

