  <script nonce="${nonce}">
    const vscode = acquireVsCodeApi();

    // Custom tooltips
    (function() {
      const tooltip = document.getElementById('tooltip');
      let tooltipTimer = null;
      document.querySelectorAll('[data-tooltip]').forEach(el => {
        el.addEventListener('mouseenter', () => {
          const text = el.getAttribute('data-tooltip');
          if (!text) return;
          tooltipTimer = setTimeout(() => {
            tooltip.textContent = text;
            tooltip.style.display = 'block';
            const rect = el.getBoundingClientRect();
            tooltip.style.top = (rect.bottom + 4) + 'px';
            let left = rect.left;
            const tipRect = tooltip.getBoundingClientRect();
            if (left + tipRect.width > document.documentElement.clientWidth) {
              left = document.documentElement.clientWidth - tipRect.width - 8;
            }
            if (left < 4) left = 4;
            tooltip.style.left = left + 'px';
          }, 400);
        });
        el.addEventListener('mouseleave', () => {
          clearTimeout(tooltipTimer);
          tooltip.style.display = 'none';
        });
      });
    })();

    // Tab switching with state persistence
    (function() {
      const state = vscode.getState() || {};
      const activeTab = state.activeTab;

      if (activeTab) {
        const btn = document.querySelector('.tab-btn[data-tab="' + activeTab + '"]');
        if (btn) {
          document.querySelectorAll('.tab-btn').forEach(b => b.classList.remove('tab-active'));
          document.querySelectorAll('.tab-panel').forEach(p => p.classList.remove('tab-panel-active'));
          btn.classList.add('tab-active');
          const panel = document.querySelector('.tab-panel[data-tab-panel="' + activeTab + '"]');
          if (panel) panel.classList.add('tab-panel-active');
        }
      }

      document.querySelectorAll('.tab-btn').forEach(btn => {
        btn.addEventListener('click', () => {
          const tabId = btn.getAttribute('data-tab');
          document.querySelectorAll('.tab-btn').forEach(b => b.classList.remove('tab-active'));
          document.querySelectorAll('.tab-panel').forEach(p => p.classList.remove('tab-panel-active'));
          btn.classList.add('tab-active');
          const panel = document.querySelector('.tab-panel[data-tab-panel="' + tabId + '"]');
          if (panel) panel.classList.add('tab-panel-active');
          vscode.setState({ ...vscode.getState(), activeTab: tabId });
        });
      });
    })();

    document.querySelectorAll('.cta-btn').forEach(btn => {
      btn.addEventListener('click', () => {
        const command = btn.getAttribute('data-command');
        if (command) vscode.postMessage({ type: 'command', command });
      });
    });

    document.querySelectorAll('[data-report-path]').forEach(el => {
      el.addEventListener('click', () => {
        const reportPath = el.getAttribute('data-report-path');
        if (reportPath) vscode.postMessage({ type: 'openReport', path: reportPath });
      });
    });
  </script>
</body>
</html>`;
