1089→function renderPieChart(d: ImpactData): string {
1090→  const newTotal = d.newNodes + d.newEdges;
1091→  const modTotal = d.modifiedNodes + d.modifiedEdges;
1092→  const total = d.totalNodes + d.totalEdges;
1093→  const intactTotal = total - newTotal - modTotal;
1094→
1095→  if (total === 0) return `<div class="muted">No nodes or edges</div>`;
1096→
1097→  const r = 40;
1098→  const cx = 50;
1099→  const cy = 50;
1100→  const strokeWidth = 16;
1101→  const circumference = 2 * Math.PI * r;
1102→
1103→  const segments = [
1104→    { label: "New", count: newTotal, color: "var(--vscode-charts-green, #89d185)" },
1105→    { label: "Modified", count: modTotal, color: "var(--vscode-charts-orange, #cca700)" },
1106→    { label: "Intact", count: intactTotal, color: "var(--vscode-charts-foreground, rgba(128,128,128,0.3))" },
1107→  ].filter((s) => s.count > 0);
1108→
1109→  let paths = "";
1110→  let offset = 0;
1111→  for (const seg of segments) {
1112→    const pct = seg.count / total;
1113→    const dashLen = pct * circumference;
1114→    const dashGap = circumference - dashLen;
1115→    paths += `<circle cx="${cx}" cy="${cy}" r="${r}" fill="none"
1116→      stroke="${seg.color}" stroke-width="${strokeWidth}"
1117→      stroke-dasharray="${dashLen.toFixed(2)} ${dashGap.toFixed(2)}"
1118→      stroke-dashoffset="${(-offset).toFixed(2)}"
1119→      transform="rotate(-90 ${cx} ${cy})" />`;
1120→    offset += dashLen;
1121→  }
1122→
1123→  const legendItems = segments
1124→    .map((s) => {
1125→      const pct = Math.round((s.count / total) * 100);
1126→      return `<div class="legend-item">
1127→        <span class="legend-dot" style="background:${s.color}"></span>
1128→        <span class="legend-label">${s.label}</span>
1129→        <span class="legend-value">${pct}%</span>
1130→      </div>`;
1131→    })
1132→    .join("");
1133→
1134→  return `
1135→    <div class="pie-container">
1136→      <svg class="pie-chart" viewBox="0 0 100 100">
1137→        ${paths}
1138→        <text x="${cx}" y="${cy}" text-anchor="middle" dominant-baseline="central"
1139→          fill="var(--vscode-foreground)" font-size="14" font-weight="600">${Math.round(d.blastRadius * 100)}%</text>
1140→      </svg>
1141→      <div class="legend">${legendItems}</div>
1142→    </div>`;
1143→}
