1164→/** Map congruency 0.0-1.0 to a red-yellow-green color. */
1165→function congruencyColor(pct: number): string {
1166→  if (pct < 0) return "rgba(128,128,128,0.3)";
1167→  const t = Math.max(0, Math.min(1, (pct - 0.3) / 0.5));
1168→  const r = t < 0.5 ? 255 : Math.round(255 * (1 - t) * 2);
1169→  const g = t > 0.5 ? 200 : Math.round(200 * t * 2);
1170→  return `rgb(${r}, ${g}, 60)`;
1171→}
