1173→interface TreemapRect { x: number; y: number; w: number; h: number; }
1174→
1175→function squarify(values: number[], container: TreemapRect): TreemapRect[] {
1176→  const total = values.reduce((a, b) => a + b, 0);
1177→  if (total === 0 || values.length === 0) return [];
1178→
1179→  const rects: TreemapRect[] = new Array(values.length);
1180→  const indices = values.map((_, i) => i).sort((a, b) => values[b] - values[a]);
1181→
1182→  function layoutRow(row: number[], box: TreemapRect, totalVal: number): TreemapRect {
1183→    const rowSum = row.reduce((a, i) => a + values[i], 0);
1184→    const fraction = rowSum / totalVal;
1185→    const horizontal = box.w >= box.h;
1186→    let offset = 0;
1187→
1188→    if (horizontal) {
1189→      const rowW = box.w * fraction;
1190→      for (const idx of row) {
1191→        const h = box.h * (values[idx] / rowSum);
1192→        rects[idx] = { x: box.x, y: box.y + offset, w: rowW, h };
1193→        offset += h;
1194→      }
1195→      return { x: box.x + rowW, y: box.y, w: box.w - rowW, h: box.h };
1196→    } else {
1197→      const rowH = box.h * fraction;
1198→      for (const idx of row) {
1199→        const w = box.w * (values[idx] / rowSum);
1200→        rects[idx] = { x: box.x + offset, y: box.y, w, h: rowH };
1201→        offset += w;
1202→      }
1203→      return { x: box.x, y: box.y + rowH, w: box.w, h: box.h - rowH };
1204→    }
1205→  }
1206→
1207→  function worstRatio(row: number[], side: number, totalVal: number): number {
1208→    const rowSum = row.reduce((a, i) => a + values[i], 0);
1209→    const fraction = rowSum / totalVal;
1210→    const rowSide = side * fraction;
1211→    if (rowSide === 0) return Infinity;
1212→    let worst = 0;
1213→    for (const idx of row) {
1214→      const cellSide = (side * (values[idx] / rowSum));
1215→      const r = Math.max(cellSide / rowSide, rowSide / cellSide);
1216→      if (r > worst) worst = r;
1217→    }
1218→    return worst;
1219→  }
1220→
1221→  let box = { ...container };
1222→  let remaining = [...indices];
1223→  let remTotal = total;
1224→
1225→  while (remaining.length > 0) {
1226→    const side = Math.min(box.w, box.h);
1227→    const row: number[] = [remaining[0]];
1228→    remaining = remaining.slice(1);
1229→
1230→    let currentWorst = worstRatio(row, side, remTotal);
1231→
1232→    while (remaining.length > 0) {
1233→      const candidate = [...row, remaining[0]];
1234→      const candidateWorst = worstRatio(candidate, side, remTotal);
1235→      if (candidateWorst <= currentWorst) {
1236→        row.push(remaining[0]);
1237→        remaining = remaining.slice(1);
1238→        currentWorst = candidateWorst;
1239→      } else {
1240→        break;
1241→      }
1242→    }
1243→
1244→    box = layoutRow(row, box, remTotal);
1245→    remTotal -= row.reduce((a, i) => a + values[i], 0);
1246→  }
1247→
1248→  return rects;
1249→}
