    tabs.push({ id: "completeness", icon: "debug-disconnect", label: "Completeness", content: completenessContent });
  }
  if (advancedMetrics) {
    tabs.push({ id: "advanced", icon: "tools", label: "Advanced Metrics", content: renderAdvancedMetricsContent(advancedMetrics) });
  }

  let tabsHtml = "";
  if (tabs.length > 0) {
    const tabButtons = tabs
      .map((t, i) => `<button class="tab-btn${i === 0 ? " tab-active" : ""}" data-tab="${t.id}" data-tooltip="${t.label}"><i class="codicon codicon-${t.icon}"></i></button>`)
      .join("");

    const tabPanels = tabs
      .map((t, i) => `<div class="tab-panel${i === 0 ? " tab-panel-active" : ""}" data-tab-panel="${t.id}">${t.content}</div>`)
      .join("");

    tabsHtml = `
      <hr class="separator" />
      <div class="tab-bar">${tabButtons}</div>
      <div class="tab-panels">${tabPanels}</div>`;
  }

  return `<!DOCTYPE html>
