// ---------------------------------------------------------------------------
// WebviewView Provider
// ---------------------------------------------------------------------------

class ContextViewProvider implements vscode.WebviewViewProvider {
  private view: vscode.WebviewView | undefined;
  private runningWorkflowId: string | null = null;

  constructor(
    private extensionUri: vscode.Uri,
    private workspaceRoot: string,
  ) {}

  resolveWebviewView(webviewView: vscode.WebviewView): void {
    this.view = webviewView;

    webviewView.webview.options = {
      enableScripts: true,
      localResourceRoots: [
        vscode.Uri.joinPath(this.extensionUri, "node_modules", "@vscode", "codicons", "dist"),
      ],
    };

    webviewView.onDidDispose(() => {
      this.view = undefined;
    });

    webviewView.webview.onDidReceiveMessage((msg) => {
      if (msg.type === "command" && typeof msg.command === "string") {
        logUsage("ui_action", { panel: "context", action: "command", command: msg.command });
        vscode.commands.executeCommand(msg.command);
      } else if (msg.type === "openReport" && typeof msg.path === "string") {
        logUsage("ui_action", { panel: "context", action: "open_report", report_type: inferReportType(msg.path) });
        const uri = vscode.Uri.file(msg.path);
        const cmd = msg.path.endsWith(".md") ? "markdown.showPreview" : "vscode.open";
        vscode.commands.executeCommand(cmd, uri);
      }
    });

    this.updateHtml();
  }

  async refresh(): Promise<void> {
    await this.updateContextKey();
    await this.updateHtml();
  }

  setWorkflowRunning(workflowId: string | null): void {
    this.runningWorkflowId = workflowId;
    this.updateHtml();
  }

  /** Update context keys that control Context Details / Advanced Metrics panel visibility. */
  private async updateContextKey(): Promise<void> {
    const data = await loadContextData(this.workspaceRoot);
    this.lastData = data;
    vscode.commands.executeCommand("setContext", "alucify.hasProjectAppgraph", data.hasProjectAppgraph);
    vscode.commands.executeCommand("setContext", "alucify.hasAnyAppgraph", data.hasStats);
  }

  private lastData: ContextData | undefined;

  private async updateHtml(): Promise<void> {
    if (!this.view) return;
    const codiconCssUri = this.view.webview.asWebviewUri(
      vscode.Uri.joinPath(this.extensionUri, "node_modules", "@vscode", "codicons", "dist", "codicon.css"),
    );
    const data = this.lastData ?? await loadContextData(this.workspaceRoot);
    this.lastData = undefined;
    // Load summary data for tabbed visuals when project appgraph exists
    const summary = data.hasProjectAppgraph ? await loadSummaryData(this.workspaceRoot) : null;
    // Load advanced metrics only when advanced mode is enabled
    const advancedMetrics = data.hasProjectAppgraph && isAdvancedMode()
      ? await loadAdvancedMetricsData(this.workspaceRoot)
      : null;
    const nonce = getNonce();
    const cspSource = this.view.webview.cspSource;
    this.view.webview.html = getHtml(codiconCssUri.toString(), data, summary, advancedMetrics, this.runningWorkflowId, nonce, cspSource);
  }
}

// ---------------------------------------------------------------------------
// Module state
// ---------------------------------------------------------------------------

let viewProvider: ContextViewProvider | undefined;
let manifestWatcher: vscode.FileSystemWatcher | undefined;
let baselineWatcher: vscode.FileSystemWatcher | undefined;
let artifactsWatcher: vscode.FileSystemWatcher | undefined;
let pipelineManifestWatcher: vscode.FileSystemWatcher | undefined;
let debounceTimer: ReturnType<typeof setTimeout> | undefined;

// ---------------------------------------------------------------------------
// Public API
// ---------------------------------------------------------------------------

export function register(context: vscode.ExtensionContext): void {
  const workspaceFolder = vscode.workspace.workspaceFolders?.[0];
  if (!workspaceFolder) return;

  viewProvider = new ContextViewProvider(context.extensionUri, workspaceFolder.uri.fsPath);

  context.subscriptions.push(
    vscode.window.registerWebviewViewProvider(
      "alucify.context",
      viewProvider,
    ),
  );

  // Set context key eagerly so panel visibility is correct before webview opens
  viewProvider.refresh();

  // File system watchers with debounced refresh
  const debouncedRefresh = (): void => {
    if (debounceTimer) clearTimeout(debounceTimer);
    debounceTimer = setTimeout(() => viewProvider?.refresh(), 500);
  };

  manifestWatcher = vscode.workspace.createFileSystemWatcher(
    new vscode.RelativePattern(workspaceFolder, ".alucify/versions/manifest.json"),
  );
  manifestWatcher.onDidCreate(debouncedRefresh);
  manifestWatcher.onDidChange(debouncedRefresh);
  manifestWatcher.onDidDelete(debouncedRefresh);
  context.subscriptions.push(manifestWatcher);

  baselineWatcher = vscode.workspace.createFileSystemWatcher(
    new vscode.RelativePattern(workspaceFolder, ".alucify/appgraph-baseline.json"),
  );
  baselineWatcher.onDidCreate(debouncedRefresh);
  baselineWatcher.onDidChange(debouncedRefresh);
  baselineWatcher.onDidDelete(debouncedRefresh);
  context.subscriptions.push(baselineWatcher);

  // Watch artifacts folder so CTA button updates when artifacts are added/changed
  artifactsWatcher = vscode.workspace.createFileSystemWatcher(
    new vscode.RelativePattern(workspaceFolder, ".alucify/artifacts/**/*"),
  );
  artifactsWatcher.onDidCreate(debouncedRefresh);
  artifactsWatcher.onDidChange(debouncedRefresh);
  artifactsWatcher.onDidDelete(debouncedRefresh);
  context.subscriptions.push(artifactsWatcher);

  // Watch pipeline manifest so CTA buttons update after workflows complete
  pipelineManifestWatcher = vscode.workspace.createFileSystemWatcher(
    new vscode.RelativePattern(workspaceFolder, ".alucify/artifact-manifest.json"),
  );
  pipelineManifestWatcher.onDidChange(debouncedRefresh);
  pipelineManifestWatcher.onDidCreate(debouncedRefresh);
  context.subscriptions.push(pipelineManifestWatcher);

  // Re-render when alucify.advanced setting changes so the Advanced tab appears/disappears
  context.subscriptions.push(
    vscode.workspace.onDidChangeConfiguration((e) => {
      if (e.affectsConfiguration("alucify.advanced")) {
        debouncedRefresh();
      }
    }),
  );
}

export function refresh(): void {
  viewProvider?.refresh();
}

export function setWorkflowRunning(workflowId: string | null): void {
  viewProvider?.setWorkflowRunning(workflowId);
}

export function dispose(): void {
  if (debounceTimer) clearTimeout(debounceTimer);
  manifestWatcher?.dispose();
  baselineWatcher?.dispose();
  artifactsWatcher?.dispose();
  pipelineManifestWatcher?.dispose();
  viewProvider = undefined;
  manifestWatcher = undefined;
  baselineWatcher = undefined;
  artifactsWatcher = undefined;
}

