      border: none;
      border-top: 1px solid var(--vscode-panel-border, rgba(128,128,128,0.2));
      margin: 16px 0 8px;
    }

    /* Tab bar — GitLens-style icon tabs */
    .tab-bar {
      display: flex;
      gap: 0;
      margin: 0 -16px;           /* full-bleed: span past body padding */
      padding: 0 16px;
      background: #363636;
      border-bottom: 1px solid var(--vscode-panel-border, rgba(128,128,128,0.2));
      margin-bottom: 12px;
