    }

    .view-details-link {
      font-size: 10px;
      font-weight: 400;
      text-transform: none;
      letter-spacing: normal;
      color: var(--vscode-textLink-foreground);
      cursor: pointer;
      text-decoration: none;
      margin-left: 6px;
    }
    .view-details-link:hover {
      text-decoration: underline;
    }

    /* Impact: summary counts (non-versioned) */
    .summary-counts {
      font-size: 13px;
      color: var(--vscode-descriptionForeground);
    }
    .count-value { font-weight: 600; color: var(--vscode-foreground); }
    .count-sep { margin: 0 6px; }

    /* Impact: pie chart */
    .pie-container {
      display: flex;
      align-items: center;
      gap: 16px;
    }
    .pie-chart {
      width: 80px;
      height: 80px;
      flex-shrink: 0;
    }
    .legend {
      display: flex;
      flex-direction: column;
      gap: 4px;
    }
    .legend-item {
      display: flex;
      align-items: center;
      gap: 6px;
      font-size: 11px;
    }
    .legend-dot {
      width: 8px;
      height: 8px;
      border-radius: 50%;
      flex-shrink: 0;
    }
    .legend-label {
      color: var(--vscode-descriptionForeground);
    }
    .legend-value {
      color: var(--vscode-foreground);
      font-weight: 500;
    }

    /* Coverage: progress bars */
    .bars-container {
      display: flex;
      flex-direction: column;
      gap: 8px;
    }
    .bar-row {
      display: flex;
      align-items: center;
      gap: 8px;
    }
    .bar-label {
      width: 72px;
      flex-shrink: 0;
      font-size: 11px;
      color: var(--vscode-descriptionForeground);
    }
    .bar-track {
      flex: 1;
      height: 6px;
      border-radius: 3px;
      background: var(--vscode-editor-background, rgba(128,128,128,0.15));
      overflow: hidden;
    }
    .bar-fill {
      height: 100%;
      border-radius: 3px;
      background: var(--vscode-charts-purple, #b180d7);
      transition: width 0.3s ease;
    }
    .bar-value {
      width: 32px;
      flex-shrink: 0;
      text-align: right;
      font-size: 11px;
      font-weight: 600;
