    }
    .completeness-label {
      color: var(--vscode-descriptionForeground);
    }
    .completeness-count {
      text-align: right;
      color: var(--vscode-descriptionForeground);
    }
    .completeness-value {
      text-align: right;
      font-weight: 600;
      padding-left: 8px;
    }

    /* Recommendations list */
    .actions-list {
