      background: var(--vscode-editorHoverWidget-background, var(--vscode-editor-background));
      color: var(--vscode-editorHoverWidget-foreground, var(--vscode-foreground));
      font-size: 12px;
      line-height: 1.5;
      pointer-events: none;
      box-shadow: 0 2px 8px rgba(0,0,0,0.2);
    }

    /* Tab content header row */
    .tab-header-row {
      display: flex;
      justify-content: space-between;
      align-items: baseline;
      margin-bottom: 8px;
    }
    .tab-section-label {
      font-size: 11px;
      font-weight: 600;
      text-transform: uppercase;
      letter-spacing: 0.3px;
      color: var(--vscode-descriptionForeground);
    }

    .view-details-link {
      font-size: 10px;
      font-weight: 400;
      text-transform: none;
      letter-spacing: normal;
      color: var(--vscode-textLink-foreground);
      cursor: pointer;
      text-decoration: none;
      margin-left: 6px;
    }
    .view-details-link:hover {
      text-decoration: underline;
    }

    /* Impact: summary counts (non-versioned) */
    .summary-counts {
      font-size: 13px;
      color: var(--vscode-descriptionForeground);
    }
    .count-value { font-weight: 600; color: var(--vscode-foreground); }
    .count-sep { margin: 0 6px; }

    /* Impact: pie chart */
    .pie-container {
      display: flex;
      align-items: center;
      gap: 16px;
    }
    .pie-chart {
      width: 80px;
      height: 80px;
      flex-shrink: 0;
    }
    .legend {
      display: flex;
      flex-direction: column;
      gap: 4px;
    }
    .legend-item {
      display: flex;
      align-items: center;
      gap: 6px;
      font-size: 11px;
    }
    .legend-dot {
      width: 8px;
      height: 8px;
      border-radius: 50%;
      flex-shrink: 0;
    }
    .legend-label {
      color: var(--vscode-descriptionForeground);
    }
    .legend-value {
      color: var(--vscode-foreground);
      font-weight: 500;
    }

    /* Coverage: progress bars */
    .bars-container {
      display: flex;
      flex-direction: column;
      gap: 8px;
    }
    .bar-row {
      display: flex;
      align-items: center;
      gap: 8px;
    }
    .bar-label {
      width: 72px;
      flex-shrink: 0;
      font-size: 11px;
      color: var(--vscode-descriptionForeground);
    }
    .bar-track {
      flex: 1;
      height: 6px;
      border-radius: 3px;
      background: var(--vscode-editor-background, rgba(128,128,128,0.15));
      overflow: hidden;
    }
    .bar-fill {
      height: 100%;
      border-radius: 3px;
      background: var(--vscode-charts-purple, #b180d7);
      transition: width 0.3s ease;
    }
    .bar-value {
      width: 32px;
      flex-shrink: 0;
      text-align: right;
      font-size: 11px;
      font-weight: 600;
    }

    /* Congruency: treemap heatmap */
    .heatmap-container {
      position: relative;
    }
    .heatmap-cell {
      position: absolute;
      box-sizing: border-box;
      display: flex;
      flex-direction: column;
      align-items: center;
      justify-content: center;
      border: 1px solid var(--vscode-editor-background, rgba(0,0,0,0.2));
      padding: 2px;
      overflow: hidden;
      cursor: default;
    }
    .heatmap-pct {
      font-size: 13px;
      font-weight: 700;
      color: #fff;
      text-shadow: 0 1px 2px rgba(0,0,0,0.4);
    }
    .heatmap-name {
      font-size: 9px;
      color: rgba(255,255,255,0.85);
      text-shadow: 0 1px 2px rgba(0,0,0,0.4);
      text-align: center;
      overflow: hidden;
      text-overflow: ellipsis;
      white-space: nowrap;
      max-width: 100%;
    }

    /* Advanced Metrics tab */
    .adv-section-header {
      display: flex;
      justify-content: space-between;
      align-items: baseline;
      font-size: 11px;
      font-weight: 600;
      text-transform: uppercase;
      letter-spacing: 0.3px;
      color: var(--vscode-descriptionForeground);
      margin: 8px 0 4px;
    }
    .adv-separator {
      border: none;
      border-top: 1px solid var(--vscode-panel-border, rgba(128,128,128,0.2));
      margin: 16px 0 8px;
    }
    .data-table {
      width: 100%;
      border-collapse: collapse;
      font-size: 11px;
      margin: 4px 0 8px;
    }
    .data-table th,
    .data-table td {
      padding: 2px 6px;
      text-align: right;
      border: 1px solid var(--vscode-panel-border, rgba(128,128,128,0.2));
    }
    .data-table thead th {
      font-weight: 600;
      color: var(--vscode-descriptionForeground);
      text-align: right;
    }
    .data-table thead th:first-child {
      text-align: left;
    }
    .data-table .row-header {
      text-align: left;
      font-weight: 600;
      max-width: 120px;
      overflow: hidden;
      text-overflow: ellipsis;
      white-space: nowrap;
    }
    .data-table .pct-cell {
      font-weight: 600;
    }
    .data-table tr.clickable {
      cursor: pointer;
    }
    .data-table tr.clickable:hover {
      background: var(--vscode-list-hoverBackground, rgba(128,128,128,0.1));
    }
    .version-table-wrapper {
      overflow-x: auto;
      margin: 4px 0 8px;
    }
    .completeness-table {
      width: 100%;
      border-collapse: collapse;
      font-size: 11px;
      margin: 4px 0 8px;
    }
    .completeness-table td {
      padding: 3px 0;
      border-bottom: 1px solid var(--vscode-panel-border, rgba(128,128,128,0.1));
    }
    .completeness-label {
      color: var(--vscode-descriptionForeground);
    }
    .completeness-count {
      text-align: right;
      color: var(--vscode-descriptionForeground);
    }
    .completeness-value {
      text-align: right;
      font-weight: 600;
      padding-left: 8px;
    }

    /* Recommendations list */
    .actions-list {
      margin: 0;
      padding-left: 20px;
      font-size: var(--vscode-font-size);
    }
    .actions-list li {
      margin-bottom: 6px;
      line-height: 1.4;
    }
    .tag-pill {
      display: inline-block;
      font-size: 10px;
      line-height: 1;
      padding: 2px 6px;
      margin-left: 4px;
      border-radius: 9px;
      vertical-align: middle;
      opacity: 0.85;
      background: var(--vscode-charts-blue, #3794ff);
      color: #fff;
    }
    .more-actions {
      font-size: 11px;
      color: var(--vscode-descriptionForeground);
      margin-top: 4px;
    }

  </style>
</head>
<body>
  ${versionHtml}
  ${metricsHtml}
  ${tabsHtml}
  <div class="custom-tooltip" id="tooltip"></div>

  <script nonce="${nonce}">
    const vscode = acquireVsCodeApi();

    // Custom tooltips
    (function() {
      const tooltip = document.getElementById('tooltip');
      let tooltipTimer = null;
      document.querySelectorAll('[data-tooltip]').forEach(el => {
        el.addEventListener('mouseenter', () => {
          const text = el.getAttribute('data-tooltip');
          if (!text) return;
          tooltipTimer = setTimeout(() => {
            tooltip.textContent = text;
            tooltip.style.display = 'block';
            const rect = el.getBoundingClientRect();
            tooltip.style.top = (rect.bottom + 4) + 'px';
            let left = rect.left;
            const tipRect = tooltip.getBoundingClientRect();
            if (left + tipRect.width > document.documentElement.clientWidth) {
              left = document.documentElement.clientWidth - tipRect.width - 8;
            }
            if (left < 4) left = 4;
            tooltip.style.left = left + 'px';
          }, 400);
        });
        el.addEventListener('mouseleave', () => {
          clearTimeout(tooltipTimer);
          tooltip.style.display = 'none';
        });
      });
    })();

    // Tab switching with state persistence
    (function() {
      const state = vscode.getState() || {};
      const activeTab = state.activeTab;

      if (activeTab) {
        const btn = document.querySelector('.tab-btn[data-tab="' + activeTab + '"]');
        if (btn) {
          document.querySelectorAll('.tab-btn').forEach(b => b.classList.remove('tab-active'));
          document.querySelectorAll('.tab-panel').forEach(p => p.classList.remove('tab-panel-active'));
          btn.classList.add('tab-active');
          const panel = document.querySelector('.tab-panel[data-tab-panel="' + activeTab + '"]');
          if (panel) panel.classList.add('tab-panel-active');
        }
      }

      document.querySelectorAll('.tab-btn').forEach(btn => {
        btn.addEventListener('click', () => {
          const tabId = btn.getAttribute('data-tab');
          document.querySelectorAll('.tab-btn').forEach(b => b.classList.remove('tab-active'));
          document.querySelectorAll('.tab-panel').forEach(p => p.classList.remove('tab-panel-active'));
          btn.classList.add('tab-active');
          const panel = document.querySelector('.tab-panel[data-tab-panel="' + tabId + '"]');
          if (panel) panel.classList.add('tab-panel-active');
          vscode.setState({ ...vscode.getState(), activeTab: tabId });
        });
      });
    })();

    document.querySelectorAll('.cta-btn').forEach(btn => {
      btn.addEventListener('click', () => {
        const command = btn.getAttribute('data-command');
        if (command) vscode.postMessage({ type: 'command', command });
      });
    });

    document.querySelectorAll('[data-report-path]').forEach(el => {
      el.addEventListener('click', () => {
        const reportPath = el.getAttribute('data-report-path');
        if (reportPath) vscode.postMessage({ type: 'openReport', path: reportPath });
      });
    });
  </script>
</body>
</html>`;
}

// ---------------------------------------------------------------------------
// WebviewView Provider
// ---------------------------------------------------------------------------

class ContextViewProvider implements vscode.WebviewViewProvider {
  private view: vscode.WebviewView | undefined;
  private runningWorkflowId: string | null = null;

  constructor(
    private extensionUri: vscode.Uri,
    private workspaceRoot: string,
  ) {}

  resolveWebviewView(webviewView: vscode.WebviewView): void {
    this.view = webviewView;

    webviewView.webview.options = {
      enableScripts: true,
      localResourceRoots: [
        vscode.Uri.joinPath(this.extensionUri, "node_modules", "@vscode", "codicons", "dist"),
      ],
    };

    webviewView.onDidDispose(() => {
      this.view = undefined;
    });

    webviewView.webview.onDidReceiveMessage((msg) => {
      if (msg.type === "command" && typeof msg.command === "string") {
        logUsage("ui_action", { panel: "context", action: "command", command: msg.command });
        vscode.commands.executeCommand(msg.command);
      } else if (msg.type === "openReport" && typeof msg.path === "string") {
        logUsage("ui_action", { panel: "context", action: "open_report", report_type: inferReportType(msg.path) });
        const uri = vscode.Uri.file(msg.path);
        const cmd = msg.path.endsWith(".md") ? "markdown.showPreview" : "vscode.open";
        vscode.commands.executeCommand(cmd, uri);
      }
    });

    this.updateHtml();
  }

  async refresh(): Promise<void> {
    await this.updateContextKey();
    await this.updateHtml();
  }

  setWorkflowRunning(workflowId: string | null): void {
    this.runningWorkflowId = workflowId;
    this.updateHtml();
  }

  /** Update context keys that control Context Details / Advanced Metrics panel visibility. */
  private async updateContextKey(): Promise<void> {
    const data = await loadContextData(this.workspaceRoot);
    this.lastData = data;
    vscode.commands.executeCommand("setContext", "alucify.hasProjectAppgraph", data.hasProjectAppgraph);
    vscode.commands.executeCommand("setContext", "alucify.hasAnyAppgraph", data.hasStats);
  }

  private lastData: ContextData | undefined;

  private async updateHtml(): Promise<void> {
    if (!this.view) return;
    const codiconCssUri = this.view.webview.asWebviewUri(
      vscode.Uri.joinPath(this.extensionUri, "node_modules", "@vscode", "codicons", "dist", "codicon.css"),
    );
    const data = this.lastData ?? await loadContextData(this.workspaceRoot);
    this.lastData = undefined;
    // Load summary data for tabbed visuals when project appgraph exists
    const summary = data.hasProjectAppgraph ? await loadSummaryData(this.workspaceRoot) : null;
    // Load advanced metrics only when advanced mode is enabled
    const advancedMetrics = data.hasProjectAppgraph && isAdvancedMode()
      ? await loadAdvancedMetricsData(this.workspaceRoot)
      : null;
    const nonce = getNonce();
    const cspSource = this.view.webview.cspSource;
    this.view.webview.html = getHtml(codiconCssUri.toString(), data, summary, advancedMetrics, this.runningWorkflowId, nonce, cspSource);
  }
}

// ---------------------------------------------------------------------------
// Module state
// ---------------------------------------------------------------------------

let viewProvider: ContextViewProvider | undefined;
let manifestWatcher: vscode.FileSystemWatcher | undefined;
let baselineWatcher: vscode.FileSystemWatcher | undefined;
let artifactsWatcher: vscode.FileSystemWatcher | undefined;
let pipelineManifestWatcher: vscode.FileSystemWatcher | undefined;
let debounceTimer: ReturnType<typeof setTimeout> | undefined;

// ---------------------------------------------------------------------------
// Public API
// ---------------------------------------------------------------------------

export function register(context: vscode.ExtensionContext): void {
  const workspaceFolder = vscode.workspace.workspaceFolders?.[0];
  if (!workspaceFolder) return;

  viewProvider = new ContextViewProvider(context.extensionUri, workspaceFolder.uri.fsPath);

  context.subscriptions.push(
    vscode.window.registerWebviewViewProvider(
      "alucify.context",
      viewProvider,
    ),
  );

  // Set context key eagerly so panel visibility is correct before webview opens
  viewProvider.refresh();

  // File system watchers with debounced refresh
  const debouncedRefresh = (): void => {
    if (debounceTimer) clearTimeout(debounceTimer);
    debounceTimer = setTimeout(() => viewProvider?.refresh(), 500);
  };

  manifestWatcher = vscode.workspace.createFileSystemWatcher(
    new vscode.RelativePattern(workspaceFolder, ".alucify/versions/manifest.json"),
  );
  manifestWatcher.onDidCreate(debouncedRefresh);
  manifestWatcher.onDidChange(debouncedRefresh);
  manifestWatcher.onDidDelete(debouncedRefresh);
  context.subscriptions.push(manifestWatcher);

  baselineWatcher = vscode.workspace.createFileSystemWatcher(
    new vscode.RelativePattern(workspaceFolder, ".alucify/appgraph-baseline.json"),
  );
  baselineWatcher.onDidCreate(debouncedRefresh);
  baselineWatcher.onDidChange(debouncedRefresh);
  baselineWatcher.onDidDelete(debouncedRefresh);
  context.subscriptions.push(baselineWatcher);

  // Watch artifacts folder so CTA button updates when artifacts are added/changed
  artifactsWatcher = vscode.workspace.createFileSystemWatcher(
    new vscode.RelativePattern(workspaceFolder, ".alucify/artifacts/**/*"),
  );
  artifactsWatcher.onDidCreate(debouncedRefresh);
  artifactsWatcher.onDidChange(debouncedRefresh);
  artifactsWatcher.onDidDelete(debouncedRefresh);
  context.subscriptions.push(artifactsWatcher);

  // Watch pipeline manifest so CTA buttons update after workflows complete
  pipelineManifestWatcher = vscode.workspace.createFileSystemWatcher(
    new vscode.RelativePattern(workspaceFolder, ".alucify/artifact-manifest.json"),
  );
  pipelineManifestWatcher.onDidChange(debouncedRefresh);
  pipelineManifestWatcher.onDidCreate(debouncedRefresh);
  context.subscriptions.push(pipelineManifestWatcher);

  // Re-render when alucify.advanced setting changes so the Advanced tab appears/disappears
  context.subscriptions.push(
    vscode.workspace.onDidChangeConfiguration((e) => {
      if (e.affectsConfiguration("alucify.advanced")) {
        debouncedRefresh();
      }
    }),
  );
}

export function refresh(): void {
  viewProvider?.refresh();
}

export function setWorkflowRunning(workflowId: string | null): void {
  viewProvider?.setWorkflowRunning(workflowId);
}

export function dispose(): void {
  if (debounceTimer) clearTimeout(debounceTimer);
  manifestWatcher?.dispose();
  baselineWatcher?.dispose();
  artifactsWatcher?.dispose();
  pipelineManifestWatcher?.dispose();
  viewProvider = undefined;
  manifestWatcher = undefined;
  baselineWatcher = undefined;
  artifactsWatcher = undefined;
}

