/**
 * Context panel — WebviewView showing latest context version, AppGraph stats,
 * a primary CTA button, and a dropdown menu for all workflows.
 */

import * as vscode from "vscode";
import * as path from "node:path";
import * as fs from "node:fs/promises";
import { getNonce } from "./html-utils";
import {
  type BaselineAppGraph,
  VERSIONS_DIR,
  BASELINE_PATH,
  NODE_TYPES,
  loadLatestManifestEntry,
  loadAllManifestEntries,
  loadBaseline,
  formatDate,
  getLatestAnalysisDir,
  findImpactReport,
  findCoverageReport,
  findCongruencyReport,
  findCongruencyBatchReport,
  findQualitySynthesisReport,
  findQualitySynthesisData,
  computeGroundingDistribution,
} from "./appgraph-data.js";
import {
  ARTIFACTS_DIR,
} from "../core/mechanical/initialize-workflow.js";
import { hasSourceCode, isAdvancedMode } from "./config.js";
import { detectClaudeCli } from "./bmad-manager.js";
import { logUsage, inferReportType } from "../core/analytics/telemetry.js";

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

interface ContextData {
  versionLabel: string;
  versionDate: string;
  hasStats: boolean;
  /** Whether a baseline appgraph exists. */
  hasBaseline: boolean;
  /** Number of new or changed artifacts since last integration. */
  changedArtifactCount: number;
  /** Number of source artifacts used to build this version. */
  artifactCount: number;
  /** Blast radius 0.0-1.0 from metadata.stats.impact.blast_radius. */
  blastRadius: number;
  /** Grounding percentage 0.0-1.0 from metadata.stats.grounding.overall.grounding_pct. */
  groundingPct: number;
  /** Congruency 0.0-1.0: 1 - (nodes_affected / total_appgraph_nodes). -1 means unavailable. */
  congruencyPct: number;
  /** "greenfield" | "brownfield" from metadata.project_mode, or empty if unavailable. */
  projectMode: string;
  /** Absolute path to the latest impact analysis markdown report, if available. */
  impactReportPath: string | null;
  /** Absolute path to the latest coverage analysis markdown report, if available. */
  coverageReportPath: string | null;
  /** Absolute path to the latest congruency batch report, if available. */
  congruencyReportPath: string | null;
  /** Absolute path to the latest quality synthesis report, if available. */
  synthesisReportPath: string | null;
  /** Top 5 actions from prioritized_actions in the synthesis data. */
  synthesisTopActions: { action: string; tags: string[] }[];
  /** Total number of prioritized actions in the synthesis data. */
  synthesisTotalActions: number;
  /** Whether a project appgraph (not just baseline) exists. */
  hasProjectAppgraph: boolean;
  /** Whether Claude CLI is available (controls Generate Artifact button). */
  hasClaudeCli: boolean;
  /** Whether the workspace has any artifact files (used in empty-state CTA). */
  hasAnyArtifacts: boolean;
  /** Whether the workspace contains source code files (used in empty-state CTA). */
  hasCode: boolean;
  /** Number of artifacts that don't have fresh mini-AppGraphs (need analysis). */
  unanalyzedArtifactCount: number;
  /** Per-metric history arrays for sparklines (one value per version, chronological). */
  metricHistory: {
    artifacts: number[];
    blastRadius: number[];
    groundingPct: number[];
    congruencyPct: number[];
  };
}

// Summary data types (for tabbed visuals)

interface ImpactData {
  hasStats: boolean;
  isVersioned: boolean;
  totalNodes: number;
  totalEdges: number;
  newNodes: number;
  newEdges: number;
  modifiedNodes: number;
  modifiedEdges: number;
  blastRadius: number;
  reportPath: string | null;
}

interface CoverageRow {
  nodeType: string;
  label: string;
  groundingPct: number;
}

interface CompletenessData {
  total_requirements: number;
  total_designs: number;
  total_validations: number;
  reqs_missing_validations: number;
  reqs_missing_designs: number;
  designs_missing_reqs: number;
  validations_missing_reqs: number;
  designs_missing_validations: number;
  validations_missing_designs: number;
  [key: string]: number;
}

interface CoverageData {
  hasData: boolean;
  rows: CoverageRow[];
  completeness: CompletenessData | null;
  reportPath: string | null;
}

interface CongruencyCell {
  artifactName: string;
  totalNodes: number;
  congruencyPct: number;
}

interface CongruencyData {
  hasData: boolean;
  cells: CongruencyCell[];
  batchReportPath: string | null;
}

interface SummaryData {
  impact: ImpactData;
  coverage: CoverageData;
  congruency: CongruencyData;
}

// Advanced Metrics types

interface AdvCongruencyRow {
  artifactName: string;
  congruencyPct: number;
  totalIssues: number;
  critical: number;
  major: number;
  minor: number;
  reportPath: string | null;
}

interface AdvCongruencyData {
  hasData: boolean;
  rows: AdvCongruencyRow[];
  batchReportPath: string | null;
}

interface AdvCoverageData {
  hasData: boolean;
  isVersioned: boolean;
  groundingDistribution: Record<string, Record<string, number>>;
  completeness: CompletenessData | null;
  reportPath: string | null;
}

interface VersionHistoryRow {
  version: string;
  artifactCount: number;
  nodeCount: number;
  edgeCount: number;
  blastRadiusPct: number | null;
  coveragePct: number | null;
  congruencyPct: number | null;
  completenessPct: number | null;
}

interface AdvancedMetricsData {
  impact: ImpactData;
  coverage: AdvCoverageData;
  congruency: AdvCongruencyData;
  versionHistory: VersionHistoryRow[];
}

// ---------------------------------------------------------------------------
// Data loading
// ---------------------------------------------------------------------------

async function loadContextData(workspaceRoot: string): Promise<ContextData> {
  const hasBaseline = await checkBaselineExists(workspaceRoot);
  const { changedArtifactCount, unanalyzedArtifactCount } =
    await countArtifactStatesFromManifest(workspaceRoot);

  // Build metric history from all manifest versions
  const allEntries = await loadAllManifestEntries(workspaceRoot);
  const metricHistory = buildMetricHistory(allEntries);

  const entry = await loadLatestManifestEntry(workspaceRoot);
  if (entry) {
    let artifactCount = entry.artifact_count ?? 0;
    let blastRadius = 0;
    let groundingPct = 0;
    let congruencyPct = -1;
    let projectMode = "";

    try {
      const appgraphPath = path.join(workspaceRoot, VERSIONS_DIR, entry.path);
      const raw = await fs.readFile(appgraphPath, "utf-8");
      const ag = JSON.parse(raw) as Record<string, unknown>;
      const meta = ag.metadata as Record<string, unknown> | undefined;
      if (meta) {
        if (typeof meta.project_mode === "string") {
          projectMode = meta.project_mode;
        }
        const refs = meta.artifact_references;
        if (Array.isArray(refs)) artifactCount = refs.length;

        const stats = meta.stats as Record<string, unknown> | undefined;
        if (stats) {
          const impact = stats.impact as Record<string, unknown> | undefined;
          if (impact && typeof impact.blast_radius === "number") {
            blastRadius = impact.blast_radius;
          }
          const grounding = stats.grounding as Record<string, Record<string, unknown>> | undefined;
          if (grounding?.overall && typeof grounding.overall.grounding_pct === "number") {
            groundingPct = grounding.overall.grounding_pct;
          }
          const congruency = stats.congruency as Record<string, unknown> | undefined;
          if (congruency) {
            if (typeof congruency.congruency_score === "number") {
              // Use severity-weighted score (stored as 0-100, convert to 0-1 ratio)
              congruencyPct = Math.round(congruency.congruency_score * 100) / 10000;
            } else if (typeof congruency.total_nodes_affected === "number") {
              // Fallback: unweighted node-affected ratio
              const totalNodes = entry.node_count;
              congruencyPct = totalNodes > 0
                ? Math.round((1 - congruency.total_nodes_affected / totalNodes) * 10000) / 10000
                : -1;
            }
          }
        }
      }
    } catch {
      // Appgraph file not found — use manifest totals
    }

    const analysisDir = await getLatestAnalysisDir(workspaceRoot);
    const impactReportPath = analysisDir ? await findImpactReport(analysisDir) : null;
    const coverageReportPath = analysisDir ? await findCoverageReport(analysisDir) : null;
    const congruencyReportPath = analysisDir ? await findCongruencyBatchReport(analysisDir) : null;
    const synthesisReportPath = analysisDir ? await findQualitySynthesisReport(analysisDir) : null;
    const { topActions: synthesisTopActions, totalActions: synthesisTotalActions } =
      analysisDir ? await loadSynthesisActions(analysisDir) : { topActions: [], totalActions: 0 };

    return {
      versionLabel: entry.version,
      versionDate: entry.created_at ? formatDate(entry.created_at) : "",
      hasStats: true,
      hasBaseline,
      changedArtifactCount,
      hasProjectAppgraph: true,
      hasClaudeCli: detectClaudeCli(),
      hasAnyArtifacts: false,
      hasCode: false,
      artifactCount,
      blastRadius,
      groundingPct,
      congruencyPct,
      projectMode,
      impactReportPath,
      coverageReportPath,
      congruencyReportPath,
      synthesisReportPath,
      synthesisTopActions,
      synthesisTotalActions,
      unanalyzedArtifactCount,
      metricHistory,
    };
  }

  const baseline = await loadBaseline(workspaceRoot);
  if (baseline) {
    // Extract version and date from the baseline JSON and manifest
    const baselineRaw = baseline as unknown as Record<string, unknown>;
    const generatedAt = typeof baselineRaw.generated_at === "string" ? baselineRaw.generated_at : "";
    let baselineVersion = "Baseline";
    try {
      const manifestRaw = await fs.readFile(
        path.join(workspaceRoot, ".alucify/baseline/manifest.json"),
        "utf-8",
      );
      const manifest = JSON.parse(manifestRaw);
      if (manifest.current_version) {
        baselineVersion = `Baseline ${manifest.current_version}`;
      }
    } catch {
      // No manifest — use default label
    }

    const artifactsDir = path.join(workspaceRoot, ARTIFACTS_DIR);
    const hasAnyArtifacts = (await countArtifactFiles(artifactsDir)) > 0;

    return {
      versionLabel: baselineVersion,
      versionDate: generatedAt ? formatDate(generatedAt) : "",
      hasStats: true,
      hasBaseline,
      changedArtifactCount,
      hasProjectAppgraph: false,
      hasClaudeCli: detectClaudeCli(),
      hasAnyArtifacts,
      hasCode: false,
      artifactCount: 0,
      blastRadius: 0,
      groundingPct: 0,
      congruencyPct: -1,
      projectMode: "",
      impactReportPath: null,
      coverageReportPath: null,
      congruencyReportPath: null,
      synthesisReportPath: null,
      synthesisTopActions: [],
      synthesisTotalActions: 0,
      unanalyzedArtifactCount,
      metricHistory,
    };
  }

  const artifactsDir = path.join(workspaceRoot, ARTIFACTS_DIR);
  const hasAnyArtifacts = (await countArtifactFiles(artifactsDir)) > 0;
  const hasCode = await hasSourceCode();

  return {
    versionLabel: "",
    versionDate: "",
    hasStats: false,
    hasBaseline,
    changedArtifactCount,
    hasProjectAppgraph: false,
    hasClaudeCli: detectClaudeCli(),
    hasAnyArtifacts,
    hasCode,
    artifactCount: 0,
    blastRadius: 0,
    groundingPct: 0,
    congruencyPct: -1,
    projectMode: "",
    impactReportPath: null,
    coverageReportPath: null,
    congruencyReportPath: null,
    synthesisReportPath: null,
    synthesisTopActions: [],
    synthesisTotalActions: 0,
    unanalyzedArtifactCount,
    metricHistory,
  };
}

async function checkBaselineExists(workspaceRoot: string): Promise<boolean> {
  try {
    await fs.access(path.join(workspaceRoot, BASELINE_PATH));
    return true;
  } catch {
    return false;
  }
}

/** Count real (non-hidden) files in the artifacts directory. */
async function countArtifactFiles(artifactsDir: string): Promise<number> {
  try {
    const entries = await fs.readdir(artifactsDir, { recursive: true, withFileTypes: true });
    return entries.filter((e) => e.isFile() && !e.name.startsWith(".")).length;
  } catch {
    return 0;
  }
}

/**
 * Count artifact states for the Context Overview.
 *
 * - unanalyzedArtifactCount: from pipeline manifest (extraction/analysis status)
 * - changedArtifactCount: from file comparison against last version (added + modified).
 *   This uses the same logic as the integration flow's detectFileChanges, so the
 *   number shown matches what the user sees in the integration checkpoint prompt.
 */
async function countArtifactStatesFromManifest(
  workspaceRoot: string,
): Promise<{ unanalyzedArtifactCount: number; changedArtifactCount: number }> {
  let unanalyzed = 0;

  // Count unanalyzed from pipeline manifest
  try {
    const { loadManifest, refreshContentHashes, computeStaleness, saveManifest } =
      await import("../core/mechanical/artifact-pipeline-manifest.js");
    const manifest = await loadManifest(workspaceRoot);
    const { manifest: updated, changed: hashesChanged } = await refreshContentHashes(workspaceRoot, manifest);
    computeStaleness(updated);
    if (hashesChanged.length > 0) {
      await saveManifest(workspaceRoot, updated);
    }

    const { isImageArtifact } = await import("../core/mechanical/scan-artifacts.js");
    for (const entry of Object.values(updated.artifacts)) {
      const isImage = isImageArtifact(entry.relative_path);
      if (isImage) {
        if (entry.extraction.status !== "done") unanalyzed++;
      } else {
        if (entry.extraction.status !== "done" || entry.analysis.status !== "done") unanalyzed++;
      }
    }
  } catch {
    // Pipeline manifest not available — leave unanalyzed at 0
  }

  // Count changed artifacts by comparing current files against last version's manifest.
  // This matches the integration flow's detectFileChanges logic exactly.
  let changed = 0;
  try {
    const { ARTIFACTS_DIR } = await import("../core/mechanical/initialize-workflow.js");
    const { detectFileChanges } = await import("../core/mechanical/detect-file-changes.js");
    const latestEntry = await loadLatestManifestEntry(workspaceRoot);
    if (latestEntry) {
      const prevVersion = latestEntry.version;
      const prevManifestPath = path.join(
        workspaceRoot, VERSIONS_DIR, prevVersion, "working", "artifact-manifest.json",
      );
      const artifactsDir = path.join(workspaceRoot, ARTIFACTS_DIR);
      try {
        const result = await detectFileChanges(artifactsDir, prevManifestPath);
        changed = result.summary.added + result.summary.modified;
      } catch {
        // Previous manifest not readable — can't determine changes
      }
    }
  } catch {
    // No versions exist yet — all artifacts are new; count from pipeline manifest
    try {
      const { loadManifest } = await import("../core/mechanical/artifact-pipeline-manifest.js");
      const manifest = await loadManifest(workspaceRoot);
      changed = Object.keys(manifest.artifacts).length;
    } catch {
      // No manifest either
    }
  }

  return { unanalyzedArtifactCount: unanalyzed, changedArtifactCount: changed };
}

function buildMetricHistory(entries: import("./appgraph-data.js").ManifestVersionEntry[]): ContextData["metricHistory"] {
  const artifacts: number[] = [];
  const blastRadius: number[] = [];
  const groundingPct: number[] = [];
  const congruencyPct: number[] = [];

  for (const e of entries) {
    artifacts.push(e.artifact_count ?? 0);

    const impact = e.impact as Record<string, unknown> | undefined;
    if (impact && typeof impact.blast_radius === "number") {
      blastRadius.push(impact.blast_radius);
    }

    const gd = e.grounding_distribution as Record<string, Record<string, unknown>> | undefined;
    if (gd?.overall && typeof gd.overall.grounding_pct === "number") {
      groundingPct.push(gd.overall.grounding_pct);
    }

    const cong = e.congruency as Record<string, unknown> | undefined;
    if (cong) {
      if (typeof cong.congruency_score === "number") {
        congruencyPct.push(cong.congruency_score / 100);
      } else if (typeof cong.total_nodes_affected === "number" && e.node_count > 0) {
        congruencyPct.push(1 - cong.total_nodes_affected / e.node_count);
      }
    }
  }

  return { artifacts, blastRadius, groundingPct, congruencyPct };
}

function renderSparkline(values: number[]): string {
  if (values.length < 2) return "";

  const w = 40;
  const h = 16;
  const min = Math.min(...values);
  const max = Math.max(...values);
  const range = max - min;

  const points = values
    .map((v, i) => {
      const x = (i / (values.length - 1)) * w;
      const y = range > 0 ? h - ((v - min) / range) * h : h / 2;
      return `${x.toFixed(1)},${y.toFixed(1)}`;
    })
    .join(" ");

  return `<svg class="sparkline" width="${w}" height="${h}" viewBox="0 0 ${w} ${h}"><polyline points="${points}" fill="none" stroke="var(--vscode-descriptionForeground)" stroke-width="1.5" stroke-opacity="0.5" stroke-linecap="round" stroke-linejoin="round"/></svg>`;
}

async function loadSynthesisActions(
  analysisDir: string,
): Promise<{ topActions: { action: string; tags: string[] }[]; totalActions: number }> {
  const dataPath = await findQualitySynthesisData(analysisDir);
  if (!dataPath) return { topActions: [], totalActions: 0 };

  try {
    const raw = await fs.readFile(dataPath, "utf-8");
    const data = JSON.parse(raw) as Record<string, unknown>;
    const actions = (data.prioritized_actions as Array<Record<string, unknown>>) ?? [];
    if (actions.length === 0) return { topActions: [], totalActions: 0 };

    const topActions = actions
      .slice(0, 5)
      .map((a) => ({
        action: ((a.action as string) ?? ""),
        tags: (Array.isArray(a.tags) ? a.tags as string[] : []),
      }))
      .filter((a) => a.action.length > 0);

    return { topActions, totalActions: actions.length };
  } catch {
    return { topActions: [], totalActions: 0 };
  }
}

// ---------------------------------------------------------------------------
// Summary data loading (for tabbed visuals)
// ---------------------------------------------------------------------------

const NODE_TYPE_LABELS: Record<string, string> = {
  schema: "Schema",
  interface: "Interface",
  logic: "Logic",
  validation: "Validation",
};

async function loadSummaryData(workspaceRoot: string): Promise<SummaryData> {
  const entry = await loadLatestManifestEntry(workspaceRoot);

  let impact: ImpactData = {
    hasStats: false, isVersioned: false,
    totalNodes: 0, totalEdges: 0,
    newNodes: 0, newEdges: 0,
    modifiedNodes: 0, modifiedEdges: 0,
    blastRadius: 0, reportPath: null,
  };

  let coverage: CoverageData = { hasData: false, rows: [], completeness: null, reportPath: null };
  let congruency: CongruencyData = { hasData: false, cells: [], batchReportPath: null };

  if (entry) {
    let ag: BaselineAppGraph | null = null;
    try {
      const appgraphPath = path.join(workspaceRoot, VERSIONS_DIR, entry.path);
      const raw = await fs.readFile(appgraphPath, "utf-8");
      ag = JSON.parse(raw) as BaselineAppGraph;
    } catch {
      // Appgraph file not found
    }

    // Impact
    {
      let newNodes = 0, newEdges = 0, modifiedNodes = 0, modifiedEdges = 0;
      let isVersioned = false;
      let blastRadius = 0;

      if (ag) {
        const allNodes = [
          ...(ag.nodes ?? []),
          ...(ag.requirement_nodes ?? []),
          ...(ag.validation_nodes ?? []),
        ];
        const edges = ag.edges ?? [];

        for (const n of allNodes) {
          if (n.impact_status === "new") newNodes++;
          else if (n.impact_status === "modified") modifiedNodes++;
        }
        for (const e of edges) {
          if (e.impact_status === "new") newEdges++;
          else if (e.impact_status === "modified") modifiedEdges++;
        }
        if (newNodes > 0 || modifiedNodes > 0) isVersioned = true;

        const meta = (ag as Record<string, unknown>).metadata as Record<string, unknown> | undefined;
        const stats = meta?.stats as Record<string, unknown> | undefined;
        const impactStats = stats?.impact as Record<string, unknown> | undefined;
        if (impactStats && typeof impactStats.blast_radius === "number") {
          blastRadius = impactStats.blast_radius;
        }
      }

      const analysisDir = await getLatestAnalysisDir(workspaceRoot);
      const reportPath = analysisDir ? await findImpactReport(analysisDir) : null;

      impact = {
        hasStats: true, isVersioned,
        totalNodes: entry.node_count, totalEdges: entry.edge_count,
        newNodes, newEdges, modifiedNodes, modifiedEdges,
        blastRadius, reportPath,
      };
    }

    // Coverage
    {
      let grounding = entry.grounding_distribution ?? {};
      let completeness: CompletenessData | null = null;

      const allNodes = ag ? [
        ...(ag.nodes ?? []),
        ...(ag.requirement_nodes ?? []),
        ...(ag.validation_nodes ?? []),
      ] : [];

      if (ag && Object.keys(grounding).length === 0) {
        grounding = computeGroundingDistribution(allNodes);
      }

      if (ag) {
        const meta = (ag as Record<string, unknown>).metadata as Record<string, unknown> | undefined;
        const stats = meta?.stats as Record<string, unknown> | undefined;
        const comp = stats?.completeness as Record<string, number> | undefined;
        if (comp && typeof comp === "object") {
          const designTypes = new Set(["interface", "schema", "logic"]);
          completeness = {
            ...comp,
            total_requirements: allNodes.filter((n: Record<string, unknown>) => n.type === "requirement").length,
            total_designs: allNodes.filter((n: Record<string, unknown>) => designTypes.has(n.type as string ?? "")).length,
            total_validations: allNodes.filter((n: Record<string, unknown>) => n.type === "validation").length,
          } as CompletenessData;
        }
      }

      const groundingNodeTypes = NODE_TYPES.filter((nt) => nt !== "requirement" && nt !== "validation");
      const rows: CoverageRow[] = groundingNodeTypes.map((nt) => {
        const row = grounding[nt] ?? {};
        return {
          nodeType: nt,
          label: NODE_TYPE_LABELS[nt] ?? nt,
          groundingPct: typeof row.grounding_pct === "number" ? row.grounding_pct : 0,
        };
      });

      const analysisDir = await getLatestAnalysisDir(workspaceRoot);
      const reportPath = analysisDir ? await findCoverageReport(analysisDir) : null;

      coverage = { hasData: Object.keys(grounding).length > 0, rows, completeness, reportPath };
    }

    // Congruency
    {
      if (ag) {
        const meta = (ag as Record<string, unknown>).metadata as Record<string, unknown> | undefined;
        const stats = meta?.stats as Record<string, unknown> | undefined;
        const cong = stats?.congruency as Record<string, unknown> | undefined;
        let perArtifact: Array<Record<string, unknown>> = [];
        if (cong && Array.isArray(cong.per_artifact)) {
          perArtifact = cong.per_artifact as Array<Record<string, unknown>>;
        }

        if (perArtifact.length > 0) {
          const totalAppGraphNodes = entry.node_count;
          const cells: CongruencyCell[] = perArtifact.map((art) => {
            const storedScore = art.congruency_score;
            let pct: number;
            if (typeof storedScore === "number") {
              pct = Math.round(storedScore * 100) / 10000;
            } else {
              const nodesAffected = Number(art.nodes_affected ?? 0);
              pct = totalAppGraphNodes > 0
                ? Math.round((1 - nodesAffected / totalAppGraphNodes) * 10000) / 10000
                : -1;
            }
            return {
              artifactName: String(art.artifact_name ?? ""),
              totalNodes: totalAppGraphNodes,
              congruencyPct: pct,
            };
          });

          const analysisDir = await getLatestAnalysisDir(workspaceRoot);
          const batchReportPath = analysisDir ? await findCongruencyBatchReport(analysisDir) : null;
          congruency = { hasData: true, cells, batchReportPath };
        }
      }
    }
  } else {
    // No manifest — try baseline
    const baseline = await loadBaseline(workspaceRoot);
    if (baseline) {
      const allNodes = [
        ...(baseline.nodes ?? []),
        ...(baseline.requirement_nodes ?? []),
        ...(baseline.validation_nodes ?? []),
      ];
      const edges = baseline.edges ?? [];

      impact = {
        hasStats: true, isVersioned: false,
        totalNodes: allNodes.length, totalEdges: edges.length,
        newNodes: 0, newEdges: 0, modifiedNodes: 0, modifiedEdges: 0,
        blastRadius: 0, reportPath: null,
      };

      const grounding = computeGroundingDistribution(allNodes);
      const groundingNodeTypes = NODE_TYPES.filter((nt) => nt !== "requirement" && nt !== "validation");
      const rows: CoverageRow[] = groundingNodeTypes.map((nt) => {
        const row = grounding[nt] ?? {};
        return {
          nodeType: nt,
          label: NODE_TYPE_LABELS[nt] ?? nt,
          groundingPct: typeof row.grounding_pct === "number" ? row.grounding_pct : 0,
        };
      });

      coverage = { hasData: Object.keys(grounding).length > 0, rows, completeness: null, reportPath: null };
    }
  }

  return { impact, coverage, congruency };
}

// ---------------------------------------------------------------------------
// Advanced Metrics data loading
// ---------------------------------------------------------------------------

async function loadAdvancedMetricsData(workspaceRoot: string): Promise<AdvancedMetricsData> {
  const entry = await loadLatestManifestEntry(workspaceRoot);

  let impact: ImpactData = {
    hasStats: false, isVersioned: false,
    totalNodes: 0, totalEdges: 0, newNodes: 0, newEdges: 0, modifiedNodes: 0, modifiedEdges: 0,
    blastRadius: 0, reportPath: null,
  };
  let coverage: AdvCoverageData = {
    hasData: false, isVersioned: false, groundingDistribution: {}, completeness: null, reportPath: null,
  };
  let congruency: AdvCongruencyData = { hasData: false, rows: [], batchReportPath: null };

  if (entry) {
    let ag: BaselineAppGraph | null = null;
    try {
      const appgraphPath = path.join(workspaceRoot, VERSIONS_DIR, entry.path);
      const raw = await fs.readFile(appgraphPath, "utf-8");
      ag = JSON.parse(raw) as BaselineAppGraph;
    } catch { /* not found */ }

    // Impact
    {
      let newNodes = 0, newEdges = 0, modifiedNodes = 0, modifiedEdges = 0;
      let isVersioned = false;
      let blastRadius = 0;

      if (ag) {
        const allNodes = [...(ag.nodes ?? []), ...(ag.requirement_nodes ?? []), ...(ag.validation_nodes ?? [])];
        const edges = ag.edges ?? [];
        for (const n of allNodes) {
          if (n.impact_status === "new") newNodes++;
          else if (n.impact_status === "modified") modifiedNodes++;
        }
        for (const e of edges) {
          if (e.impact_status === "new") newEdges++;
          else if (e.impact_status === "modified") modifiedEdges++;
        }
        if (newNodes > 0 || modifiedNodes > 0) isVersioned = true;

        const meta = (ag as Record<string, unknown>).metadata as Record<string, unknown> | undefined;
        const stats = meta?.stats as Record<string, unknown> | undefined;
        const impactStats = stats?.impact as Record<string, unknown> | undefined;
        if (impactStats && typeof impactStats.blast_radius === "number") blastRadius = impactStats.blast_radius;
      }

      const analysisDir = await getLatestAnalysisDir(workspaceRoot);
      const reportPath = analysisDir ? await findImpactReport(analysisDir) : null;
      impact = { hasStats: true, isVersioned, totalNodes: entry.node_count, totalEdges: entry.edge_count, newNodes, newEdges, modifiedNodes, modifiedEdges, blastRadius, reportPath };
    }

    // Coverage
    {
      let grounding = entry.grounding_distribution ?? {};
      let completeness: CompletenessData | null = null;
      if (ag) {
        const allNodes = [...(ag.nodes ?? []), ...(ag.requirement_nodes ?? []), ...(ag.validation_nodes ?? [])];
        if (Object.keys(grounding).length === 0) grounding = computeGroundingDistribution(allNodes);

        const meta = (ag as Record<string, unknown>).metadata as Record<string, unknown> | undefined;
        const stats = meta?.stats as Record<string, unknown> | undefined;
        const comp = stats?.completeness as Record<string, number> | undefined;
        if (comp && typeof comp === "object") {
          const designTypes = new Set(["interface", "schema", "logic"]);
          completeness = {
            ...comp,
            total_requirements: allNodes.filter((n: Record<string, unknown>) => n.type === "requirement").length,
            total_designs: allNodes.filter((n: Record<string, unknown>) => designTypes.has(n.type as string ?? "")).length,
            total_validations: allNodes.filter((n: Record<string, unknown>) => n.type === "validation").length,
          } as CompletenessData;
        }
      }
      const analysisDir = await getLatestAnalysisDir(workspaceRoot);
      const reportPath = analysisDir ? await findCoverageReport(analysisDir) : null;
      coverage = { hasData: true, isVersioned: !!completeness, groundingDistribution: grounding, completeness, reportPath };
    }

    // Congruency
    {
      if (ag) {
        const meta = (ag as Record<string, unknown>).metadata as Record<string, unknown> | undefined;
        const stats = meta?.stats as Record<string, unknown> | undefined;
        const cong = stats?.congruency as Record<string, unknown> | undefined;
        let perArtifact: Array<Record<string, unknown>> = [];
        if (cong && Array.isArray(cong.per_artifact)) perArtifact = cong.per_artifact as Array<Record<string, unknown>>;

        if (perArtifact.length > 0) {
          const analysisDir = await getLatestAnalysisDir(workspaceRoot);
          const rows: AdvCongruencyRow[] = [];
          for (const art of perArtifact) {
            const artName = String(art.artifact_name ?? "");
            const totalNodes = Number(art.total_nodes ?? 0);
            const nodesAffected = Number(art.nodes_affected ?? 0);
            const bySev = art.by_severity as Record<string, number> | undefined;
            const storedScore = art.congruency_score;
            const congruencyPct = typeof storedScore === "number"
              ? Math.round(storedScore * 100) / 10000
              : totalNodes > 0 ? Math.round((1 - nodesAffected / totalNodes) * 10000) / 10000 : -1;
            const reportPath = analysisDir ? await findCongruencyReport(analysisDir, artName) : null;
            rows.push({ artifactName: artName, congruencyPct, totalIssues: Number(art.total_issues ?? 0), critical: bySev?.critical ?? 0, major: bySev?.major ?? 0, minor: bySev?.minor ?? 0, reportPath });
          }
          const batchReportPath = analysisDir ? await findCongruencyBatchReport(analysisDir) : null;
          congruency = { hasData: true, rows, batchReportPath };
        } else {
          congruency = { hasData: true, rows: [], batchReportPath: null };
        }
      }
    }
  } else {
    const baseline = await loadBaseline(workspaceRoot);
    if (baseline) {
      const allNodes = [...(baseline.nodes ?? []), ...(baseline.requirement_nodes ?? []), ...(baseline.validation_nodes ?? [])];
      impact = { hasStats: true, isVersioned: false, totalNodes: allNodes.length, totalEdges: (baseline.edges ?? []).length, newNodes: 0, newEdges: 0, modifiedNodes: 0, modifiedEdges: 0, blastRadius: 0, reportPath: null };
      coverage = { hasData: true, isVersioned: false, groundingDistribution: computeGroundingDistribution(allNodes), completeness: null, reportPath: null };
    }
  }

  // Version History
  const allEntries = await loadAllManifestEntries(workspaceRoot);
  const versionHistory: VersionHistoryRow[] = allEntries.map((e) => {
    const imp = e.impact as Record<string, unknown> | undefined;
    const blastRadiusPct = imp && typeof imp.blast_radius === "number" ? Math.round(imp.blast_radius * 10000) / 100 : null;
    const gd = e.grounding_distribution as Record<string, Record<string, unknown>> | undefined;
    const coveragePct = gd?.overall && typeof gd.overall.grounding_pct === "number" ? Math.round((gd.overall.grounding_pct as number) * 10000) / 100 : null;
    const cong = e.congruency as Record<string, unknown> | undefined;
    let congPct: number | null = null;
    if (cong && typeof cong.congruency_score === "number") congPct = Math.round((cong.congruency_score as number) * 100) / 100;
    const comp = e.completeness as Record<string, number> | undefined;
    const completenessPct = comp && typeof comp.completeness_score === "number" ? Math.round(comp.completeness_score * 10) / 10 : null;
    return { version: e.version, artifactCount: e.artifact_count ?? 0, nodeCount: e.node_count ?? 0, edgeCount: e.edge_count ?? 0, blastRadiusPct, coveragePct, congruencyPct: congPct, completenessPct };
  });

  return { impact, coverage, congruency, versionHistory };
}

// ---------------------------------------------------------------------------
// Advanced Metrics render function
// ---------------------------------------------------------------------------

function renderAdvancedMetricsContent(data: AdvancedMetricsData): string {
  // Version History table
  let versionHistoryHtml = "";
  if (data.versionHistory.length > 0) {
    const fmtPct = (v: number | null): string => v !== null ? `${v}%` : "\u2014";
    const versionCols = data.versionHistory.map((v) => `<th>${escapeHtmlStr(v.version)}</th>`).join("");
    const artifactRow = data.versionHistory.map((v) => `<td>${v.artifactCount}</td>`).join("");
    const nodesRow = data.versionHistory.map((v) => `<td>${v.nodeCount}</td>`).join("");
    const edgesRow = data.versionHistory.map((v) => `<td>${v.edgeCount}</td>`).join("");
    const blastRow = data.versionHistory.map((v) => `<td>${fmtPct(v.blastRadiusPct)}</td>`).join("");
    const coverageRow = data.versionHistory.map((v) => `<td>${fmtPct(v.coveragePct)}</td>`).join("");
    const congruencyRow = data.versionHistory.map((v) => `<td>${fmtPct(v.congruencyPct)}</td>`).join("");
    const completenessRow = data.versionHistory.map((v) => `<td>${fmtPct(v.completenessPct)}</td>`).join("");

    versionHistoryHtml = `
      <div class="adv-section-header">Version History</div>
      <div class="version-table-wrapper">
        <table class="data-table">
          <thead><tr><th></th>${versionCols}</tr></thead>
          <tbody>
            <tr><th class="row-header">Artifacts</th>${artifactRow}</tr>
            <tr><th class="row-header">Nodes</th>${nodesRow}</tr>
            <tr><th class="row-header">Edges</th>${edgesRow}</tr>
            <tr><th class="row-header">Blast Radius</th>${blastRow}</tr>
            <tr><th class="row-header">Coverage</th>${coverageRow}</tr>
            <tr><th class="row-header">Congruency</th>${congruencyRow}</tr>
            <tr><th class="row-header">Completeness</th>${completenessRow}</tr>
          </tbody>
        </table>
      </div>`;
  }

  // Impact table
  let impactHtml = "";
  if (data.impact.hasStats) {
    const d = data.impact;
    const unchangedNodes = d.totalNodes - d.newNodes - d.modifiedNodes;
    const unchangedEdges = d.totalEdges - d.newEdges - d.modifiedEdges;
    const pct = (n: number, total: number) => total > 0 ? `${Math.round((n / total) * 100)}%` : "0%";
    const impactViewDetails = d.reportPath
      ? ` <a class="view-details-link" data-report-path="${escapeAttr(d.reportPath)}">View Details</a>` : "";
    if (d.isVersioned) {
      const rows = [
        { label: "New", nodes: pct(d.newNodes, d.totalNodes), edges: pct(d.newEdges, d.totalEdges) },
        { label: "Modified", nodes: pct(d.modifiedNodes, d.totalNodes), edges: pct(d.modifiedEdges, d.totalEdges) },
        { label: "Unchanged", nodes: pct(unchangedNodes, d.totalNodes), edges: pct(unchangedEdges, d.totalEdges) },
      ];
      const tableRows = rows.map((r) => `<tr><th class="row-header">${r.label}</th><td>${r.nodes}</td><td>${r.edges}</td></tr>`).join("");
      impactHtml = `
        <div class="adv-section-header"><span>Impact</span>${impactViewDetails}</div>
        <table class="data-table">
          <thead><tr><th></th><th>Nodes (${d.totalNodes})</th><th>Edges (${d.totalEdges})</th></tr></thead>
          <tbody>${tableRows}</tbody>
        </table>`;
    } else {
      impactHtml = `
        <div class="adv-section-header"><span>Impact</span>${impactViewDetails}</div>
        <table class="data-table">
          <thead><tr><th></th><th>Nodes</th><th>Edges</th></tr></thead>
          <tbody><tr><th class="row-header">Total</th><td>${d.totalNodes}</td><td>${d.totalEdges}</td></tr></tbody>
        </table>`;
    }
  } else {
    impactHtml = `<div class="adv-section-header">Impact</div><div class="muted">No data available</div>`;
  }

  // Coverage table
  let coverageHtml = "";
  if (data.coverage.hasData) {
    const nodeTypes = [...NODE_TYPES];
    const ntLabels: Record<string, string> = { requirement: "Requirement", schema: "Schema", interface: "Interface", logic: "Logic", validation: "Validation" };
    const authCols = [
      { key: "total", label: "Total" }, { key: "prototyped", label: "Prototyped" },
      { key: "specified", label: "Specified" }, { key: "described", label: "Described" },
      { key: "referenced", label: "Referenced" }, { key: "as-built", label: "As-Built" },
    ];
    const hasGrounding = Object.keys(data.coverage.groundingDistribution).length > 0;
    let groundingTableHtml = "";
    if (hasGrounding) {
      const fmtPct = (v: number | undefined): string => v != null && v > 0 ? `${Math.round(v * 100)}%` : "\u2014";
      const headerCells = nodeTypes.map((nt) => `<th>${ntLabels[nt]}</th>`).join("");
      const pctRow = `<tr><th class="row-header">%</th>${nodeTypes.map((nt) => {
        const row = data.coverage.groundingDistribution[nt] ?? {};
        return `<td class="pct-cell">${fmtPct(row.grounding_pct)}</td>`;
      }).join("")}</tr>`;
      const authRows = authCols.map((c) => {
        const cells = nodeTypes.map((nt) => {
          const row = data.coverage.groundingDistribution[nt] ?? {};
          return `<td>${row[c.key] ?? 0}</td>`;
        }).join("");
        return `<tr><th class="row-header">${c.label}</th>${cells}</tr>`;
      }).join("");
      groundingTableHtml = `<table class="data-table"><thead><tr><th></th>${headerCells}</tr></thead><tbody>${pctRow}${authRows}</tbody></table>`;
    }
    const covViewDetails = data.coverage.reportPath
      ? ` <a class="view-details-link" data-report-path="${escapeAttr(data.coverage.reportPath)}">View Details</a>` : "";
    coverageHtml = hasGrounding
      ? `<div class="adv-section-header"><span>Coverage</span>${covViewDetails}</div>${groundingTableHtml}`
      : `<div class="adv-section-header"><span>Coverage</span>${covViewDetails}</div><div class="muted">No coverage data available</div>`;
  } else {
    coverageHtml = `<div class="adv-section-header">Coverage</div><div class="muted">No context generated</div>`;
  }

  // Congruency table
  const congViewDetails = data.congruency.batchReportPath
    ? ` <a class="view-details-link" data-report-path="${escapeAttr(data.congruency.batchReportPath)}">View Details</a>` : "";
  let congruencyHtml = "";
  if (!data.congruency.hasData) {
    congruencyHtml = `<div class="adv-section-header">Congruency</div><div class="muted">No context generated</div>`;
  } else if (data.congruency.rows.length === 0) {
    congruencyHtml = `<div class="adv-section-header"><span>Congruency</span>${congViewDetails}</div><div class="muted">No congruency analysis available</div>`;
  } else {
    const fmtPct = (v: number): string => v >= 0 ? `${Math.round(v * 100)}%` : "\u2014";
    const tableRows = data.congruency.rows.map((r) => {
      const clickable = r.reportPath ? "clickable" : "";
      const dataAttr = r.reportPath ? ` data-report-path="${escapeAttr(r.reportPath)}"` : "";
      return `<tr class="${clickable}"${dataAttr}><td class="row-header">${escapeHtmlStr(r.artifactName)}</td><td>${fmtPct(r.congruencyPct)}</td><td>${r.totalIssues}</td><td>${r.critical}</td><td>${r.major}</td><td>${r.minor}</td></tr>`;
    }).join("");
    congruencyHtml = `
      <div class="adv-section-header"><span>Congruency</span>${congViewDetails}</div>
      <table class="data-table"><thead><tr><th>Artifact</th><th>%</th><th>Issues</th><th>Crit</th><th>Major</th><th>Minor</th></tr></thead><tbody>${tableRows}</tbody></table>`;
  }

  // Completeness table + butterfly
  let completenessHtml = "";
  if (data.coverage.hasData && data.coverage.completeness) {
    const c = data.coverage.completeness;
    const totalReqs = c.total_requirements ?? 0;
    const totalDesigns = c.total_designs ?? 0;
    const totalVals = c.total_validations ?? 0;

    const fmtRow = (missing: number, total: number) => {
      const pctVal = total > 0 ? `${Math.round((missing / total) * 100)}%` : "\u2014";
      return { pctVal, count: `${missing}/${total}` };
    };
    const tableData = [
      { label: "Reqs without Designs", ...fmtRow(c.reqs_missing_designs ?? 0, totalReqs) },
      { label: "Designs without Reqs", ...fmtRow(c.designs_missing_reqs ?? 0, totalDesigns) },
      { label: "Reqs without Tests", ...fmtRow(c.reqs_missing_validations ?? 0, totalReqs) },
      { label: "Tests without Reqs", ...fmtRow(c.validations_missing_reqs ?? 0, totalVals) },
      { label: "Designs without Tests", ...fmtRow(c.designs_missing_validations ?? 0, totalDesigns) },
      { label: "Tests without Designs", ...fmtRow(c.validations_missing_designs ?? 0, totalVals) },
    ];
    const completenessTableRows = tableData.map((r) =>
      `<tr><td class="completeness-label">${r.label}</td><td class="completeness-count">${r.count}</td><td class="completeness-value">${r.pctVal}</td></tr>`
    ).join("");

    completenessHtml = `
      <div class="adv-section-header">Completeness</div>
      <table class="completeness-table"><tbody>${completenessTableRows}</tbody></table>`;

    // Butterfly chart
    const pct = (missing: number, total: number) => total > 0 ? Math.round(((total - missing) / total) * 100) : 100;
    const reqToVal = pct(c.reqs_missing_validations ?? 0, totalReqs);
    const valToReq = pct(c.validations_missing_reqs ?? 0, totalVals);
    const reqToDes = pct(c.reqs_missing_designs ?? 0, totalReqs);
    const desToReq = pct(c.designs_missing_reqs ?? 0, totalDesigns);
    const desToVal = pct(c.designs_missing_validations ?? 0, totalDesigns);
    const valToDes = pct(c.validations_missing_designs ?? 0, totalVals);

    const hc = (v: number) =>
      v >= 80 ? "var(--vscode-charts-green, #89d185)"
      : v >= 50 ? "var(--vscode-charts-yellow, #cca700)"
      : "var(--vscode-charts-red, #f48771)";

    const bfMaxW = 90;
    const bfBar = (v: number) => Math.max((v / 100) * bfMaxW, 2);
    const pairs = [
      { left: reqToVal, leftLabel: "R\u2192V", right: valToReq, rightLabel: "V\u2192R" },
      { left: reqToDes, leftLabel: "R\u2192D", right: desToReq, rightLabel: "D\u2192R" },
      { left: desToVal, leftLabel: "D\u2192V", right: valToDes, rightLabel: "V\u2192D" },
    ];
    const rowH = 28;
    const bfH = pairs.length * rowH + 20;
    const bfCx = 140;
    const bfLabelL = 48;
    const bfLabelR = 232;

    let butterflyRows = "";
    pairs.forEach((p, i) => {
      const y = 16 + i * rowH;
      const barY = y + 2;
      const barH = 14;
      const lw = bfBar(p.left);
      const rw = bfBar(p.right);
      butterflyRows += `
        <text x="${bfLabelL}" y="${y + 13}" text-anchor="end" font-size="8" fill="${hc(p.left)}">${p.leftLabel} ${p.left}%</text>
        <rect x="${bfCx - 2 - lw}" y="${barY}" width="${lw}" height="${barH}" rx="2" fill="${hc(p.left)}" opacity="0.7"/>
        <rect x="${bfCx + 2}" y="${barY}" width="${rw}" height="${barH}" rx="2" fill="${hc(p.right)}" opacity="0.7"/>
        <text x="${bfLabelR}" y="${y + 13}" text-anchor="start" font-size="8" fill="${hc(p.right)}">${p.right}% ${p.rightLabel}</text>`;
    });

    completenessHtml += `
      <div class="adv-section-header">Completeness \u2014 Butterfly</div>
      <svg viewBox="0 0 280 ${bfH}" width="100%" style="display:block;margin:4px 0 8px;">
        <line x1="${bfCx}" y1="8" x2="${bfCx}" y2="${bfH - 4}" stroke="var(--vscode-panel-border, rgba(128,128,128,0.25))" stroke-width="1" stroke-dasharray="2,2"/>
        ${butterflyRows}
      </svg>`;
  }

  const sep = '<hr class="adv-separator" />';
  return `${versionHistoryHtml}${versionHistoryHtml ? sep : ""}${impactHtml}${sep}${coverageHtml}${sep}${congruencyHtml}${sep}${completenessHtml}`;
}

// ---------------------------------------------------------------------------
// Visual render functions (for tabbed section)
// ---------------------------------------------------------------------------

function escapeAttr(s: string): string {
  return s.replace(/&/g, "&amp;").replace(/"/g, "&quot;");
}

function escapeHtmlStr(s: string): string {
  return s.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
}

function renderPieChart(d: ImpactData): string {
  const newTotal = d.newNodes + d.newEdges;
  const modTotal = d.modifiedNodes + d.modifiedEdges;
  const total = d.totalNodes + d.totalEdges;
  const intactTotal = total - newTotal - modTotal;

  if (total === 0) return `<div class="muted">No nodes or edges</div>`;

  const r = 40;
  const cx = 50;
  const cy = 50;
  const strokeWidth = 16;
  const circumference = 2 * Math.PI * r;

  const segments = [
    { label: "New", count: newTotal, color: "var(--vscode-charts-green, #89d185)" },
    { label: "Modified", count: modTotal, color: "var(--vscode-charts-orange, #cca700)" },
    { label: "Intact", count: intactTotal, color: "var(--vscode-charts-foreground, rgba(128,128,128,0.3))" },
  ].filter((s) => s.count > 0);

  let paths = "";
  let offset = 0;
  for (const seg of segments) {
    const pct = seg.count / total;
    const dashLen = pct * circumference;
    const dashGap = circumference - dashLen;
    paths += `<circle cx="${cx}" cy="${cy}" r="${r}" fill="none"
      stroke="${seg.color}" stroke-width="${strokeWidth}"
      stroke-dasharray="${dashLen.toFixed(2)} ${dashGap.toFixed(2)}"
      stroke-dashoffset="${(-offset).toFixed(2)}"
      transform="rotate(-90 ${cx} ${cy})" />`;
    offset += dashLen;
  }

  const legendItems = segments
    .map((s) => {
      const pct = Math.round((s.count / total) * 100);
      return `<div class="legend-item">
        <span class="legend-dot" style="background:${s.color}"></span>
        <span class="legend-label">${s.label}</span>
        <span class="legend-value">${pct}%</span>
      </div>`;
    })
    .join("");

  return `
    <div class="pie-container">
      <svg class="pie-chart" viewBox="0 0 100 100">
        ${paths}
        <text x="${cx}" y="${cy}" text-anchor="middle" dominant-baseline="central"
          fill="var(--vscode-foreground)" font-size="14" font-weight="600">${Math.round(d.blastRadius * 100)}%</text>
      </svg>
      <div class="legend">${legendItems}</div>
    </div>`;
}

function renderCoverageBars(rows: CoverageRow[]): string {
  if (rows.length === 0) return `<div class="muted">No coverage data</div>`;

  const bars = rows
    .map((r) => {
      const pct = Math.round(r.groundingPct * 100);
      return `<div class="bar-row">
        <div class="bar-label">${r.label}</div>
        <div class="bar-track">
          <div class="bar-fill" style="width:${pct}%"></div>
        </div>
        <div class="bar-value">${pct}%</div>
      </div>`;
    })
    .join("");

  return `<div class="bars-container">${bars}</div>`;
}

/** Map congruency 0.0-1.0 to a red-yellow-green color. */
function congruencyColor(pct: number): string {
  if (pct < 0) return "rgba(128,128,128,0.3)";
  const t = Math.max(0, Math.min(1, (pct - 0.3) / 0.5));
  const r = t < 0.5 ? 255 : Math.round(255 * (1 - t) * 2);
  const g = t > 0.5 ? 200 : Math.round(200 * t * 2);
  return `rgb(${r}, ${g}, 60)`;
}

interface TreemapRect { x: number; y: number; w: number; h: number; }

function squarify(values: number[], container: TreemapRect): TreemapRect[] {
  const total = values.reduce((a, b) => a + b, 0);
  if (total === 0 || values.length === 0) return [];

  const rects: TreemapRect[] = new Array(values.length);
  const indices = values.map((_, i) => i).sort((a, b) => values[b] - values[a]);

  function layoutRow(row: number[], box: TreemapRect, totalVal: number): TreemapRect {
    const rowSum = row.reduce((a, i) => a + values[i], 0);
    const fraction = rowSum / totalVal;
    const horizontal = box.w >= box.h;
    let offset = 0;

    if (horizontal) {
      const rowW = box.w * fraction;
      for (const idx of row) {
        const h = box.h * (values[idx] / rowSum);
        rects[idx] = { x: box.x, y: box.y + offset, w: rowW, h };
        offset += h;
      }
      return { x: box.x + rowW, y: box.y, w: box.w - rowW, h: box.h };
    } else {
      const rowH = box.h * fraction;
      for (const idx of row) {
        const w = box.w * (values[idx] / rowSum);
        rects[idx] = { x: box.x + offset, y: box.y, w, h: rowH };
        offset += w;
      }
      return { x: box.x, y: box.y + rowH, w: box.w, h: box.h - rowH };
    }
  }

  function worstRatio(row: number[], side: number, totalVal: number): number {
    const rowSum = row.reduce((a, i) => a + values[i], 0);
    const fraction = rowSum / totalVal;
    const rowSide = side * fraction;
    if (rowSide === 0) return Infinity;
    let worst = 0;
    for (const idx of row) {
      const cellSide = (side * (values[idx] / rowSum));
      const r = Math.max(cellSide / rowSide, rowSide / cellSide);
      if (r > worst) worst = r;
    }
    return worst;
  }

  let box = { ...container };
  let remaining = [...indices];
  let remTotal = total;

  while (remaining.length > 0) {
    const side = Math.min(box.w, box.h);
    const row: number[] = [remaining[0]];
    remaining = remaining.slice(1);

    let currentWorst = worstRatio(row, side, remTotal);

    while (remaining.length > 0) {
      const candidate = [...row, remaining[0]];
      const candidateWorst = worstRatio(candidate, side, remTotal);
      if (candidateWorst <= currentWorst) {
        row.push(remaining[0]);
        remaining = remaining.slice(1);
        currentWorst = candidateWorst;
      } else {
        break;
      }
    }

    box = layoutRow(row, box, remTotal);
    remTotal -= row.reduce((a, i) => a + values[i], 0);
  }

  return rects;
}

function renderCongruencyHeatmap(cells: CongruencyCell[]): string {
  if (cells.length === 0) return `<div class="muted">No congruency data</div>`;

  const values = cells.map((c) => Math.max(c.totalNodes, 1));
  const containerW = 240;
  const containerH = 140;
  const rects = squarify(values, { x: 0, y: 0, w: containerW, h: containerH });

  const divs = cells
    .map((c, i) => {
      const r = rects[i];
      if (!r) return "";
      const pct = c.congruencyPct >= 0 ? Math.round(c.congruencyPct * 100) : -1;
      const pctLabel = pct >= 0 ? `${pct}%` : "\u2014";
      const bg = congruencyColor(c.congruencyPct);
      const showPct = r.h > 24;
      const showName = r.h > 36 && r.w > 40;

      return `<div class="heatmap-cell" style="left:${r.x.toFixed(1)}px;top:${r.y.toFixed(1)}px;width:${r.w.toFixed(1)}px;height:${r.h.toFixed(1)}px;background:${bg};"
        title="${escapeHtmlStr(c.artifactName)}: ${pctLabel} congruency, ${c.totalNodes} nodes">
        ${showPct ? `<span class="heatmap-pct">${pctLabel}</span>` : ""}
        ${showName ? `<span class="heatmap-name">${escapeHtmlStr(c.artifactName)}</span>` : ""}
      </div>`;
    })
    .join("");

  return `<div class="heatmap-container" style="width:${containerW}px;height:${containerH}px;">${divs}</div>`;
}

function renderCompletenessTriangle(completeness: CompletenessData): string {
  const c = completeness;
  const totalReqs = c.total_requirements ?? 0;
  const totalDesigns = c.total_designs ?? 0;
  const totalVals = c.total_validations ?? 0;

  const pct = (missing: number, total: number) =>
    total > 0 ? Math.round(((total - missing) / total) * 100) : 100;
  const reqToVal = pct(c.reqs_missing_validations ?? 0, totalReqs);
  const valToReq = pct(c.validations_missing_reqs ?? 0, totalVals);
  const reqToDes = pct(c.reqs_missing_designs ?? 0, totalReqs);
  const desToReq = pct(c.designs_missing_reqs ?? 0, totalDesigns);
  const desToVal = pct(c.designs_missing_validations ?? 0, totalDesigns);
  const valToDes = pct(c.validations_missing_designs ?? 0, totalVals);

  const hc = (v: number) =>
    v >= 80 ? "var(--vscode-charts-green, #89d185)"
    : v >= 50 ? "var(--vscode-charts-yellow, #cca700)"
    : "var(--vscode-charts-red, #f48771)";

  const hcFill = (v: number) =>
    v >= 80 ? "rgba(137,209,133,0.6)"
    : v >= 50 ? "rgba(204,167,0,0.6)"
    : "rgba(244,135,113,0.6)";

  const arrowBar = (id: string, pctVal: number, bLen: number, hLen: number, hH: number, label: string, flipped: boolean) => {
    const headHH = hH + 4;
    const totalLen = bLen + hLen;
    const fillW = Math.max((pctVal / 100) * bLen, 1);
    const pts = `0,${-hH} ${bLen},${-hH} ${bLen},${-headHH} ${totalLen},0 ${bLen},${headHH} ${bLen},${hH} 0,${hH}`;
    const labelY = -(hH + 9);
    const labelTransform = flipped ? ` transform="rotate(180, ${bLen / 2}, ${labelY})"` : "";
    return `<polygon points="${pts}" fill="rgba(180,180,180,0.25)" stroke="rgba(128,128,128,0.3)" stroke-width="0.75"/>
      <clipPath id="${id}"><polygon points="${pts}"/></clipPath>
      <rect x="0" y="${-headHH}" width="${fillW}" height="${headHH * 2}" fill="${hcFill(pctVal)}" clip-path="url(#${id})"/>
      <text x="${bLen / 2}" y="${labelY}" text-anchor="middle" font-size="7" fill="${hc(pctVal)}"${labelTransform}>${label} ${pctVal}%</text>`;
  };

  const svgW = 300, svgH = 280;
  const dxV = 150, dyV = 38;
  const rxV = 42,  ryV = 220;
  const vxV = 258, vyV = 220;
  const barLen = 130, headLen = 12, halfH = 4;

  const leftAngle = Math.atan2(dyV - ryV, dxV - rxV) * (180 / Math.PI);
  const rightAngle = Math.atan2(vyV - dyV, vxV - dxV) * (180 / Math.PI);
  const offset = 7;

  const edgeStart = (x1: number, y1: number, x2: number, y2: number, perpOff: number, inset: number) => {
    const edx = x2 - x1, edy = y2 - y1;
    const len = Math.sqrt(edx * edx + edy * edy);
    const ux = edx / len, uy = edy / len;
    const px = -uy, py = ux;
    return { x: x1 + ux * inset + px * perpOff, y: y1 + uy * inset + py * perpOff };
  };

  const inset = 22;
  const rdStart = edgeStart(rxV, ryV, dxV, dyV, -offset, inset);
  const drStart = edgeStart(dxV, dyV, rxV, ryV, -offset, inset);
  const dvStart = edgeStart(dxV, dyV, vxV, vyV, -offset, inset);
  const vdStart = edgeStart(vxV, vyV, dxV, dyV, -offset, inset);
  const rvStart = edgeStart(rxV, ryV, vxV, vyV, -offset, inset);
  const vrStart = edgeStart(vxV, vyV, rxV, ryV, -offset, inset);

  return `
    <svg viewBox="0 0 ${svgW} ${svgH}" width="100%" style="display:block;margin:4px 0 8px;">
      <defs></defs>
      <g transform="translate(${rdStart.x.toFixed(1)}, ${rdStart.y.toFixed(1)}) rotate(${leftAngle.toFixed(1)})">
        ${arrowBar("arr-rd", reqToDes, barLen, headLen, halfH, "Mapped Reqs", false)}
      </g>
      <g transform="translate(${drStart.x.toFixed(1)}, ${drStart.y.toFixed(1)}) rotate(${(leftAngle + 180).toFixed(1)})">
        ${arrowBar("arr-dr", desToReq, barLen, headLen, halfH, "Mapped Designs", true)}
      </g>
      <g transform="translate(${dvStart.x.toFixed(1)}, ${dvStart.y.toFixed(1)}) rotate(${rightAngle.toFixed(1)})">
        ${arrowBar("arr-dv", desToVal, barLen, headLen, halfH, "Mapped Designs", false)}
      </g>
      <g transform="translate(${vdStart.x.toFixed(1)}, ${vdStart.y.toFixed(1)}) rotate(${(rightAngle + 180).toFixed(1)})">
        ${arrowBar("arr-vd", valToDes, barLen, headLen, halfH, "Mapped Tests", true)}
      </g>
      <g transform="translate(${rvStart.x.toFixed(1)}, ${rvStart.y.toFixed(1)}) rotate(0)">
        ${arrowBar("arr-rv", reqToVal, barLen, headLen, halfH, "Mapped Reqs", false)}
      </g>
      <g transform="translate(${vrStart.x.toFixed(1)}, ${vrStart.y.toFixed(1)}) rotate(180)">
        ${arrowBar("arr-vr", valToReq, barLen, headLen, halfH, "Mapped Tests", true)}
      </g>
      <text x="${dxV}" y="${dyV - 10}" text-anchor="middle" font-size="10" font-weight="600" fill="var(--vscode-foreground)">Designs</text>
      <text x="${rxV - 4}" y="${ryV + 6}" text-anchor="middle" font-size="10" font-weight="600" fill="var(--vscode-foreground)">Reqs</text>
      <text x="${vxV + 4}" y="${vyV + 6}" text-anchor="middle" font-size="10" font-weight="600" fill="var(--vscode-foreground)">Tests</text>
    </svg>`;
}

