function getHtml(
  codiconCssUri: string,
  data: ContextData,
  summary: SummaryData | null,
  advancedMetrics: AdvancedMetricsData | null,
  runningWorkflowId: string | null,
  nonce: string,
  cspSource: string,
): string {
  // --- Version info ---
  let versionHtml = "";
  if (data.versionLabel) {
    const datePart = data.versionDate
      ? `<span class="muted"> &middot; ${data.versionDate}</span>`
      : "";
    const modePart = data.projectMode
      ? `<span class="mode-tag">${data.projectMode}</span>`
      : "";
    versionHtml = `<div class="version-row">${data.versionLabel}${datePart}${modePart}</div>`;
  }

  // --- Metric cards (only shown when project appgraph exists) ---
  let metricsHtml = "";
  if (data.hasProjectAppgraph) {
    const fmt = (v: number): string => v > 0 ? `${Math.round(v * 100)}%` : "—";
    metricsHtml = `
      <div class="metric-group-label"><span>Scope</span></div>
      <div class="metrics-grid">
        <div class="metric-card">
          <div class="metric-value"><span class="metric-number">${data.artifactCount || "—"}</span><span class="metric-spark">${renderSparkline(data.metricHistory.artifacts)}</span></div>
          <div class="metric-label">${data.artifactCount === 1 ? "Artifact" : "Artifacts"}</div>
        </div>
        <div class="metric-card${data.impactReportPath ? " clickable-metric" : ""}"${data.impactReportPath ? ` data-report-path="${data.impactReportPath.replace(/&/g, "&amp;").replace(/"/g, "&quot;")}"` : ""}>
          <div class="metric-value"><span class="metric-number">${fmt(data.blastRadius)}</span><span class="metric-spark">${renderSparkline(data.metricHistory.blastRadius)}</span></div>
          <div class="metric-label">Impact</div>
        </div>
      </div>
      <div class="metric-group-label"><span>Dev Readiness</span></div>
      <div class="metrics-grid">
        <div class="metric-card${data.coverageReportPath ? " clickable-metric" : ""}"${data.coverageReportPath ? ` data-report-path="${data.coverageReportPath.replace(/&/g, "&amp;").replace(/"/g, "&quot;")}"` : ""}>
          <div class="metric-value"><span class="metric-number">${fmt(data.groundingPct)}</span><span class="metric-spark">${renderSparkline(data.metricHistory.groundingPct)}</span></div>
          <div class="metric-label">Coverage</div>
        </div>
        <div class="metric-card${data.congruencyReportPath ? " clickable-metric" : ""}"${data.congruencyReportPath ? ` data-report-path="${data.congruencyReportPath.replace(/&/g, "&amp;").replace(/"/g, "&quot;")}"` : ""}>
          <div class="metric-value"><span class="metric-number">${data.congruencyPct >= 0 ? `${Math.round(data.congruencyPct * 100)}%` : "&mdash;"}</span><span class="metric-spark">${renderSparkline(data.metricHistory.congruencyPct)}</span></div>
          <div class="metric-label">Congruency</div>
        </div>
      </div>`;
  }

  // --- Recommended Actions content (for tab) ---
  let recommendationsContent = "";
  if (data.synthesisTopActions.length > 0) {
    const escHtml = (s: string): string =>
      s.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;");

    const viewDetails = data.synthesisReportPath
      ? ` <a class="view-details-link" data-report-path="${escHtml(data.synthesisReportPath)}">View Details</a>`
      : "";

    const actionItems = data.synthesisTopActions
      .map((a) => {
        const tagsHtml = a.tags.length > 0
          ? " " + a.tags.map((t) => `<span class="tag-pill tag-${t}">${escHtml(t)}</span>`).join("")
          : "";
        return `<li>${escHtml(a.action)}${tagsHtml}</li>`;
      })
      .join("\n        ");

    const remaining = data.synthesisTotalActions - data.synthesisTopActions.length;
    const moreLabel = remaining > 0
      ? `<div class="more-actions">+${remaining} more recommendation${remaining === 1 ? "" : "s"}</div>`
      : "";

    recommendationsContent = `
      <div class="tab-header-row"><span class="tab-section-label">Recommendations (${data.synthesisTotalActions})</span>${viewDetails}</div>
      <ol class="actions-list">
        ${actionItems}
      </ol>
      ${moreLabel}`;
  } else {
    recommendationsContent = `<div class="muted">No recommendations available</div>`;
  }

  // --- Filtered recommendations helper ---
  const escHtmlTag = (s: string): string =>
    s.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;");

  function renderFilteredRecommendations(tag: string): string {
    const filtered = data.synthesisTopActions.filter((a) => a.tags.includes(tag));
    if (filtered.length === 0) return "";
    const items = filtered
      .map((a) => `<li>${escHtmlTag(a.action)}</li>`)
      .join("\n        ");
    return `
      <div class="tab-recos-section">
        <div class="tab-recos-label">Recommendations</div>
        <ol class="actions-list">${items}</ol>
      </div>`;
  }

  // --- Tab visuals content ---
  let impactContent = "";
  let coverageContent = "";
  let congruencyContent = "";
  let completenessContent = "";

  if (summary) {
    // Impact tab
    if (summary.impact.hasStats) {
      const impactViewDetails = summary.impact.reportPath
        ? ` <a class="view-details-link" data-report-path="${escapeAttr(summary.impact.reportPath)}">View Details</a>`
        : "";
      if (summary.impact.isVersioned) {
        impactContent = `<div class="tab-header-row"><span class="tab-section-label">Impact</span>${impactViewDetails}</div>${renderPieChart(summary.impact)}`;
      } else {
        impactContent = `<div class="tab-header-row"><span class="tab-section-label">Impact</span>${impactViewDetails}</div>
          <div class="summary-counts">
            <span class="count-value">${summary.impact.totalNodes}</span> nodes
            <span class="count-sep">&middot;</span>
            <span class="count-value">${summary.impact.totalEdges}</span> edges
          </div>`;
      }
    } else {
      impactContent = `<div class="muted">No impact data available</div>`;
    }

    // Coverage tab
    if (summary.coverage.hasData) {
      const covViewDetails = summary.coverage.reportPath
        ? ` <a class="view-details-link" data-report-path="${escapeAttr(summary.coverage.reportPath)}">View Details</a>`
        : "";
      coverageContent = `<div class="tab-header-row"><span class="tab-section-label">Coverage</span>${covViewDetails}</div>${renderCoverageBars(summary.coverage.rows)}`;
    } else {
      coverageContent = `<div class="muted">No coverage data available</div>`;
    }

    // Congruency tab
    if (summary.congruency.hasData) {
      const congViewDetails = summary.congruency.batchReportPath
        ? ` <a class="view-details-link" data-report-path="${escapeAttr(summary.congruency.batchReportPath)}">View Details</a>`
        : "";
      congruencyContent = `<div class="tab-header-row"><span class="tab-section-label">Congruency</span>${congViewDetails}</div>${renderCongruencyHeatmap(summary.congruency.cells)}`;
    } else {
      congruencyContent = `<div class="muted">No congruency data available</div>`;
    }

    // Completeness tab
    if (summary.coverage.completeness) {
      completenessContent = `<div class="tab-header-row"><span class="tab-section-label">Completeness</span></div>${renderCompletenessTriangle(summary.coverage.completeness)}`;
    } else {
      completenessContent = `<div class="muted">No completeness data available</div>`;
    }
  }

  // Append filtered recommendations beneath each tab's visual
  impactContent += renderFilteredRecommendations("impact");
  coverageContent += renderFilteredRecommendations("coverage");
  congruencyContent += renderFilteredRecommendations("congruency");
  completenessContent += renderFilteredRecommendations("completeness");

  // --- Build tabs section (only when project appgraph exists) ---
  type TabDef = { id: string; icon: string; label: string; content: string };
  const tabs: TabDef[] = [];
  if (data.synthesisTopActions.length > 0 || data.hasProjectAppgraph) {
    tabs.push({ id: "recommendations", icon: "lightbulb", label: "Recommendations", content: recommendationsContent });
  }
  if (data.hasProjectAppgraph && summary) {
    tabs.push({ id: "impact", icon: "zap", label: "Impact", content: impactContent });
    tabs.push({ id: "coverage", icon: "target", label: "Coverage", content: coverageContent });
    tabs.push({ id: "congruency", icon: "git-compare", label: "Congruency", content: congruencyContent });
    tabs.push({ id: "completeness", icon: "debug-disconnect", label: "Completeness", content: completenessContent });
  }
  if (advancedMetrics) {
    tabs.push({ id: "advanced", icon: "tools", label: "Advanced Metrics", content: renderAdvancedMetricsContent(advancedMetrics) });
  }

  let tabsHtml = "";
  if (tabs.length > 0) {
    const tabButtons = tabs
      .map((t, i) => `<button class="tab-btn${i === 0 ? " tab-active" : ""}" data-tab="${t.id}" data-tooltip="${t.label}"><i class="codicon codicon-${t.icon}"></i></button>`)
      .join("");

    const tabPanels = tabs
      .map((t, i) => `<div class="tab-panel${i === 0 ? " tab-panel-active" : ""}" data-tab-panel="${t.id}">${t.content}</div>`)
      .join("");

    tabsHtml = `
      <hr class="separator" />
      <div class="tab-bar">${tabButtons}</div>
      <div class="tab-panels">${tabPanels}</div>`;
  }

  return `<!DOCTYPE html>
