/**
 * Artifacts Explorer V2 — webview-based sidebar panel with real buttons,
 * collapsible tree, status icons, and filter toggle.
 */

import * as vscode from "vscode";
import * as path from "node:path";
import * as fs from "node:fs/promises";
import { ARTIFACTS_DIR } from "../core/mechanical/initialize-workflow.js";
import {
  loadManifest,
  refreshContentHashes,
  computeStaleness,
  saveManifest,
  getPipelineStatus,
  type ArtifactPipelineEntry,
} from "../core/mechanical/artifact-pipeline-manifest.js";
import { normalizeName } from "../core/mechanical/scan-artifacts.js";
import { getMiniAppGraphDir } from "../core/mechanical/extract-mini-appgraph.js";
import { detectClaudeCli } from "./bmad-manager.js";
import { getLatestAnalysisDir, findCongruencyReport } from "./appgraph-data.js";
import { getNonce } from "./html-utils.js";
import { log } from "./output-channel.js";
import { refresh as refreshContextView } from "./context-view.js";
import { logUsage } from "../core/analytics/telemetry.js";
import { getActiveFilter } from "./overview-view.js";

// ---------------------------------------------------------------------------
// Cleanup
// ---------------------------------------------------------------------------

/**
 * Remove associated extraction and analysis files when an artifact is deleted.
 * Best-effort: failures are logged but do not block the delete.
 */
async function cleanupArtifactFiles(workspaceRoot: string, normalizedName: string): Promise<void> {
  // 1. Remove mini-AppGraph directory
  const miniDir = getMiniAppGraphDir(workspaceRoot, normalizedName);
  try {
    await fs.rm(miniDir, { recursive: true });
  } catch { /* doesn't exist */ }

  // 2. Remove congruency reports from analysis directory
  const analysisDir = await getLatestAnalysisDir(workspaceRoot);
  if (analysisDir) {
    const prefixes = [
      `congruency-v2-${normalizedName}.`,           // V2: .json and .md
      `congruency-analysis-${normalizedName}-v`,     // V1: versioned .json and .md
    ];
    try {
      const entries = await fs.readdir(analysisDir);
      for (const entry of entries) {
        if (prefixes.some((p) => entry.startsWith(p))) {
          try {
            await fs.unlink(path.join(analysisDir, entry));
          } catch { /* ignore individual failures */ }
        }
      }
    } catch { /* analysis dir doesn't exist */ }
  }

  // 3. Remove entry from pipeline manifest
  try {
    const manifest = await loadManifest(workspaceRoot);
    if (manifest.artifacts[normalizedName]) {
      delete manifest.artifacts[normalizedName];
      await saveManifest(workspaceRoot, manifest);
    }
  } catch { /* manifest doesn't exist or save failed */ }
}

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

interface TreeNode {
  kind: "folder" | "file";
  name: string;
  relativePath: string;
  absolutePath: string;
  /** Pipeline status label: "integrated" | "out of date" | "analyzed" | "extracted" | "" */
  status: string;
  /** Codicon name for the status icon */
  statusIcon: string;
  /** CSS color class for the icon */
  statusColor: string;
  /** Whether this file is pending integration (used for filtering) */
  pending: boolean;
  /** Rich tooltip HTML for hover popup */
  tooltipHtml: string;
  /** Short tooltip for the status icon */
  iconTooltip: string;
  /** Whether to open in preview mode */
  preview: boolean;
  /** Absolute path to congruency report, if one exists */
  congruencyReportPath?: string;
  /** Children (folders only) */
  children?: TreeNode[];
}

const SKIP_FILES = new Set([".DS_Store", "Thumbs.db", "desktop.ini"]);

function formatShortDate(iso: string): string {
  try {
    const d = new Date(iso);
    return d.toLocaleDateString(undefined, { month: "short", day: "numeric" });
  } catch {
    return "";
  }
}

// ---------------------------------------------------------------------------
// Data loading
// ---------------------------------------------------------------------------

async function walkDir(root: string): Promise<string[]> {
  const results: string[] = [];
  async function walk(dir: string): Promise<void> {
    let entries;
    try {
      entries = await fs.readdir(dir, { withFileTypes: true });
    } catch {
      return;
    }
    for (const entry of entries) {
      if (entry.name.startsWith(".") || SKIP_FILES.has(entry.name)) continue;
      const fullPath = path.join(dir, entry.name);
      if (entry.isDirectory()) {
        await walk(fullPath);
      } else if (entry.isFile()) {
        results.push(path.relative(root, fullPath));
      }
    }
  }
  await walk(root);
  return results;
}

async function buildTreeData(workspaceRoot: string): Promise<TreeNode[]> {
  const artifactsDir = path.join(workspaceRoot, ARTIFACTS_DIR);

  try {
    await fs.access(artifactsDir);
  } catch {
    return [];
  }

  // Load pipeline manifest
  const pipelineEntries = new Map<string, ArtifactPipelineEntry>();
  try {
    const manifest = await loadManifest(workspaceRoot);
    const { manifest: updated, changed } = await refreshContentHashes(workspaceRoot, manifest);
    computeStaleness(updated);
    if (changed.length > 0) {
      await saveManifest(workspaceRoot, updated);
    }
    for (const entry of Object.values(updated.artifacts)) {
      pipelineEntries.set(entry.normalized_name, entry);
    }
  } catch {
    // Continue without pipeline data
  }

  // Load congruency report paths for analyzed artifacts
  const congruencyReports = new Map<string, string>();
  try {
    const analysisDir = await getLatestAnalysisDir(workspaceRoot);
    if (analysisDir) {
      for (const [name, entry] of pipelineEntries) {
        if (entry.analysis.status === "done" || entry.analysis.status === "stale") {
          const reportPath = await findCongruencyReport(analysisDir, name);
          if (reportPath) congruencyReports.set(name, reportPath);
        }
      }
    }
  } catch {
    // Non-critical
  }

  const allFiles = await walkDir(artifactsDir);
  if (allFiles.length === 0) return [];

  // Build nested tree structure
  const rootChildren: TreeNode[] = [];
  const folderMap = new Map<string, TreeNode>();

  // Ensure folder nodes exist for all directories
  function ensureFolder(relDir: string): TreeNode {
    if (relDir === ".") return { kind: "folder", name: "", relativePath: "", absolutePath: artifactsDir, status: "", statusIcon: "", statusColor: "", pending: false, tooltipHtml: "", iconTooltip: "", preview: false, children: rootChildren };
    const existing = folderMap.get(relDir);
    if (existing) return existing;

    const parentDir = path.dirname(relDir);
    const folder: TreeNode = {
      kind: "folder",
      name: path.basename(relDir),
      relativePath: relDir,
      absolutePath: path.join(artifactsDir, relDir),
      status: "",
      statusIcon: "folder",
      statusColor: "",
      pending: false,
      tooltipHtml: "",
      iconTooltip: "",
      preview: false,
      children: [],
    };
    folderMap.set(relDir, folder);

    // Attach to parent
    const parent = ensureFolder(parentDir);
    (parent.children ?? rootChildren).push(folder);

    return folder;
  }

  // Create file nodes
  for (const relPath of allFiles) {
    const normalizedName = normalizeName(relPath);
    const entry = pipelineEntries.get(normalizedName);
    const ext = path.extname(relPath).toLowerCase();
    const isPreviewable = ext === ".md" || ext === ".mmd" || ext === ".mermaid";

    let status = "";
    let statusIcon = "file";
    let statusColor = "";
    let iconTooltip = "";
    let pending = true;
    let tooltipHtml = "";

    if (entry) {
      const s = getPipelineStatus(entry);
      if (s.stale) {
        status = "out of date";
        statusIcon = "warning";
        statusColor = "warning";
        iconTooltip = "Out of date — content changed since last run";
        pending = true;
      } else if (s.integrated) {
        status = "integrated";
        statusIcon = "sparkle";
        statusColor = "success";
        iconTooltip = "Integrated into project context";
        pending = false;
      } else if (s.analyzed) {
        status = "analyzed";
        statusIcon = "beaker";
        statusColor = "success";
        iconTooltip = "Analyzed — ready to integrate";
        pending = true;
      } else if (s.extracted) {
        status = "extracted";
        statusIcon = "inbox";
        statusColor = "";
        iconTooltip = "Extracted — pending analysis";
        pending = true;
      } else {
        statusIcon = "inbox";
        iconTooltip = "Not yet processed";
      }

      // Rich HTML tooltip
      const statusLine = s.stale
        ? `<span class="codicon codicon-warning icon-warning"></span> <strong>Out of date</strong> — content changed since last run`
        : s.integrated
          ? `<span class="codicon codicon-sparkle icon-success"></span> <strong>Integrated</strong> into project context`
          : s.analyzed
            ? `<span class="codicon codicon-beaker icon-success"></span> <strong>Analyzed</strong> — ready to integrate`
            : s.extracted
              ? `<span class="codicon codicon-inbox"></span> <strong>Extracted</strong> — pending analysis`
              : `<span class="codicon codicon-inbox"></span> Not yet processed`;
      const extLine = `Extracted: ${entry.extraction.status}${entry.extraction.timestamp ? ` (${formatShortDate(entry.extraction.timestamp)})` : ""}`;
      const anaLine = `Analyzed: ${entry.analysis.status}${entry.analysis.timestamp ? ` (${formatShortDate(entry.analysis.timestamp)})` : ""}`;
      const intLine = `Integrated: ${entry.integration.status}${entry.integration.version ? ` (${entry.integration.version})` : ""}`;
      tooltipHtml = `<strong>${escapeHtml(path.basename(relPath))}</strong><br>${statusLine}<br><span class="tt-muted">${escapeHtml(extLine)}<br>${escapeHtml(anaLine)}<br>${escapeHtml(intLine)}</span>`;
    } else {
      status = "new";
      statusIcon = "inbox";
      iconTooltip = "New — not yet processed";
      tooltipHtml = `<strong>${escapeHtml(path.basename(relPath))}</strong><br><span class="codicon codicon-inbox"></span> New — not yet processed`;
    }

    const fileNode: TreeNode = {
      kind: "file",
      name: path.basename(relPath),
      relativePath: relPath,
      absolutePath: path.join(artifactsDir, relPath),
      status,
      statusIcon,
      statusColor,
      iconTooltip,
      pending,
      tooltipHtml,
      preview: isPreviewable,
      congruencyReportPath: congruencyReports.get(normalizedName),
    };

    const parentDir = path.dirname(relPath);
    if (parentDir === ".") {
      rootChildren.push(fileNode);
    } else {
      const parent = ensureFolder(parentDir);
      parent.children!.push(fileNode);
    }
  }

  // Sort: folders first, then alphabetical
  function sortChildren(nodes: TreeNode[]): void {
    nodes.sort((a, b) => {
      if (a.kind !== b.kind) return a.kind === "folder" ? -1 : 1;
      return a.name.localeCompare(b.name);
    });
    for (const n of nodes) {
      if (n.children) sortChildren(n.children);
    }
  }
  sortChildren(rootChildren);

  // Mark folders as pending if any descendant is pending
  function markFolderPending(node: TreeNode): boolean {
    if (node.kind === "file") return node.pending;
    let hasPending = false;
    for (const child of node.children ?? []) {
      if (markFolderPending(child)) hasPending = true;
    }
    node.pending = hasPending;
    return hasPending;
  }
  for (const node of rootChildren) {
    markFolderPending(node);
  }

  return rootChildren;
}

// ---------------------------------------------------------------------------
// HTML generation
// ---------------------------------------------------------------------------

function renderTreeHtml(nodes: TreeNode[], depth: number = 0): string {
  if (nodes.length === 0) return "";
  const items = nodes.map((node) => {
    const indent = depth * 16;
    const pendingAttr = node.pending ? "true" : "false";

    if (node.kind === "folder") {
      const childrenHtml = node.children ? renderTreeHtml(node.children, depth + 1) : "";
      return `<li class="tree-folder" data-pending="${pendingAttr}" data-status="${escapeAttr(node.status)}"
        <div class="tree-row folder-row" style="padding-left:${indent}px" title="${escapeAttr(node.name)}">
          <span class="codicon codicon-chevron-right folder-chevron"></span>
          <span class="codicon codicon-folder folder-icon"></span>
          <span class="tree-label">${escapeHtml(node.name)}</span>
          <span class="row-actions"><span class="row-action codicon codicon-trash" title="Delete folder" data-action="delete" data-delete-path="${escapeAttr(node.absolutePath)}" data-delete-name="${escapeAttr(node.name)}"></span></span>
        </div>
        <ul class="tree-children" style="display:none">${childrenHtml}</ul>
      </li>`;
    }

    const iconColorClass = node.statusColor ? ` icon-${node.statusColor}` : "";
    const iconTitle = node.iconTooltip ? ` title="${escapeAttr(node.iconTooltip)}"` : "";

    // Hover action buttons
    const actions: string[] = [];
    if (node.congruencyReportPath) {
      actions.push(`<span class="row-action codicon codicon-search" title="View congruency analysis" data-action="openReport" data-report-path="${escapeAttr(node.congruencyReportPath)}"></span>`);
    }
    actions.push(`<span class="row-action codicon codicon-trash" title="Delete artifact" data-action="delete" data-delete-path="${escapeAttr(node.absolutePath)}" data-delete-name="${escapeAttr(node.name)}"></span>`);
    const actionsHtml = `<span class="row-actions">${actions.join("")}</span>`;

    const tooltipData = node.tooltipHtml ? ` data-tooltip="${escapeAttr(node.tooltipHtml)}"` : "";
    return `<li class="tree-file" data-pending="${pendingAttr}" data-status="${escapeAttr(node.status)}" data-path="${escapeAttr(node.absolutePath)}" data-preview="${node.preview}">
      <div class="tree-row file-row" style="padding-left:${indent + 16}px"${tooltipData}>
        <span class="codicon codicon-${node.statusIcon}${iconColorClass} status-icon"${iconTitle}></span>
        <span class="tree-label">${escapeHtml(node.name)}</span>
        ${actionsHtml}
      </div>
    </li>`;
  });
  return items.join("\n");
}

function escapeHtml(s: string): string {
  return s.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
}

function escapeAttr(s: string): string {
  return s.replace(/&/g, "&amp;").replace(/"/g, "&quot;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
}

function getHtml(
  codiconCssUri: string,
  treeNodes: TreeNode[],
  cliAvailable: boolean,
  nonce: string,
  cspSource: string,
  initialCategory: "new" | "analyzed" | "integrated" | null = null,
  initialFilterEnabled = true,
): string {
  const treeHtml = renderTreeHtml(treeNodes);
  function countFiles(nodes: TreeNode[]): { total: number; pending: number } {
    let total = 0, pending = 0;
    for (const n of nodes) {
      if (n.kind === "file") { total++; if (n.pending) pending++; }
      else if (n.children) { const c = countFiles(n.children); total += c.total; pending += c.pending; }
    }
    return { total, pending };
  }
  const counts = countFiles(treeNodes);
  const generateBtnHtml = cliAvailable
    ? `<button class="action-btn action-btn-secondary action-btn-icon" data-command="alucify.generateArtifact" data-tooltip="Generate an artifact with Claude"><span class="codicon codicon-wand"></span></button>`
    : "";

  const emptyHtml = treeNodes.length === 0
    ? `<div class="empty-state">No artifacts found.<br>Import files to get started.</div>`
    : "";

  return `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <meta http-equiv="Content-Security-Policy" content="default-src 'none'; style-src ${cspSource} 'unsafe-inline'; font-src ${cspSource}; script-src 'nonce-${nonce}';">
  <link rel="stylesheet" href="${codiconCssUri}">
  <style>
    body {
      margin: 0;
      padding: 0;
      font-family: var(--vscode-font-family);
      font-size: var(--vscode-font-size);
      color: var(--vscode-foreground);
      background: transparent;
    }

    /* Button row */
    .button-row {
      display: flex;
      gap: 6px;
      padding: 8px 12px;
    }
    .action-btn {
      flex: 1;
      display: flex;
      align-items: center;
      justify-content: center;
      gap: 4px;
      padding: 4px 10px;
      border: none;
      border-radius: 4px;
      background: var(--vscode-button-background);
      color: var(--vscode-button-foreground);
      font-family: var(--vscode-font-family);
      font-size: var(--vscode-font-size);
      cursor: pointer;
      white-space: nowrap;
    }
    .action-btn:hover {
      background: var(--vscode-button-hoverBackground);
    }
    .action-btn-secondary {
      background: var(--vscode-button-secondaryBackground);
      color: var(--vscode-button-secondaryForeground);
      border: 1px solid var(--vscode-widget-border, transparent);
    }
    .action-btn-secondary:hover {
      background: var(--vscode-button-secondaryHoverBackground);
    }
    .action-btn-icon {
      flex: 0 0 auto;
      width: 28px;
      padding: 4px;
    }

    /* Toolbar */
    .toolbar {
      display: flex;
      align-items: center;
      gap: 2px;
      padding: 2px 8px 4px;
      border-bottom: 1px solid var(--vscode-panel-border);
    }
    .toolbar-title {
      flex: 1;
      font-size: 11px;
      text-transform: uppercase;
      letter-spacing: 0.04em;
      color: var(--vscode-foreground);
      opacity: 0.7;
    }
    .toolbar-btn {
      display: flex;
      align-items: center;
      justify-content: center;
      width: 22px;
      height: 22px;
      border: none;
      border-radius: 3px;
      background: transparent;
      color: var(--vscode-foreground);
      cursor: pointer;
      opacity: 0.8;
    }
    .toolbar-btn:hover {
      background: var(--vscode-toolbar-hoverBackground, rgba(90,93,94,0.31));
      opacity: 1;
    }
    .toolbar-btn.active {
      color: var(--vscode-focusBorder);
      opacity: 1;
    }

    /* Tree */
    .tree-root {
      list-style: none;
      margin: 0;
      padding: 0;
    }
    .tree-root ul {
      list-style: none;
      margin: 0;
      padding: 0;
    }
    .tree-row {
      display: flex;
      align-items: center;
      gap: 4px;
      padding: 2px 8px;
      cursor: pointer;
      user-select: none;
      white-space: nowrap;
      overflow: hidden;
      text-overflow: ellipsis;
      min-height: 22px;
    }
    .tree-row:hover {
      background: var(--vscode-list-hoverBackground);
    }
    .tree-label {
      overflow: hidden;
      text-overflow: ellipsis;
    }
    .tree-description {
      margin-left: auto;
      flex-shrink: 0;
      font-size: 0.9em;
      color: var(--vscode-descriptionForeground);
      padding-right: 4px;
    }

    /* Folder chevron */
    .folder-chevron {
      font-size: 12px;
      transition: transform 0.1s;
      flex-shrink: 0;
    }
    .tree-folder.open > .tree-row .folder-chevron {
      transform: rotate(90deg);
    }
    .tree-folder.open > .tree-row .folder-icon::before {
      content: "\\eaf7"; /* codicon-folder-opened */
    }
    .folder-icon {
      flex-shrink: 0;
    }

    /* Status icons */
    .status-icon {
      flex-shrink: 0;
    }

    /* Hover actions (delete, congruency report) */
    .row-actions {
      display: none;
      margin-left: auto;
      flex-shrink: 0;
      gap: 2px;
    }
    .tree-row:hover .row-actions {
      display: flex;
    }
    .tree-row:hover .tree-description {
      display: none;
    }
    .row-action {
      display: flex;
      align-items: center;
      justify-content: center;
      width: 20px;
      height: 20px;
      border-radius: 3px;
      font-size: 14px;
      color: var(--vscode-foreground);
      opacity: 0.7;
      cursor: pointer;
    }
    .row-action:hover {
      opacity: 1;
      background: var(--vscode-toolbar-hoverBackground, rgba(90,93,94,0.31));
    }

    /* Status icon colors */
    .icon-success {
      color: var(--vscode-testing-iconPassed, var(--vscode-charts-green, #4caf50));
    }
    .icon-warning {
      color: var(--vscode-list-warningForeground, var(--vscode-charts-yellow, #ff9800));
    }

    /* Filter: hide non-pending when active */
    .filter-active .tree-file[data-pending="false"] {
      display: none;
    }
    .filter-active .tree-folder[data-pending="false"] {
      display: none;
    }

    /* Category filter: new = new, out of date, extracted; analyzed = analyzed; integrated = integrated */
    .filter-category-new .tree-file:not([data-status="new"]):not([data-status="out of date"]):not([data-status="extracted"]):not([data-status=""]) {
      display: none;
    }
    .filter-category-analyzed .tree-file:not([data-status="analyzed"]) {
      display: none;
    }
    .filter-category-integrated .tree-file:not([data-status="integrated"]) {
      display: none;
    }
    /* Hide folders that have no visible children (JS will manage this) */
    .category-hidden {
      display: none !important;
    }

    /* Empty state for category filter */
    .category-empty {
      display: none;
      padding: 20px 16px;
      text-align: center;
      color: var(--vscode-descriptionForeground);
      line-height: 1.5;
    }
    .category-empty.visible {
      display: block;
    }

    /* Custom tooltip */
    .custom-tooltip {
      display: none;
      position: fixed;
      z-index: 100;
      max-width: 300px;
      padding: 6px 10px;
      border: 1px solid var(--vscode-editorHoverWidget-border, var(--vscode-panel-border));
      border-radius: 4px;
      background: var(--vscode-editorHoverWidget-background, var(--vscode-editor-background));
      color: var(--vscode-editorHoverWidget-foreground, var(--vscode-foreground));
      font-size: 12px;
      line-height: 1.5;
      pointer-events: none;
      box-shadow: 0 2px 8px rgba(0,0,0,0.2);
    }
    .custom-tooltip strong {
      font-weight: 600;
    }
    .custom-tooltip .tt-muted {
      color: var(--vscode-descriptionForeground);
      font-size: 11px;
    }
    .custom-tooltip .icon-success {
      color: var(--vscode-testing-iconPassed, var(--vscode-charts-green, #4caf50));
    }
    .custom-tooltip .icon-warning {
      color: var(--vscode-list-warningForeground, var(--vscode-charts-yellow, #ff9800));
    }

    /* Empty state */
    .empty-state {
      padding: 20px 16px;
      text-align: center;
      color: var(--vscode-descriptionForeground);
      line-height: 1.5;
    }
  </style>
</head>
<body>
  <div class="button-row">
    <button class="action-btn${treeNodes.length > 0 ? " action-btn-secondary" : ""}" data-command="alucify.importArtifact"><span class="codicon codicon-add"></span> Import Artifact</button>
    ${generateBtnHtml}
  </div>

  <div class="toolbar">
    <span class="toolbar-title" id="toolbarTitle" data-total="${counts.total}" data-pending="${counts.pending}">All Artifacts (${counts.total})</span>
    <button class="toolbar-btn${initialFilterEnabled && initialCategory ? " active" : ""}" id="filterBtn" title="Toggle filter">
      <span class="codicon codicon-filter"></span>
    </button>
    <button class="toolbar-btn" id="refreshBtn" title="Refresh">
      <span class="codicon codicon-refresh"></span>
    </button>
  </div>

  <div class="custom-tooltip" id="tooltip"></div>

  ${emptyHtml}
  <div class="category-empty" id="categoryEmpty">No artifacts in this state</div>
  <ul class="tree-root" id="treeRoot">
    ${treeHtml}
  </ul>

  <script nonce="${nonce}">
    const vscode = acquireVsCodeApi();

    // Action buttons
    document.querySelectorAll('.action-btn').forEach(btn => {
      btn.addEventListener('click', () => {
        const command = btn.getAttribute('data-command');
        if (command) vscode.postMessage({ type: 'command', command });
      });
    });

    // Folder expand/collapse
    document.querySelectorAll('.tree-folder').forEach(folder => {
      const row = folder.querySelector(':scope > .folder-row');
      if (row) {
        row.addEventListener('click', () => {
          folder.classList.toggle('open');
          const children = folder.querySelector(':scope > .tree-children');
          if (children) {
            children.style.display = folder.classList.contains('open') ? '' : 'none';
          }
        });
      }
    });

    // File click → open
    document.querySelectorAll('.tree-file').forEach(file => {
      const row = file.querySelector('.file-row');
      if (row) {
        row.addEventListener('click', () => {
          const filePath = file.getAttribute('data-path');
          const preview = file.getAttribute('data-preview') === 'true';
          if (filePath) {
            vscode.postMessage({ type: 'openFile', path: filePath, preview });
          }
        });
      }
    });

    // Category filter (driven by overview panel)
    const toolbarTitle = document.getElementById('toolbarTitle');
    const treeRoot = document.getElementById('treeRoot');
    const categoryEmpty = document.getElementById('categoryEmpty');
    const filterBtn = document.getElementById('filterBtn');
    const totalCount = parseInt(toolbarTitle.dataset.total, 10) || 0;
    let currentCategory = ${initialCategory ? `'${initialCategory}'` : "null"};
    let filterEnabled = ${initialFilterEnabled && initialCategory ? "true" : "false"};

    function renderFilter() {
      const active = filterEnabled ? currentCategory : null;
      // Remove all category classes
      treeRoot.className = treeRoot.className.replace(/filter-category-\\S+/g, '').trim();
      if (active) {
        treeRoot.classList.add('filter-category-' + active);
      }
      // Update folder visibility — hide folders with no visible file children
      document.querySelectorAll('.tree-folder').forEach(folder => {
        folder.classList.remove('category-hidden');
        if (active) {
          let hasVisible = false;
          folder.querySelectorAll('.tree-file').forEach(file => {
            const status = file.getAttribute('data-status');
            if (active === 'new') {
              hasVisible = hasVisible || status === 'new' || status === 'out of date' || status === 'extracted' || status === '';
            } else if (active === 'analyzed') {
              hasVisible = hasVisible || status === 'analyzed';
            } else if (active === 'integrated') {
              hasVisible = hasVisible || status === 'integrated';
            }
          });
          if (!hasVisible) folder.classList.add('category-hidden');
        }
      });
      // Count visible files and update toolbar title
      let visibleCount = totalCount;
      if (active) {
        visibleCount = 0;
        treeRoot.querySelectorAll('.tree-file').forEach(file => {
          const status = file.getAttribute('data-status');
          if (active === 'new') {
            if (status === 'new' || status === 'out of date' || status === 'extracted' || status === '') visibleCount++;
          } else if (active === 'analyzed') {
            if (status === 'analyzed') visibleCount++;
          } else if (active === 'integrated') {
            if (status === 'integrated') visibleCount++;
          }
        });
      }
      const labels = { new: 'Pending', analyzed: 'Analyzed', integrated: 'Integrated' };
      const label = active ? labels[active] || 'All Artifacts' : 'All Artifacts';
      toolbarTitle.textContent = label + ' (' + visibleCount + ')';
      // Show empty state if no visible files
      categoryEmpty.classList.toggle('visible', active && visibleCount === 0);
      // Update toggle button state
      filterBtn.classList.toggle('active', filterEnabled && !!currentCategory);
    }

    // Filter toggle button
    filterBtn.addEventListener('click', () => {
      if (!currentCategory) return;
      filterEnabled = !filterEnabled;
      renderFilter();
    });

    // Refresh
    document.getElementById('refreshBtn').addEventListener('click', () => {
      vscode.postMessage({ type: 'refresh' });
    });

    // Listen for messages from extension (e.g. programmatic filter toggle)
    window.addEventListener('message', (event) => {
      const msg = event.data;
      if (msg.type === 'setFilterCategory') {
        currentCategory = msg.category || null;
        if (msg.enabled !== undefined) filterEnabled = !!msg.enabled;
        renderFilter();
      }
    });

    // Rich tooltips
    const tooltip = document.getElementById('tooltip');
    let tooltipTimer = null;
    document.querySelectorAll('[data-tooltip]').forEach(row => {
      row.addEventListener('mouseenter', (e) => {
        const html = row.getAttribute('data-tooltip');
        if (!html) return;
        tooltipTimer = setTimeout(() => {
          tooltip.innerHTML = html;
          tooltip.style.display = 'block';
          const rect = row.getBoundingClientRect();
          tooltip.style.top = (rect.bottom + 4) + 'px';
          let left = rect.left + 16;
          const tipRect = tooltip.getBoundingClientRect();
          if (left + tipRect.width > document.documentElement.clientWidth) {
            left = document.documentElement.clientWidth - tipRect.width - 8;
          }
          tooltip.style.left = left + 'px';
        }, 400);
      });
      row.addEventListener('mouseleave', () => {
        clearTimeout(tooltipTimer);
        tooltip.style.display = 'none';
      });
    });

    // Row actions (delete, congruency report)
    document.querySelectorAll('.row-action').forEach(btn => {
      btn.addEventListener('click', (e) => {
        e.stopPropagation(); // Don't trigger row click (open file / toggle folder)
        const action = btn.getAttribute('data-action');
        if (action === 'delete') {
          const delPath = btn.getAttribute('data-delete-path');
          const delName = btn.getAttribute('data-delete-name');
          if (delPath) {
            vscode.postMessage({ type: 'deleteArtifact', path: delPath, name: delName });
          }
        } else if (action === 'openReport') {
          const reportPath = btn.getAttribute('data-report-path');
          if (reportPath) {
            vscode.postMessage({ type: 'openReport', path: reportPath });
          }
        }
      });
    });

    // Apply initial filter state baked into the HTML render
    renderFilter();
  </script>
</body>
</html>`;
}

// ---------------------------------------------------------------------------
// WebviewViewProvider
// ---------------------------------------------------------------------------

class ArtifactsWebviewProvider implements vscode.WebviewViewProvider {
  private view: vscode.WebviewView | undefined;
  private currentCategory: "new" | "analyzed" | "integrated" | null = null;
  private filterEnabled = true;

  constructor(
    private extensionUri: vscode.Uri,
    private workspaceRoot: string,
  ) {}

  resolveWebviewView(webviewView: vscode.WebviewView): void {
    this.view = webviewView;

    webviewView.webview.options = {
      enableScripts: true,
      localResourceRoots: [
        vscode.Uri.joinPath(this.extensionUri, "node_modules", "@vscode", "codicons", "dist"),
      ],
    };

    webviewView.onDidDispose(() => {
      this.view = undefined;
    });

    webviewView.webview.onDidReceiveMessage(async (msg) => {
      if (msg.type === "command" && typeof msg.command === "string") {
        logUsage("ui_action", { panel: "artifacts_explorer", action: "command", command: msg.command });
        vscode.commands.executeCommand(msg.command);
      } else if (msg.type === "openFile" && typeof msg.path === "string") {
        logUsage("ui_action", { panel: "artifacts_explorer", action: "open_file", file_type: path.extname(msg.path), preview: !!msg.preview });
        const uri = vscode.Uri.file(msg.path);
        const cmd = msg.preview ? "markdown.showPreview" : "vscode.open";
        vscode.commands.executeCommand(cmd, uri);
      } else if (msg.type === "openReport" && typeof msg.path === "string") {
        logUsage("ui_action", { panel: "artifacts_explorer", action: "open_report", report_type: "congruency" });
        const uri = vscode.Uri.file(msg.path);
        vscode.commands.executeCommand("markdown.showPreview", uri);
      } else if (msg.type === "deleteArtifact" && typeof msg.path === "string") {
        logUsage("ui_action", { panel: "artifacts_explorer", action: "delete_artifact" });
        const label = `Delete "${msg.name ?? path.basename(msg.path)}"?`;
        const confirmed = await vscode.window.showWarningMessage(label, { modal: true }, "Delete");
        if (confirmed !== "Delete") return;

        // Determine which normalized names need cleanup
        const artifactsDir = path.join(this.workspaceRoot, ARTIFACTS_DIR);
        const relativePath = path.relative(artifactsDir, msg.path);
        const namesToClean: string[] = [];

        try {
          const stat = await fs.stat(msg.path);
          if (stat.isDirectory()) {
            // Folder: find all manifest entries under this relative path
            try {
              const manifest = await loadManifest(this.workspaceRoot);
              const folderPrefix = relativePath + path.sep;
              for (const entry of Object.values(manifest.artifacts)) {
                if (entry.relative_path === relativePath || entry.relative_path.startsWith(folderPrefix)) {
                  namesToClean.push(entry.normalized_name);
                }
              }
            } catch { /* manifest unavailable */ }
            await fs.rm(msg.path, { recursive: true });
          } else {
            namesToClean.push(normalizeName(relativePath));
            await fs.unlink(msg.path);
          }
        } catch (err) {
          vscode.window.showErrorMessage(`Failed to delete: ${err}`);
        }

        // Clean up associated files (best-effort, non-blocking)
        for (const name of namesToClean) {
          await cleanupArtifactFiles(this.workspaceRoot, name);
        }

        // File watcher will auto-refresh; also update context view counts
        refreshContextView();
      } else if (msg.type === "refresh") {
        logUsage("ui_action", { panel: "artifacts_explorer", action: "refresh" });
        this.refresh();
      }
    });

    this.updateHtml();
  }

  async refresh(): Promise<void> {
    await this.updateHtml();
  }

  /** Set filter state programmatically from extension code. */
  setFilter(pendingOnly: boolean): void {
    this.view?.webview.postMessage({ type: "setFilter", active: pendingOnly });
  }

  /** Set category filter from overview panel. */
  setFilterCategory(category: "new" | "analyzed" | "integrated"): void {
    this.currentCategory = category;
    this.filterEnabled = true;
    this.view?.webview.postMessage({ type: "setFilterCategory", category, enabled: true });
  }

  private async updateHtml(): Promise<void> {
    if (!this.view) return;
    const codiconCssUri = this.view.webview.asWebviewUri(
      vscode.Uri.joinPath(this.extensionUri, "node_modules", "@vscode", "codicons", "dist", "codicon.css"),
    );
    const treeNodes = await buildTreeData(this.workspaceRoot);
    const cliAvailable = detectClaudeCli();
    const nonce = getNonce();
    const cspSource = this.view.webview.cspSource;
    // Use stored category, falling back to overview panel's active filter
    const category = this.currentCategory ?? getActiveFilter() ?? null;
    this.view.webview.html = getHtml(codiconCssUri.toString(), treeNodes, cliAvailable, nonce, cspSource, category, this.filterEnabled);
  }
}

// ---------------------------------------------------------------------------
// Module state
// ---------------------------------------------------------------------------

let viewProvider: ArtifactsWebviewProvider | undefined;
let fileWatcher: vscode.FileSystemWatcher | undefined;
let manifestWatcher: vscode.FileSystemWatcher | undefined;
let debounceTimer: ReturnType<typeof setTimeout> | undefined;

// ---------------------------------------------------------------------------
// Public API
// ---------------------------------------------------------------------------

export function register(context: vscode.ExtensionContext): void {
  const workspaceFolder = vscode.workspace.workspaceFolders?.[0];
  if (!workspaceFolder) return;

  const workspaceRoot = workspaceFolder.uri.fsPath;
  viewProvider = new ArtifactsWebviewProvider(context.extensionUri, workspaceRoot);

  context.subscriptions.push(
    vscode.window.registerWebviewViewProvider(
      "alucify.artifactsExplorerV2",
      viewProvider,
    ),
  );

  // Register import command (was previously in the old TreeView panel)
  const importCmd = vscode.commands.registerCommand(
    "alucify.importArtifact",
    async () => {
      const uris = await vscode.window.showOpenDialog({
        canSelectFiles: true,
        canSelectFolders: true,
        canSelectMany: true,
        openLabel: "Import",
        title: "Select files or folders to import as artifacts",
      });
      if (!uris || uris.length === 0) return;

      const artifactsDir = path.join(workspaceRoot, ARTIFACTS_DIR);
      await fs.mkdir(artifactsDir, { recursive: true });

      for (const uri of uris) {
        const srcPath = uri.fsPath;
        const destPath = path.join(artifactsDir, path.basename(srcPath));
        try {
          const stat = await fs.stat(srcPath);
          if (stat.isDirectory()) {
            await fs.cp(srcPath, destPath, { recursive: true });
          } else {
            await fs.copyFile(srcPath, destPath);
          }
        } catch (err) {
          vscode.window.showErrorMessage(
            `Failed to import "${path.basename(srcPath)}": ${err}`,
          );
        }
      }
      // File watcher will auto-refresh; also update context view counts
      refreshContextView();
    },
  );
  context.subscriptions.push(importCmd);

  const debouncedRefresh = (): void => {
    if (debounceTimer) clearTimeout(debounceTimer);
    debounceTimer = setTimeout(() => viewProvider?.refresh(), 500);
  };

  // Watch artifacts directory
  fileWatcher = vscode.workspace.createFileSystemWatcher(
    new vscode.RelativePattern(workspaceFolder, ".alucify/artifacts/**/*"),
  );
  fileWatcher.onDidCreate(debouncedRefresh);
  fileWatcher.onDidChange(debouncedRefresh);
  fileWatcher.onDidDelete(debouncedRefresh);
  context.subscriptions.push(fileWatcher);

  // Watch pipeline manifest
  manifestWatcher = vscode.workspace.createFileSystemWatcher(
    new vscode.RelativePattern(workspaceFolder, ".alucify/artifact-manifest.json"),
  );
  manifestWatcher.onDidChange(debouncedRefresh);
  manifestWatcher.onDidCreate(debouncedRefresh);
  context.subscriptions.push(manifestWatcher);

  // Initial load — flip context key so welcome content transitions
  viewProvider.refresh().then(
    () => vscode.commands.executeCommand("setContext", "alucify.artifactsLoaded", true),
    () => vscode.commands.executeCommand("setContext", "alucify.artifactsLoaded", true),
  );
}

export function refresh(): void {
  viewProvider?.refresh();
}

export function setFilter(pendingOnly: boolean): void {
  viewProvider?.setFilter(pendingOnly);
}

/** Set filter category from overview panel. */
export function setFilterCategory(category: "new" | "analyzed" | "integrated"): void {
  viewProvider?.setFilterCategory(category);
}

export function dispose(): void {
  if (debounceTimer) clearTimeout(debounceTimer);
  fileWatcher?.dispose();
  manifestWatcher?.dispose();
  viewProvider = undefined;
}

