{
  "name": "alucify-vscode",
  "displayName": "Alucify",
  "description": "Run AI agent workflows for artifact integration and project context generation",
  "version": "0.1.0",
  "publisher": "alucify",
  "license": "MIT",
  "icon": "resources/icon.png",
  "repository": {
    "type": "git",
    "url": "https://github.com/alucifyai/alucify-vs-extension"
  },
  "homepage": "https://github.com/alucifyai/alucify-vs-extension#readme",
  "bugs": {
    "url": "https://github.com/alucifyai/alucify-vs-extension/issues"
  },
  "keywords": [
    "AI",
    "agents",
    "artifacts",
    "appgraph",
    "knowledge-graph",
    "documentation",
    "requirements"
  ],
  "engines": {
    "vscode": "^1.85.0"
  },
  "categories": [
    "Machine Learning",
    "Other"
  ],
  "main": "./dist/extension.js",
  "activationEvents": [],
  "contributes": {
    "authentication": [
      {
        "id": "auth0",
        "label": "Alucify"
      }
    ],
    "commands": [
      {
        "command": "alucify.generateInitialContext",
        "title": "Generate Code Context",
        "category": "Alucify",
        "icon": "$(sparkle)"
      },
      {
        "command": "alucify.runArtifactIntegration",
        "title": "Update Project Context",
        "category": "Alucify",
        "icon": "$(play)"
      },
      {
        "command": "alucify.cancelWorkflow",
        "title": "Cancel Workflow",
        "category": "Alucify",
        "icon": "$(stop)"
      },
      {
        "command": "alucify.resumeWorkflow",
        "title": "Resume Workflow",
        "category": "Alucify",
        "icon": "$(debug-continue)"
      },
      {
        "command": "alucify.setApiKey",
        "title": "Set Anthropic API Key",
        "category": "Alucify",
        "icon": "$(key)"
      },
      {
        "command": "alucify.clearWorkflow",
        "title": "Clear Workflow",
        "category": "Alucify",
        "icon": "$(clear-all)"
      },
      {
        "command": "alucify.importArtifact",
        "title": "Import Artifact",
        "category": "Alucify",
        "icon": "$(add)"
      },
      {
        "command": "alucify.analyzeArtifacts",
        "title": "Analyze Artifacts",
        "category": "Alucify",
        "icon": "$(beaker)"
      },
      {
        "command": "alucify.analyzeCongruency",
        "title": "Analyze Congruency",
        "category": "Alucify",
        "icon": "$(search)"
      },
      {
        "command": "alucify.analyzeCoverage",
        "title": "Analyze Coverage",
        "category": "Alucify",
        "icon": "$(checklist)"
      },
      {
        "command": "alucify.analyzeImpact",
        "title": "Analyze Impact",
        "category": "Alucify",
        "icon": "$(zap)"
      },
      {
        "command": "alucify.analyzeFindings",
        "title": "Analyze Findings",
        "category": "Alucify",
        "icon": "$(lightbulb)"
      },
      {
        "command": "alucify.openCongruencyReport",
        "title": "View Congruency Analysis",
        "category": "Alucify",
        "icon": "$(search)"
      },
      {
        "command": "alucify.generateArtifact",
        "title": "Generate Artifact",
        "category": "Alucify",
        "icon": "$(wand)"
      },
      {
        "command": "alucify.installCodingAgents",
        "title": "Install Coding Agents",
        "category": "Alucify",
        "icon": "$(extensions)"
      },
      {
        "command": "alucify.switchAuthMode",
        "title": "Switch Auth Mode",
        "category": "Alucify",
        "icon": "$(key)"
      },
      {
        "command": "alucify.resetWelcome",
        "title": "Reset Welcome Screen",
        "category": "Alucify",
        "icon": "$(debug-restart)",
        "enablement": "config.alucify.advanced"
      },
      {
        "command": "alucify.signIn",
        "title": "Sign In",
        "category": "Alucify",
        "icon": "$(sign-in)"
      }
    ],
    "viewsContainers": {
      "activitybar": [
        {
          "id": "alucify",
          "title": "Alucify",
          "icon": "resources/icon.svg"
        }
      ]
    },
    "views": {
      "alucify": [
        {
          "id": "alucify.welcome",
          "type": "webview",
          "name": "Welcome",
          "when": "!alucify.welcomeDismissed"
        },
        {
          "id": "alucify.overview",
          "type": "webview",
          "name": "Overview",
          "when": "alucify.welcomeDismissed"
        },
        {
          "id": "alucify.context",
          "type": "webview",
          "name": "Project Context",
          "initialSize": 3,
          "when": "alucify.welcomeDismissed && alucify.overviewShowDetails"
        },
        {
          "id": "alucify.artifactAnalysis",
          "type": "webview",
          "name": "Artifact Analysis",
          "when": "alucify.welcomeDismissed && alucify.overviewShowAnalysis"
        },
        {
          "id": "alucify.artifactsExplorerV2",
          "type": "webview",
          "name": "Artifacts",
          "when": "alucify.welcomeDismissed"
        },
        {
          "id": "alucify.workflowStatus",
          "name": "Context Generation Status",
          "when": "alucify.welcomeDismissed && alucify.workflowVisible"
        }
      ]
    },
    "viewsWelcome": [],
    "menus": {
      "view/title": [
        {
          "command": "alucify.cancelWorkflow",
          "when": "view == alucify.workflowStatus && alucify.workflowRunning",
          "group": "navigation"
        },
        {
          "command": "alucify.resumeWorkflow",
          "when": "view == alucify.workflowStatus && alucify.workflowPaused && !alucify.workflowRunning",
          "group": "navigation"
        },
        {
          "command": "alucify.clearWorkflow",
          "when": "view == alucify.workflowStatus && !alucify.workflowRunning",
          "group": "navigation"
        },
        {
          "command": "alucify.generateInitialContext",
          "when": "view == alucify.context && config.alucify.advanced",
          "group": "1_workflows@1"
        },
        {
          "command": "alucify.runArtifactIntegration",
          "when": "view == alucify.context && config.alucify.advanced",
          "group": "1_workflows@2"
        },
        {
          "command": "alucify.analyzeCongruency",
          "when": "view == alucify.context && config.alucify.advanced",
          "group": "2_analysis@1"
        },
        {
          "command": "alucify.analyzeCoverage",
          "when": "view == alucify.context && config.alucify.advanced",
          "group": "2_analysis@2"
        },
        {
          "command": "alucify.analyzeImpact",
          "when": "view == alucify.context && config.alucify.advanced",
          "group": "2_analysis@3"
        },
        {
          "command": "alucify.analyzeFindings",
          "when": "view == alucify.context && config.alucify.advanced",
          "group": "2_analysis@4"
        },
        {
          "command": "alucify.switchAuthMode",
          "when": "view == alucify.overview",
          "group": "navigation"
        },
        {
          "command": "alucify.installCodingAgents",
          "when": "view == alucify.context && config.alucify.advanced && alucify.claudeCliAvailable && !alucify.codingAgentsInstalled",
          "group": "3_settings@1"
        }
      ],
      "view/item/context": [],
      "commandPalette": [
        {
          "command": "alucify.resetWelcome",
          "when": "config.alucify.advanced"
        }
      ]
    },
    "configuration": {
      "title": "Alucify",
      "properties": {
        "alucify.advanced": {
          "type": "boolean",
          "default": false,
          "description": "Enable advanced UI elements (workflow controls, analysis commands, baseline generation)"
        },
        "alucify.authMode": {
          "type": "string",
          "enum": [
            "apiKey",
            "claudeCode"
          ],
          "default": "apiKey",
          "description": "Authentication mode: 'apiKey' uses your Anthropic API key, 'claudeCode' uses your Claude Code subscription"
        },
        "alucify.telemetry": {
          "type": "boolean",
          "default": true,
          "description": "Send anonymous usage telemetry to help improve Alucify",
          "tags": [
            "telemetry",
            "usesOnlineServices"
          ]
        }
      }
    }
  },
  "dependencies": {
    "@anthropic-ai/claude-agent-sdk": "^0.2.50",
    "@anthropic-ai/sdk": "^0.39.0",
    "@vscode/codicons": "^0.0.44",
    "@vscode/tree-sitter-wasm": "^0.3.0",
    "ajv": "^8.17.1",
    "fast-glob": "^3.3.3",
    "gray-matter": "^4.0.3",
    "jsonrepair": "^3.13.2",
    "pdf-lib": "^1.17.1",
    "posthog-node": "^5.21.2",
    "unpdf": "^1.4.0"
  },
  "devDependencies": {
    "@types/node": "^20.0.0",
    "@types/vscode": "^1.85.0",
    "@vscode/vsce": "^3.2.0",
    "esbuild": "^0.24.0",
    "typescript": "^5.7.0",
    "vitest": "^2.1.0"
  },
  "scripts": {
    "prebuild": "node scripts/bundle-agents.mjs && node scripts/generate-agent-registry.mjs",
    "build": "node scripts/bundle-agents.mjs && node scripts/generate-agent-registry.mjs && node esbuild.config.mjs",
    "watch": "node esbuild.config.mjs --watch",
    "package": "vsce package",
    "test": "vitest run",
    "test:watch": "vitest"
  }
}

