/**
 * Provider-agnostic auth convenience wrapper.
 *
 * Consumers call getUser() / ensureSession() without knowing about Auth0
 * specifics. If the identity provider changes, only auth0Provider.ts changes.
 */

import * as vscode from "vscode";
import { AUTH_TYPE, SCOPES } from "./auth0Provider.js";

export interface AlucifyUser {
  /** Auth0 `sub` — stable unique identifier */
  id: string;
  /** Display name or email */
  label: string;
  /** Current access token */
  accessToken: string;
}

export class AuthService implements vscode.Disposable {
  private _onDidChangeUser = new vscode.EventEmitter<AlucifyUser | undefined>();
  readonly onDidChangeUser = this._onDidChangeUser.event;

  private _disposables: vscode.Disposable[] = [];

  constructor() {
    this._disposables.push(
      vscode.authentication.onDidChangeSessions((e) => {
        if (e.provider.id === AUTH_TYPE) {
          this.getUser().then((user) => this._onDidChangeUser.fire(user));
        }
      })
    );
  }

  /** Silent check — returns session if one exists, no prompt. */
  async getSession(): Promise<vscode.AuthenticationSession | undefined> {
    return vscode.authentication.getSession(AUTH_TYPE, SCOPES, {
      silent: true,
    });
  }

  /** Prompts user to sign in if no session exists. */
  async ensureSession(): Promise<vscode.AuthenticationSession> {
    const session = await vscode.authentication.getSession(
      AUTH_TYPE,
      SCOPES,
      { createIfNone: true }
    );
    return session;
  }

  /** Returns simplified user object or undefined. */
  async getUser(): Promise<AlucifyUser | undefined> {
    const session = await this.getSession();
    if (!session) return undefined;
    return {
      id: session.account.id,
      label: session.account.label,
      accessToken: session.accessToken,
    };
  }

  dispose(): void {
    this._onDidChangeUser.dispose();
    for (const d of this._disposables) {
      d.dispose();
    }
  }
}

