import * as vscode from "vscode";
import { registerCommands, checkForResumableWorkflow } from "./vscode/commands.js";
import { getOutputChannel } from "./vscode/output-channel.js";
import * as statusBar from "./vscode/status-bar.js";
import * as overviewView from "./vscode/overview-view.js";
import * as contextView from "./vscode/context-view.js";
import * as artifactAnalysisView from "./vscode/artifact-analysis-view.js";
import * as artifactsExplorerView from "./vscode/artifacts-webview-view.js";
import * as workflowStatusView from "./vscode/workflow-status-view.js";
import * as welcomeView from "./vscode/welcome-view.js";
import * as bmadManager from "./vscode/bmad-manager.js";
import { initTelemetry, logUsage, shutdownTelemetry, identifyUser, resetUser, setSuperProperties } from "./core/analytics/telemetry.js";
import { Auth0AuthProvider, AUTH_TYPE } from "./auth/auth0Provider.js";
import { AuthService } from "./auth/authService.js";

export function activate(context: vscode.ExtensionContext): void {
  initTelemetry(context);

  // --- Auth0 authentication ---
  const auth0Provider = new Auth0AuthProvider(context);
  context.subscriptions.push(
    vscode.authentication.registerAuthenticationProvider(
      AUTH_TYPE, "Alucify", auth0Provider,
      { supportsMultipleAccounts: false },
    ),
    auth0Provider,
  );

  const authService = new AuthService();
  context.subscriptions.push(authService);

  // Wire auth → PostHog telemetry
  const anonymousId = context.globalState.get<string>("alucify.telemetryId") ?? "";
  const wireUser = (user: { id: string; label: string } | undefined) => {
    if (user) {
      identifyUser(user.id);
      setSuperProperties({ user_id: user.id });
    } else if (anonymousId) {
      resetUser(anonymousId);
      setSuperProperties({ user_id: undefined });
    }
  };
  authService.onDidChangeUser(wireUser);
  authService.getUser().then(wireUser);

  // Sign-in command
  context.subscriptions.push(
    vscode.commands.registerCommand("alucify.signIn", async () => {
      try {
        await authService.ensureSession();
      } catch (e: any) {
        vscode.window.showErrorMessage(`Sign-in failed: ${e.message}`);
      }
    }),
  );

  // --- Extension setup ---
  const outputChannel = getOutputChannel();
  outputChannel.appendLine("Alucify extension activated.");

  const commands = registerCommands(context);
  context.subscriptions.push(...commands);
  context.subscriptions.push(outputChannel);
  context.subscriptions.push(statusBar.getStatusBarItem());
  welcomeView.register(context);
  overviewView.register(context);
  contextView.register(context);
  workflowStatusView.register(context);
  artifactAnalysisView.register(context);
  artifactsExplorerView.register(context);
  bmadManager.initialize();
  checkForResumableWorkflow();

  logUsage("extension_activated", {
    auth_mode: vscode.workspace.getConfiguration("alucify").get<string>("authMode", "apiKey"),
    advanced_mode: vscode.workspace.getConfiguration("alucify").get<boolean>("advanced", false),
  });
}

export async function deactivate(): Promise<void> {
  await shutdownTelemetry();
  statusBar.dispose();
  overviewView.dispose();
  contextView.dispose();
  workflowStatusView.dispose();
  artifactAnalysisView.dispose();
  artifactsExplorerView.dispose();
}

