      },
      {
        "command": "alucify.resumeWorkflow",
        "title": "Resume Workflow",
        "category": "Alucify",
        "icon": "$(debug-continue)"
      },
      {
        "command": "alucify.setApiKey",
        "title": "Set Anthropic API Key",
        "category": "Alucify",
        "icon": "$(key)"
      },
      {
        "command": "alucify.clearWorkflow",
        "title": "Clear Workflow",
        "category": "Alucify",
        "icon": "$(clear-all)"
      },
      {
        "command": "alucify.importArtifact",
        "title": "Import Artifact",
        "category": "Alucify",
        "icon": "$(add)"
      },
      {
        "command": "alucify.analyzeArtifacts",
        "title": "Analyze Artifacts",
        "category": "Alucify",
        "icon": "$(beaker)"
      },
