        },
        {
          "id": "alucify.overview",
          "type": "webview",
          "name": "Overview",
          "when": "alucify.welcomeDismissed"
        },
        {
          "id": "alucify.context",
          "type": "webview",
          "name": "Project Context",
          "initialSize": 3,
          "when": "alucify.welcomeDismissed && alucify.overviewShowDetails"
        },
        {
          "id": "alucify.artifactAnalysis",
          "type": "webview",
          "name": "Artifact Analysis",
          "when": "alucify.welcomeDismissed && alucify.overviewShowAnalysis"
