        },
        {
          "command": "alucify.resumeWorkflow",
          "when": "view == alucify.workflowStatus && alucify.workflowPaused && !alucify.workflowRunning",
          "group": "navigation"
        },
        {
          "command": "alucify.clearWorkflow",
          "when": "view == alucify.workflowStatus && !alucify.workflowRunning",
          "group": "navigation"
        },
        {
          "command": "alucify.generateInitialContext",
          "when": "view == alucify.context && config.alucify.advanced",
          "group": "1_workflows@1"
        },
        {
          "command": "alucify.runArtifactIntegration",
          "when": "view == alucify.context && config.alucify.advanced",
          "group": "1_workflows@2"
