287→    <button class="action-btn action-btn-secondary ${showAnalyze ? "" : "hidden"}" id="analyzeBtn" data-command="alucify.analyzeArtifacts" ${workflowRunning ? "disabled" : ""} data-tooltip="Extract and analyze pending artifacts to prepare them for integration into the project context.">
288→      <span class="codicon ${analyzeIcon}"></span> Analyze
289→    </button>
290→    <button class="action-btn ${showAnalyze ? "" : "hidden"}" id="integrateBtn" data-command="alucify.runArtifactIntegration" ${workflowRunning ? "disabled" : ""} data-tooltip="Integrate all analyzed artifacts into the project context. Pending artifacts will be auto-analyzed first.">
291→      <span class="codicon ${integrateIcon}"></span> Integrate
292→    </button>
293→    <button class="action-btn ${!showAnalyze && showIntegrate ? "" : "hidden"}" id="integrateSoloBtn" data-command="alucify.runArtifactIntegration" ${workflowRunning ? "disabled" : ""} data-tooltip="Integrate all analyzed artifacts into the project context. Pending artifacts will be auto-analyzed first.">
