300→  <script nonce="${nonce}">
301→    const vscode = acquireVsCodeApi();
302→
303→    // Column click → filter
304→    document.querySelectorAll('.col').forEach(col => {
305→      col.addEventListener('click', () => {
306→        const filter = col.getAttribute('data-filter');
307→        if (filter) {
