import * as vscode from "vscode";

function getConfig() {
  return vscode.workspace.getConfiguration("alucify");
}

export function isAdvancedMode(): boolean {
  return getConfig().get<boolean>("advanced", false);
}

const CODE_EXTENSIONS =
  "**/*.{ts,tsx,js,jsx,py,go,rs,java,kt,cs,rb,php,swift,dart,vue,svelte,cpp,c,h}";

export async function hasSourceCode(): Promise<boolean> {
  const files = await vscode.workspace.findFiles(
    CODE_EXTENSIONS,
    "**/node_modules/**",
    1,
  );
  return files.length > 0;
}

