// ---------------------------------------------------------------------------
// WebviewView Provider
// ---------------------------------------------------------------------------

class OverviewViewProvider implements vscode.WebviewViewProvider {
  private view: vscode.WebviewView | undefined;
  private runningWorkflowId: string | null = null;
  private activeFilter: OverviewFilter = "integrated";
  private filterInitialized = false;

  constructor(
    private extensionUri: vscode.Uri,
    private workspaceRoot: string,
  ) {}

  resolveWebviewView(webviewView: vscode.WebviewView): void {
    this.view = webviewView;

    webviewView.webview.options = {
      enableScripts: true,
      localResourceRoots: [
        vscode.Uri.joinPath(this.extensionUri, "node_modules", "@vscode", "codicons", "dist"),
      ],
    };

    webviewView.onDidDispose(() => {
      this.view = undefined;
    });

    webviewView.webview.onDidReceiveMessage((msg) => {
      if (msg.type === "setFilter" && typeof msg.filter === "string") {
        const filter = msg.filter as OverviewFilter;
        if (filter === this.activeFilter) return;
        this.activeFilter = filter;
        logUsage("ui_action", { panel: "overview", action: "filter", filter });
        applyFilter(filter);
      } else if (msg.type === "command" && typeof msg.command === "string") {
        logUsage("ui_action", { panel: "overview", action: "command", command: msg.command });
        vscode.commands.executeCommand(msg.command);
      }
    });

    this.updateHtml();
  }

  async refresh(): Promise<void> {
    await this.updateHtml();
  }

  setWorkflowRunning(workflowId: string | null): void {
    this.runningWorkflowId = workflowId;
    this.updateHtml();
  }

  getActiveFilter(): OverviewFilter {
    return this.activeFilter;
  }

  /** Programmatically select a column and apply its filter. */
  setActiveFilter(filter: OverviewFilter): void {
    this.activeFilter = filter;
    applyFilter(filter);
    this.updateHtml();
  }

  private async updateHtml(): Promise<void> {
    if (!this.view) return;
    const codiconCssUri = this.view.webview.asWebviewUri(
      vscode.Uri.joinPath(this.extensionUri, "node_modules", "@vscode", "codicons", "dist", "codicon.css"),
    );
    const counts = await loadPipelineCounts(this.workspaceRoot);

    // On first load, auto-select the rightmost column that has items
    if (!this.filterInitialized) {
      this.filterInitialized = true;
      const best: OverviewFilter =
        counts.integrated > 0 ? "integrated" :
        counts.analyzed > 0 ? "analyzed" : "new";
      this.activeFilter = best;
      applyFilter(best);
    }

    const nonce = getNonce();
    const cspSource = this.view.webview.cspSource;
    this.view.webview.html = getHtml(
      codiconCssUri.toString(), counts, this.activeFilter,
      this.runningWorkflowId, nonce, cspSource,
    );
  }
}

// ---------------------------------------------------------------------------
// Filter application
// ---------------------------------------------------------------------------

function applyFilter(filter: OverviewFilter): void {
  // Map filter to artifact panel category
  setFilterCategory(filter);

  // Control other panel visibility via context keys
  const showDetailPanels = filter === "integrated";
  vscode.commands.executeCommand("setContext", "alucify.overviewShowDetails", showDetailPanels);
  vscode.commands.executeCommand("setContext", "alucify.overviewShowAnalysis", filter === "analyzed");
}

// ---------------------------------------------------------------------------
// Module state
// ---------------------------------------------------------------------------

let viewProvider: OverviewViewProvider | undefined;
let fileWatcher: vscode.FileSystemWatcher | undefined;
let manifestWatcher: vscode.FileSystemWatcher | undefined;
let debounceTimer: ReturnType<typeof setTimeout> | undefined;

// ---------------------------------------------------------------------------
// Public API
// ---------------------------------------------------------------------------

export function register(context: vscode.ExtensionContext): void {
  const workspaceFolder = vscode.workspace.workspaceFolders?.[0];
  if (!workspaceFolder) return;

  const workspaceRoot = workspaceFolder.uri.fsPath;
  viewProvider = new OverviewViewProvider(context.extensionUri, workspaceRoot);

  context.subscriptions.push(
    vscode.window.registerWebviewViewProvider("alucify.overview", viewProvider),
  );

  // Set initial context key for detail panel visibility
  vscode.commands.executeCommand("setContext", "alucify.overviewShowDetails", true);

  const debouncedRefresh = (): void => {
    if (debounceTimer) clearTimeout(debounceTimer);
    debounceTimer = setTimeout(() => viewProvider?.refresh(), 500);
  };

  // Watch artifacts directory
  fileWatcher = vscode.workspace.createFileSystemWatcher(
    new vscode.RelativePattern(workspaceFolder, ".alucify/artifacts/**/*"),
  );
  fileWatcher.onDidCreate(debouncedRefresh);
  fileWatcher.onDidChange(debouncedRefresh);
  fileWatcher.onDidDelete(debouncedRefresh);
  context.subscriptions.push(fileWatcher);

  // Watch pipeline manifest
  manifestWatcher = vscode.workspace.createFileSystemWatcher(
    new vscode.RelativePattern(workspaceFolder, ".alucify/artifact-manifest.json"),
  );
  manifestWatcher.onDidChange(debouncedRefresh);
  manifestWatcher.onDidCreate(debouncedRefresh);
  context.subscriptions.push(manifestWatcher);

  // Also watch versions manifest so integrated count updates after workflow
  const versionsWatcher = vscode.workspace.createFileSystemWatcher(
    new vscode.RelativePattern(workspaceFolder, ".alucify/versions/manifest.json"),
  );
  versionsWatcher.onDidChange(debouncedRefresh);
  versionsWatcher.onDidCreate(debouncedRefresh);
  context.subscriptions.push(versionsWatcher);
}

export function refresh(): void {
  viewProvider?.refresh();
}

export function setWorkflowRunning(workflowId: string | null): void {
  viewProvider?.setWorkflowRunning(workflowId);
}

export function getActiveFilter(): OverviewFilter | undefined {
  return viewProvider?.getActiveFilter();
}

export function setActiveFilter(filter: OverviewFilter): void {
  viewProvider?.setActiveFilter(filter);
}

export function dispose(): void {
  if (debounceTimer) clearTimeout(debounceTimer);
  fileWatcher?.dispose();
  manifestWatcher?.dispose();
  viewProvider = undefined;
}

