/**
 * Overview pipeline panel — WebviewView showing the 3-column artifact pipeline
 * (New/Modified → Analyzed → Integrated) with counts, action buttons, and
 * click-to-filter behavior that controls other panel visibility.
 */

import * as vscode from "vscode";
import * as path from "node:path";
import * as fs from "node:fs/promises";
import {
  loadManifest,
  refreshContentHashes,
  computeStaleness,
  saveManifest,
  getPipelineStatus,
} from "../core/mechanical/artifact-pipeline-manifest.js";
import { BASELINE_PATH } from "../core/mechanical/initialize-workflow.js";
import { hasSourceCode } from "./config.js";
import { getNonce } from "./html-utils.js";
import { setFilterCategory } from "./artifacts-webview-view.js";
import { logUsage } from "../core/analytics/telemetry.js";

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

export type OverviewFilter = "new" | "analyzed" | "integrated";

interface PipelineCounts {
  newModified: number;
  analyzed: number;
  integrated: number;
}

// ---------------------------------------------------------------------------
// Data loading
// ---------------------------------------------------------------------------

async function loadPipelineCounts(workspaceRoot: string): Promise<PipelineCounts> {
  const counts: PipelineCounts = { newModified: 0, analyzed: 0, integrated: 0 };

  try {
    const manifest = await loadManifest(workspaceRoot);
    const { manifest: updated, changed } = await refreshContentHashes(workspaceRoot, manifest);
    computeStaleness(updated);
    if (changed.length > 0) {
      await saveManifest(workspaceRoot, updated);
    }

    for (const entry of Object.values(updated.artifacts)) {
      const s = getPipelineStatus(entry);

      if (s.stale) {
        // Content changed since last run — needs reprocessing
        counts.newModified++;
      } else if (s.integrated) {
        counts.integrated++;
      } else if (s.analyzed) {
        // Analyzed but not yet integrated
        counts.analyzed++;
      } else {
        // New, extracted-only, or unprocessed
        counts.newModified++;
      }
    }
  } catch {
    // No manifest yet — count raw artifact files
    try {
      const fs = await import("node:fs/promises");
      const { ARTIFACTS_DIR } = await import("../core/mechanical/initialize-workflow.js");
      const artifactsDir = path.join(workspaceRoot, ARTIFACTS_DIR);
      const entries = await fs.readdir(artifactsDir, { recursive: true, withFileTypes: true });
      counts.newModified = entries.filter((e) => e.isFile() && !e.name.startsWith(".")).length;
    } catch {
      // No artifacts directory
    }
  }

  return counts;
}

// ---------------------------------------------------------------------------
// HTML generation
// ---------------------------------------------------------------------------

function getHtml(
  codiconCssUri: string,
  counts: PipelineCounts,
  activeFilter: OverviewFilter,
  runningWorkflowId: string | null,
  nonce: string,
  cspSource: string,
  showCodeContext: boolean,
): string {
  const workflowRunning = runningWorkflowId !== null;
  const analyzeSpinning = runningWorkflowId === "mini-appgraph-extraction" || runningWorkflowId === "artifact-analysis";
  const integrateSpinning = runningWorkflowId === "artifact-integration";
  const codeContextSpinning = runningWorkflowId === "baseline-appgraph";

  const showAnalyze = counts.newModified > 0;
  const showIntegrate = counts.analyzed > 0 || counts.newModified > 0;

  const analyzeIcon = analyzeSpinning ? "codicon-loading codicon-modifier-spin" : "codicon-beaker";
  const integrateIcon = integrateSpinning ? "codicon-loading codicon-modifier-spin" : "codicon-play";

  const sel = (col: OverviewFilter) => col === activeFilter ? " selected" : "";

  return `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <meta http-equiv="Content-Security-Policy" content="default-src 'none'; style-src ${cspSource} 'unsafe-inline'; font-src ${cspSource}; script-src 'nonce-${nonce}';">
  <link rel="stylesheet" href="${codiconCssUri}">
  <style>
    body {
      margin: 0;
      padding: 10px 12px;
      font-family: var(--vscode-font-family);
      font-size: var(--vscode-font-size);
      color: var(--vscode-foreground);
      background: transparent;
    }

    .pipeline {
      display: flex;
      align-items: flex-start;
      gap: 0;
    }

    .col {
      flex: 1;
      display: flex;
      flex-direction: column;
      align-items: center;
      cursor: pointer;
      padding: 8px 4px;
      border-radius: 6px;
      border: 1px solid transparent;
      transition: border-color 0.15s, background 0.15s;
      min-width: 0;
    }
    .col:hover {
      background: var(--vscode-list-hoverBackground);
    }
    .col.selected {
      border-color: var(--vscode-focusBorder);
      background: color-mix(in srgb, var(--vscode-focusBorder) 8%, transparent);
    }

    .col-label {
      font-size: 10px;
      font-weight: 600;
      text-transform: uppercase;
      letter-spacing: 0.3px;
      color: var(--vscode-descriptionForeground);
      margin-bottom: 6px;
      text-align: center;
      white-space: nowrap;
      overflow: hidden;
      text-overflow: ellipsis;
      max-width: 100%;
    }

    .col-count {
      width: 40px;
      height: 40px;
      border-radius: 50%;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 16px;
      font-weight: 600;
      border: 2px solid var(--vscode-panel-border, rgba(128,128,128,0.35));
      color: var(--vscode-foreground);
      background: var(--vscode-editor-background, transparent);
    }
    .col.selected .col-count {
      border-color: var(--vscode-focusBorder);
    }
    .col-count.has-items {
      color: var(--vscode-foreground);
    }
    .col-count.empty {
      color: var(--vscode-descriptionForeground);
      opacity: 0.5;
    }

    .arrow {
      /* Mirror .col structure so arrow-icon aligns with col-count */
      display: flex;
      flex-direction: column;
      align-items: center;
      flex-shrink: 0;
      /* Match .col: 8px padding-top + 1px border-top */
      padding-top: 9px;
      color: var(--vscode-descriptionForeground);
      opacity: 0.5;
      font-size: 14px;
    }
    .arrow-spacer {
      /* Match .col-label: 10px font, ~14px line-height, 6px margin-bottom */
      font-size: 10px;
      line-height: 1;
      letter-spacing: 0.3px;
      margin-bottom: 6px;
      visibility: hidden;
    }
    .arrow-icon {
      height: 40px;
      display: flex;
      align-items: center;
    }

    .actions {
      display: flex;
      gap: 6px;
      margin-top: 10px;
      padding: 0 2px;
    }
    .action-btn {
      flex: 1;
      display: flex;
      align-items: center;
      justify-content: center;
      gap: 5px;
      padding: 5px 10px;
      border: none;
      border-radius: 4px;
      background: var(--vscode-button-background);
      color: var(--vscode-button-foreground);
      font-family: var(--vscode-font-family);
      font-size: var(--vscode-font-size);
      cursor: pointer;
      white-space: nowrap;
    }
    .action-btn:hover:not(:disabled) {
      background: var(--vscode-button-hoverBackground);
    }
    .action-btn:disabled {
      opacity: 0.5;
      cursor: default;
    }
    .action-btn-secondary {
      background: var(--vscode-button-secondaryBackground);
      color: var(--vscode-button-secondaryForeground);
      border: 1px solid var(--vscode-widget-border, transparent);
    }
    .action-btn-secondary:hover:not(:disabled) {
      background: var(--vscode-button-secondaryHoverBackground);
    }

    .hidden { display: none !important; }

    /* Custom tooltip */
    .custom-tooltip {
      display: none;
      position: fixed;
      z-index: 100;
      max-width: 260px;
      padding: 6px 10px;
      border: 1px solid var(--vscode-editorHoverWidget-border, var(--vscode-panel-border));
      border-radius: 4px;
      background: var(--vscode-editorHoverWidget-background, var(--vscode-editor-background));
      color: var(--vscode-editorHoverWidget-foreground, var(--vscode-foreground));
      font-size: 12px;
      line-height: 1.5;
      pointer-events: none;
      box-shadow: 0 2px 8px rgba(0,0,0,0.2);
    }
  </style>
</head>
<body>
  <div class="pipeline">
    <div class="col${sel("new")}" data-filter="new" data-tooltip="Artifacts that are new or have changed since last analysis.">
      <div class="col-label">Pending</div>
      <div class="col-count ${counts.newModified > 0 ? "has-items" : "empty"}">${counts.newModified}</div>
    </div>
    <div class="arrow"><div class="arrow-spacer">&nbsp;</div><div class="arrow-icon"><span class="codicon codicon-arrow-right"></span></div></div>
    <div class="col${sel("analyzed")}" data-filter="analyzed" data-tooltip="Artifacts that have been analyzed but not yet integrated into the project context.">
      <div class="col-label">Analyzed</div>
      <div class="col-count ${counts.analyzed > 0 ? "has-items" : "empty"}">${counts.analyzed}</div>
    </div>
    <div class="arrow"><div class="arrow-spacer">&nbsp;</div><div class="arrow-icon"><span class="codicon codicon-arrow-right"></span></div></div>
    <div class="col${sel("integrated")}" data-filter="integrated" data-tooltip="Artifacts that are part of the latest project context.">
      <div class="col-label">Integrated</div>
      <div class="col-count ${counts.integrated > 0 ? "has-items" : "empty"}">${counts.integrated}</div>
    </div>
  </div>

  <div class="actions">
    <button class="action-btn action-btn-secondary ${showAnalyze ? "" : "hidden"}" id="analyzeBtn" data-command="alucify.analyzeArtifacts" ${workflowRunning ? "disabled" : ""} data-tooltip="Extract and analyze pending artifacts to prepare them for integration into the project context.">
      <span class="codicon ${analyzeIcon}"></span> Analyze
    </button>
    <button class="action-btn ${showAnalyze ? "" : "hidden"}" id="integrateBtn" data-command="alucify.runArtifactIntegration" ${workflowRunning ? "disabled" : ""} data-tooltip="Integrate all analyzed artifacts into the project context. Pending artifacts will be auto-analyzed first.">
      <span class="codicon ${integrateIcon}"></span> Integrate
    </button>
    <button class="action-btn ${!showAnalyze && showIntegrate ? "" : "hidden"}" id="integrateSoloBtn" data-command="alucify.runArtifactIntegration" ${workflowRunning ? "disabled" : ""} data-tooltip="Integrate all analyzed artifacts into the project context. Pending artifacts will be auto-analyzed first.">
      <span class="codicon ${integrateIcon}"></span> Integrate
    </button>
  </div>

  <div class="custom-tooltip" id="tooltip"></div>

  <script nonce="${nonce}">
    const vscode = acquireVsCodeApi();

    // Column click → filter
    document.querySelectorAll('.col').forEach(col => {
      col.addEventListener('click', () => {
        const filter = col.getAttribute('data-filter');
        if (filter) {
          document.querySelectorAll('.col').forEach(c => c.classList.remove('selected'));
          col.classList.add('selected');
          vscode.postMessage({ type: 'setFilter', filter });
        }
      });
    });

    // Action buttons
    document.querySelectorAll('.action-btn').forEach(btn => {
      btn.addEventListener('click', () => {
        const command = btn.getAttribute('data-command');
        if (command) vscode.postMessage({ type: 'command', command });
      });
    });

    // Tooltips
    const tooltip = document.getElementById('tooltip');
    let tooltipTimer = null;
    document.querySelectorAll('[data-tooltip]').forEach(el => {
      el.addEventListener('mouseenter', () => {
        const text = el.getAttribute('data-tooltip');
        if (!text) return;
        tooltipTimer = setTimeout(() => {
          tooltip.textContent = text;
          tooltip.style.display = 'block';
          const rect = el.getBoundingClientRect();
          tooltip.style.top = (rect.bottom + 4) + 'px';
          let left = rect.left;
          const tipRect = tooltip.getBoundingClientRect();
          if (left + tipRect.width > document.documentElement.clientWidth) {
            left = document.documentElement.clientWidth - tipRect.width - 8;
          }
          if (left < 4) left = 4;
          tooltip.style.left = left + 'px';
        }, 400);
      });
      el.addEventListener('mouseleave', () => {
        clearTimeout(tooltipTimer);
        tooltip.style.display = 'none';
      });
    });
  </script>
</body>
</html>`;
}

// ---------------------------------------------------------------------------
// WebviewView Provider
// ---------------------------------------------------------------------------

class OverviewViewProvider implements vscode.WebviewViewProvider {
