304→        code,
305→        code_verifier: codeVerifier,
306→        redirect_uri: redirectUri,
307→      }),
308→    });
309→
310→    if (!response.ok) {
311→      const body = await response.text();
312→      throw new Error(`Token exchange failed: ${response.status} ${body}`);
313→    }
314→
315→    return (await response.json()) as Auth0TokenResponse;
316→  }
317→
318→  private async _refreshAccessToken(
319→    refreshToken: string
320→  ): Promise<Auth0TokenResponse> {
321→    const response = await fetch(`https://${AUTH0_DOMAIN}/oauth/token`, {
322→      method: "POST",
323→      headers: { "Content-Type": "application/json" },
324→      body: JSON.stringify({
325→        grant_type: "refresh_token",
326→        client_id: AUTH0_CLIENT_ID,
327→        refresh_token: refreshToken,
328→      }),
329→    });
330→
331→    if (!response.ok) {
332→      throw new Error(`Token refresh failed: ${response.status}`);
333→    }
334→
335→    return (await response.json()) as Auth0TokenResponse;
336→  }
337→
338→  private async _fetchUserInfo(accessToken: string): Promise<Auth0UserInfo> {
339→    const response = await fetch(`https://${AUTH0_DOMAIN}/userinfo`, {
340→      headers: { Authorization: `Bearer ${accessToken}` },
341→    });
342→
343→    if (!response.ok) {
344→      throw new Error(`UserInfo request failed: ${response.status}`);
345→    }
346→
347→    return (await response.json()) as Auth0UserInfo;
348→  }
349→
350→  // -------------------------------------------------------------------------
351→  // Session persistence
352→  // -------------------------------------------------------------------------
353→
354→  private async _loadSessions(): Promise<StoredSession[]> {
355→    if (this._sessionsLoaded) return this._sessions;
356→
357→    const raw = await this._context.secrets.get(SESSIONS_SECRET_KEY);
358→    this._sessions = raw ? JSON.parse(raw) : [];
359→    this._sessionsLoaded = true;
360→    return this._sessions;
361→  }
362→
363→  private async _saveSessions(): Promise<void> {
364→    await this._context.secrets.store(
365→      SESSIONS_SECRET_KEY,
366→      JSON.stringify(this._sessions)
367→    );
368→  }
369→
370→  private async _checkForSessionChanges(): Promise<void> {
371→    const previous = [...this._sessions];
372→    this._sessionsLoaded = false;
373→    const current = await this._loadSessions();
374→
375→    const previousIds = new Set(previous.map((s) => s.id));
376→    const currentIds = new Set(current.map((s) => s.id));
377→
378→    const added = current
379→      .filter((s) => !previousIds.has(s.id))
380→      .map((s) => this._toAuthSession(s));
381→    const removed = previous
382→      .filter((s) => !currentIds.has(s.id))
383→      .map((s) => this._toAuthSession(s));
384→
385→    if (added.length || removed.length) {
386→      this._sessionChangeEmitter.fire({ added, removed, changed: [] });
387→    }
388→  }
389→
390→  // -------------------------------------------------------------------------
391→  // Helpers
392→  // -------------------------------------------------------------------------
393→
394→  private _toAuthSession(
395→    stored: StoredSession
396→  ): vscode.AuthenticationSession {
397→    return {
398→      id: stored.id,
399→      accessToken: stored.accessToken,
400→      account: stored.account,
401→      scopes: stored.scopes,
402→    };
403→  }
404→
405→  dispose(): void {
406→    for (const d of this._disposables) {
407→      d.dispose();
408→    }
409→    this._sessionChangeEmitter.dispose();
410→  }
411→}
