/**
 * Auth0 AuthenticationProvider for VS Code.
 *
 * Implements OIDC Authorization Code flow with PKCE using VS Code's native
 * AuthenticationProvider API. Tokens are stored in SecretStorage (OS keychain).
 * No backend server required — Auth0 is the managed identity provider and the
 * extension acts as a public client.
 */

import * as vscode from "vscode";
import * as crypto from "crypto";

// ---------------------------------------------------------------------------
// Constants
// ---------------------------------------------------------------------------

export const AUTH_TYPE = "auth0";
export const AUTH_NAME = "Alucify";
export const SCOPES = ["openid", "email", "profile", "offline_access"];

const AUTH0_DOMAIN = "dev-5ui1ef3wc3s85sj1.us.auth0.com";
const AUTH0_CLIENT_ID = "hSSu5ZbBYo5zarGWSLNBGS5zqBZdDFnC";
const SESSIONS_SECRET_KEY = "auth0.sessions";
const AUTH_TIMEOUT_MS = 60_000;

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

interface StoredSession {
  id: string;
  accessToken: string;
  refreshToken: string;
  expiresAt: number;
  account: { id: string; label: string };
  scopes: string[];
}

interface Auth0TokenResponse {
  access_token: string;
  refresh_token?: string;
  id_token?: string;
  token_type: string;
  expires_in: number;
}

interface Auth0UserInfo {
  sub: string;
  email?: string;
  name?: string;
}

// ---------------------------------------------------------------------------
// PKCE utilities
// ---------------------------------------------------------------------------

function generateCodeVerifier(): string {
  return crypto.randomBytes(32).toString("base64url");
}

function generateCodeChallenge(verifier: string): string {
  return crypto.createHash("sha256").update(verifier).digest("base64url");
}

function generateState(): string {
  return crypto.randomBytes(16).toString("base64url");
}

// ---------------------------------------------------------------------------
// Auth0AuthProvider
// ---------------------------------------------------------------------------

export class Auth0AuthProvider
  implements vscode.AuthenticationProvider, vscode.Disposable
{
  private _sessionChangeEmitter =
    new vscode.EventEmitter<vscode.AuthenticationProviderAuthenticationSessionsChangeEvent>();
  readonly onDidChangeSessions = this._sessionChangeEmitter.event;

  private _disposables: vscode.Disposable[] = [];
  private _pendingCallbacks = new Map<
    string,
    { resolve: (code: string) => void; reject: (err: Error) => void }
  >();
  private _sessions: StoredSession[] = [];
  private _sessionsLoaded = false;

  constructor(private readonly _context: vscode.ExtensionContext) {
    // Register URI handler for Auth0 callback
    this._disposables.push(
      vscode.window.registerUriHandler({ handleUri: (uri) => this._handleUri(uri) })
    );

    // Cross-window session sync
    this._disposables.push(
      _context.secrets.onDidChange((e) => {
        if (e.key === SESSIONS_SECRET_KEY) {
          this._checkForSessionChanges();
        }
      })
    );
  }

  // -------------------------------------------------------------------------
  // AuthenticationProvider interface
  // -------------------------------------------------------------------------

  async getSessions(
    scopes?: readonly string[]
  ): Promise<vscode.AuthenticationSession[]> {
    const sessions = await this._loadSessions();

    const matched = scopes?.length
      ? sessions.filter((s) =>
          scopes.every((scope) => s.scopes.includes(scope))
        )
      : sessions;

    const result: vscode.AuthenticationSession[] = [];

    for (const stored of matched) {
      if (stored.expiresAt <= Date.now() && stored.refreshToken) {
        // Token expired — attempt refresh
        try {
          const refreshed = await this._refreshAccessToken(stored.refreshToken);
          stored.accessToken = refreshed.access_token;
          stored.expiresAt = Date.now() + refreshed.expires_in * 1000;
          if (refreshed.refresh_token) {
            stored.refreshToken = refreshed.refresh_token; // Auth0 token rotation
          }
          await this._saveSessions();
          this._sessionChangeEmitter.fire({
            added: [],
            removed: [],
            changed: [this._toAuthSession(stored)],
          });
        } catch {
          // Refresh failed — remove session
          this._sessions = this._sessions.filter((s) => s.id !== stored.id);
          await this._saveSessions();
          this._sessionChangeEmitter.fire({
            added: [],
            removed: [this._toAuthSession(stored)],
            changed: [],
          });
          continue;
        }
      }
      result.push(this._toAuthSession(stored));
    }

    return result;
  }

  async createSession(scopes: string[]): Promise<vscode.AuthenticationSession> {
    const codeVerifier = generateCodeVerifier();
    const codeChallenge = generateCodeChallenge(codeVerifier);
    const state = generateState();

    // Build callback URI (handles Remote/Codespaces)
    // Strip query params added by asExternalUri (e.g. ?windowId=N)
    const externalUri = await vscode.env.asExternalUri(
      vscode.Uri.parse(
        `${vscode.env.uriScheme}://alucify.alucify-vscode/callback`
      )
    );
    const callbackUri = externalUri.with({ query: "" });
    console.log("[Alucify Auth] Callback URI:", callbackUri.toString(true));

    const authorizeUrl = vscode.Uri.parse(
      `https://${AUTH0_DOMAIN}/authorize?` +
        `response_type=code` +
        `&client_id=${encodeURIComponent(AUTH0_CLIENT_ID)}` +
        `&redirect_uri=${encodeURIComponent(callbackUri.toString(true))}` +
        `&scope=${encodeURIComponent(scopes.join(" "))}` +
        `&code_challenge=${encodeURIComponent(codeChallenge)}` +
        `&code_challenge_method=S256` +
        `&state=${encodeURIComponent(state)}`
    );

    // Open browser
    await vscode.env.openExternal(authorizeUrl);

    // Wait for callback or timeout
    const codePromise = new Promise<string>((resolve, reject) => {
      this._pendingCallbacks.set(state, { resolve, reject });
    });
    let timeoutHandle: ReturnType<typeof setTimeout>;
    const timeoutPromise = new Promise<never>((_, reject) => {
      timeoutHandle = setTimeout(
        () => reject(new Error("Authentication timed out. Please try again.")),
        AUTH_TIMEOUT_MS
      );
    });

    let code: string;
    try {
      code = await Promise.race([codePromise, timeoutPromise]);
    } finally {
      clearTimeout(timeoutHandle!);
      this._pendingCallbacks.delete(state);
    }

    // Exchange code for tokens
    const tokens = await this._exchangeCodeForTokens(
      code,
      codeVerifier,
      callbackUri.toString(true)
    );

    // Fetch user info
    const userInfo = await this._fetchUserInfo(tokens.access_token);

    const session: StoredSession = {
      id: userInfo.sub,
      accessToken: tokens.access_token,
      refreshToken: tokens.refresh_token ?? "",
      expiresAt: Date.now() + tokens.expires_in * 1000,
      account: {
        id: userInfo.sub,
        label: userInfo.name || userInfo.email || userInfo.sub,
      },
      scopes,
    };

    // Remove any existing session for this user, then add the new one
    this._sessions = this._sessions.filter((s) => s.id !== session.id);
    this._sessions.push(session);
    await this._saveSessions();

    const authSession = this._toAuthSession(session);
    this._sessionChangeEmitter.fire({
      added: [authSession],
      removed: [],
      changed: [],
    });

    return authSession;
  }

  async removeSession(sessionId: string): Promise<void> {
    const session = this._sessions.find((s) => s.id === sessionId);
    if (!session) return;

    this._sessions = this._sessions.filter((s) => s.id !== sessionId);
    await this._saveSessions();

    // Best-effort Auth0 server-side logout
    try {
      await fetch(
        `https://${AUTH0_DOMAIN}/v2/logout?client_id=${encodeURIComponent(AUTH0_CLIENT_ID)}`
      );
    } catch {
      // Ignore — local session is already cleared
    }

    this._sessionChangeEmitter.fire({
      added: [],
      removed: [this._toAuthSession(session)],
      changed: [],
    });
  }

  // -------------------------------------------------------------------------
  // URI handler
  // -------------------------------------------------------------------------

  private _handleUri(uri: vscode.Uri): void {
    const query = new URLSearchParams(uri.query);
    const state = query.get("state");
    const code = query.get("code");
    const error = query.get("error");
    const errorDescription = query.get("error_description");

    if (!state) return;

    const pending = this._pendingCallbacks.get(state);
    if (!pending) return;

    if (error) {
      pending.reject(new Error(errorDescription || error));
    } else if (code) {
      pending.resolve(code);
    } else {
      pending.reject(new Error("No authorization code received"));
    }
  }

  // -------------------------------------------------------------------------
  // HTTP helpers
  // -------------------------------------------------------------------------

  private async _exchangeCodeForTokens(
    code: string,
    codeVerifier: string,
    redirectUri: string
  ): Promise<Auth0TokenResponse> {
    const response = await fetch(`https://${AUTH0_DOMAIN}/oauth/token`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        grant_type: "authorization_code",
        client_id: AUTH0_CLIENT_ID,
        code,
        code_verifier: codeVerifier,
        redirect_uri: redirectUri,
      }),
    });

    if (!response.ok) {
      const body = await response.text();
      throw new Error(`Token exchange failed: ${response.status} ${body}`);
    }

    return (await response.json()) as Auth0TokenResponse;
  }

  private async _refreshAccessToken(
    refreshToken: string
  ): Promise<Auth0TokenResponse> {
    const response = await fetch(`https://${AUTH0_DOMAIN}/oauth/token`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        grant_type: "refresh_token",
        client_id: AUTH0_CLIENT_ID,
        refresh_token: refreshToken,
      }),
    });

    if (!response.ok) {
      throw new Error(`Token refresh failed: ${response.status}`);
    }

    return (await response.json()) as Auth0TokenResponse;
  }

  private async _fetchUserInfo(accessToken: string): Promise<Auth0UserInfo> {
    const response = await fetch(`https://${AUTH0_DOMAIN}/userinfo`, {
      headers: { Authorization: `Bearer ${accessToken}` },
    });

    if (!response.ok) {
      throw new Error(`UserInfo request failed: ${response.status}`);
    }

    return (await response.json()) as Auth0UserInfo;
  }

  // -------------------------------------------------------------------------
  // Session persistence
  // -------------------------------------------------------------------------

  private async _loadSessions(): Promise<StoredSession[]> {
    if (this._sessionsLoaded) return this._sessions;

    const raw = await this._context.secrets.get(SESSIONS_SECRET_KEY);
    this._sessions = raw ? JSON.parse(raw) : [];
    this._sessionsLoaded = true;
    return this._sessions;
  }

  private async _saveSessions(): Promise<void> {
    await this._context.secrets.store(
      SESSIONS_SECRET_KEY,
      JSON.stringify(this._sessions)
    );
  }

  private async _checkForSessionChanges(): Promise<void> {
    const previous = [...this._sessions];
    this._sessionsLoaded = false;
    const current = await this._loadSessions();

    const previousIds = new Set(previous.map((s) => s.id));
    const currentIds = new Set(current.map((s) => s.id));

    const added = current
      .filter((s) => !previousIds.has(s.id))
      .map((s) => this._toAuthSession(s));
    const removed = previous
      .filter((s) => !currentIds.has(s.id))
      .map((s) => this._toAuthSession(s));

    if (added.length || removed.length) {
      this._sessionChangeEmitter.fire({ added, removed, changed: [] });
    }
  }

  // -------------------------------------------------------------------------
  // Helpers
  // -------------------------------------------------------------------------

  private _toAuthSession(
    stored: StoredSession
  ): vscode.AuthenticationSession {
    return {
      id: stored.id,
      accessToken: stored.accessToken,
      account: stored.account,
      scopes: stored.scopes,
    };
  }

  dispose(): void {
    for (const d of this._disposables) {
      d.dispose();
    }
    this._sessionChangeEmitter.dispose();
  }
}

