    // Strip query params added by asExternalUri (e.g. ?windowId=N)
    const externalUri = await vscode.env.asExternalUri(
      vscode.Uri.parse(
        `${vscode.env.uriScheme}://alucify.alucify-vscode/callback`
      )
    );
